/* eslint-disable @typescript-eslint/no-unused-vars */
import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import { TindakanTransfusiDarahModel } from '@/models/tindakan-transfusi-darah-model'
import { getMonitoringTransfusiDarah } from '@/services/monitoring-transfusi-darah'
import { constants } from '@/utils/constants'

interface ReportTindakanTransfusiDarahProps {
  isReport?: boolean
  noreg?: string
  norm?: string
  no?: string
}

const init: TindakanTransfusiDarahModel[] = []

const ReportTindakanTransfusiDarah = ({
  isReport,
  noreg,
  no,
}: ReportTindakanTransfusiDarahProps) => {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.tindakanTransfusiDarah, noreg!],
    queryFn: () =>
      getMonitoringTransfusiDarah({ no_reg: noreg!, kd_bagian: '' }),
    enabled: !!noreg,
  })

  const res = data?.response ?? init
  console.log('res', res)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res.length == 0) return <EmptyPlaceholder />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}
      <h1 className='text-center text-black font-semibold my-4'>
        TINDAKAN TRANSFUSI DARAH
      </h1>

      <div className='flex px-2'>
        <SimpleColumn name='No' className='text-xs flex-[0.5]' />
        <SimpleColumn name='Jenis Darah' className='text-xs flex-1' />
        <SimpleColumn name='Golongan Darah' className='text-xs flex-1' />
        <SimpleColumn name='No. Kantung' className='text-xs flex-1' />
        <SimpleColumn name='Reaksi' className='text-xs flex-1' />
        <SimpleColumn name='Tgl Kadaluarsa' className='text-xs flex-1' />
        <SimpleColumn isLast name='Perawat' className='text-xs flex-1 ' />
      </div>

      <div className='h-[50px]' />
    </LayoutBorderNo>
  )
}
export default ReportTindakanTransfusiDarah
