import type { Response } from '@/type'

import { get } from './api-2'

export interface ChecklistOperasi {
  no: string
  label: string
  col1: boolean
  col2: boolean
  col3: boolean
}

export interface Penandatangan {
  nama: string
  ttd: string
}

export interface VerifikasiPasienOperasi {
  jam_tiba_operasi: string
  ruang_rawat: string
  tanggal_operasi: string
  jam_keluar_operasi: string
  urutan_operasi: string
  lokasi_operasi: string
  lokasi_kiri: boolean
  lokasi_kanan: boolean
  bagian_operasi: string
  pre_operasi: ChecklistOperasi[]
  catatan_preoperasi: string
  paska_operasi: ChecklistOperasi[]
  catatan_paska_operasi: string
  pengantar_preoperasi: Penandatangan
  penerima_preoperasi1: Penandatangan
  penerima_preoperasi2: Penandatangan
  pengantar_paskaoperasi: Penandatangan
  penerima_paskaoperasi1: Penandatangan
  penerima_paskaoperasi2: Penandatangan
}

const getVerifikasiPasienOperasi = async ({
  no_reg,
  jk,
}: {
  no_reg: string
  jk: string
}): Promise<Response<VerifikasiPasienOperasi>> => {
  const params = { no_reg, jk }
  const response = await get('/v1/verifikasi-pasien-operasi', params, params)

  return response.data
}

export { getVerifikasiPasienOperasi }
