import { PemeriksaanLain } from '@/services/resume-medis'

const defaultData: PemeriksaanLain[] = [
  {
    tanggal: '04 November 2025',
    nama_kelompok: 'Tulang Kecil Wrist Joint Kiri',
    pemeriksaan: [
      {
        pemeriksaan: 'Tulang Kecil Wrist Joint Kiri',
        hasil:
          'Tampak fraktur di 1/3 distal os radius kiri dengan kedudukan jelek.\nTulang - tulang lain yang tervisualisasi baik.\nJaringan lunak kesan tenang.',
      },
      {
        pemeriksaan: 'Tulang Kecil Wrist Joint Kiri',
        hasil:
          'Tampak fraktur lama di 1/3 distal os radius kiri dengan kedudukan baik.\nTerpasang fiksasi interna.\nTulang - tulang lain yang tervisualisasi baik.\nJaringan lunak kesan tenang.',
      },
    ],
  },
]

function RecordCard({ record }: { record: PemeriksaanLain }) {
  return (
    <div style={{ marginBottom: 0 }}>
      {/* Grey header */}
      <div
        style={{
          background: '#b8b8b8',
          padding: '7px 10px',
          fontSize: 14,
          color: '#000',
          fontFamily: 'Arial, sans-serif',
          borderBottom: '1px solid #999',
        }}
      >
        Radiologi - Tanggal : {record.tanggal}
      </div>

      {/* Yellow sub-header */}
      <div
        style={{
          background: '#ffff99',
          padding: '7px 10px',
          fontSize: 14,
          fontWeight: 'bold',
          color: '#000',
          fontFamily: 'Arial, sans-serif',
          borderBottom: '1px solid #ccc',
        }}
      >
        Pemeriksaan : {record.nama_kelompok}
      </div>

      {/* White body — loop tiap item pemeriksaan */}
      {record.pemeriksaan.map((item, index) => (
        <div
          key={index}
          style={{
            background: '#fff',
            padding: '12px 10px 24px',
            fontFamily: 'Arial, sans-serif',
            fontSize: 13.5,
            minHeight: 100,
            borderBottom: '1px solid #999',
          }}
        >
          <div style={{ marginBottom: 12 }}>
            Hasil : <strong>{item.pemeriksaan}</strong>
          </div>
          <div style={{ whiteSpace: 'pre-line', lineHeight: 1.65 }}>
            {item.hasil}
          </div>
        </div>
      ))}
    </div>
  )
}

export default function PemeriksaanLainList({
  data,
}: {
  data?: PemeriksaanLain[]
}) {
  const records = data || defaultData

  return (
    <div
      className='w-full  max-w-none'
      style={{
        padding: '12px',
        fontFamily: 'Arial, sans-serif',
      }}
    >
      <div
        className='w-full  max-w-none'
        style={{
          border: '1px solid #999',
          maxWidth: 740,
        }}
      >
        {records.length === 0 ? (
          <div
            className='w-full  max-w-none'
            style={{ padding: 20, fontSize: 13 }}
          >
            Tidak ada data pemeriksaan.
          </div>
        ) : (
          records.map((record, index) => (
            <RecordCard key={index} record={record} />
          ))
        )}
      </div>
    </div>
  )
}
