import { useState } from 'react'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { constants } from '@/utils/constants'

import ButtonListGeriatri from './ButtonList'
import GeriatriReasesmen from './ListResikoJatuh'
import { getReasesmenGeriatri } from './geriatri'

interface ReasesmenResikoJatuhGeriatriProps {
  isReport?: boolean
  noreg?: string
}

const FormulirReasesmenGeriatri = ({
  noreg = '',
  isReport = true,
}: ReasesmenResikoJatuhGeriatriProps) => {
  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.reasesmenResikoJatuhGeriatri,
      noreg,
    ],
    queryFn: () =>
      getReasesmenGeriatri({
        noreg: noreg!,
      }),
    enabled: !!noreg,
  })

  const res = data?.response ?? []

  const [selectedIndex, setSelectedIndex] = useState(0)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo>
      {isReport && <ReportHeader />}
      <div className='p-4'>
        <ButtonListGeriatri
          items={res}
          onChange={(idx) => setSelectedIndex(idx)}
        />

        <h1 className='text-center text-black font-semibold mb-1 mt-4'>
          RESIKO JATUH GERIATRI (LEBIH DARI 60 TAHUN) - SYDNEY SCORING
        </h1>

        <p className='text-center'>
          Lakukan pengkajian (skoring) risiko jatuh pada saat pasien masuk,
          ketika terjadi perubahan kondisi pasien/therapi, saat pasien pindah
          ruangan lain, pasien risiko tinggi dikaji setiap 24 jam atau sesaat
          setelah terjadi kasus jatuh.
        </p>

        <br />

        <div className='mt-4'>
          {res && res.length > 0 && res[selectedIndex] ? (
            <GeriatriReasesmen data={res[selectedIndex]} />
          ) : (
            <div>Kosong</div>
          )}
        </div>
      </div>
    </LayoutBorderNo>
  )
}

export default FormulirReasesmenGeriatri
