import { post } from '@/services/api-2'
import type { Response } from '@/type'

export interface ReasesmenResikoJatuhAnak {
  tanggal: string
  jam: string
  total_skor: number
  keterangan: string
  nama_perawat: string
  umur: ResikoJatuh[]
  jenis_kelamin: ResikoJatuh[]
  diagnosa: ResikoJatuh[]
  gangguan_kognitif: ResikoJatuh[]
  faktor_lingkungan: ResikoJatuh[]
  respon_terhadap_pembedahan: ResikoJatuh[]
  penggunaan_obat: ResikoJatuh[]
}

export interface ResikoJatuh {
  keterangan: string
  skor: number
  is_active: boolean
}

const getResikoJatuhAnak = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<ReasesmenResikoJatuhAnak[]>> => {
  const response = await post(`/v1/reasesmen-resiko-jatuh-pada-anak/get`, {
    noreg: noreg,
  })

  return response.data
}

export { getResikoJatuhAnak }
