import { useState } from 'react'

import { Geriatri } from './geriatri'

type Props = {
  items: Geriatri[]
  onChange?: (index: number, item: Geriatri) => void
}

export default function ButtonListGeriatri({ items, onChange }: Props) {
  const [isActive, setIsActive] = useState<number>(0)

  // ⬅️ guard: kalau kosong, return null
  if (!items || items.length === 0) {
    return null
  }

  const handleClick = (index: number) => {
    setIsActive(index)
    onChange?.(index, items[index]) // ⬅️ kirim keluar
  }

  return (
    <div className='flex gap-2'>
      {items.map((item, index) => (
        <button
          key={index}
          onClick={() => handleClick(index)}
          className={`px-4 py-2 rounded ${
            isActive === index ? 'bg-green-500 text-white' : 'bg-gray-200'
          }`}
        >
          {item.tanggal}
        </button>
      ))}
    </div>
  )
}
