import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import { getInstruksiMedisFarmakologiReport } from '@/services/instruksi-medis-farmakologi'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDateTime } from '@/utils/formatDate'

interface InstruksiMedisFarmakologiProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export function InstruksiMedisFarmakologi({
  isReport = false,
  noreg = '',
  no,
}: InstruksiMedisFarmakologiProps) {
  const { pasien } = usePasienStore((state) => state)
  const noReg = noreg || pasien?.no_reg || ''

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.instruksiMedisFarmakologi, noReg],
    queryFn: () => getInstruksiMedisFarmakologiReport(noReg),
    enabled: !!noReg,
  })

  const res = data?.response ?? []

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          DAFTAR PEMBERIAN OBAT
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='flex mt-4'>
          <SimpleColumn name='No' className='text-xs flex-[0.3]' />
          <SimpleColumn name='Tanggal' className='text-xs flex-[0.8]' />
          <SimpleColumn name='Obat & Dosis' className='text-xs flex-[2]' />
          <SimpleColumn name='Jam Diberi' className='text-xs flex-[0.8]' />
          <SimpleColumn name='Frekuensi' className='text-xs flex-[0.7]' />
          <SimpleColumn name='Cara Pemberian' className='text-xs flex-1' />
          <SimpleColumn name='Perawat' className='text-xs flex-1' />
          <SimpleColumn name='Verifikasi' className='text-xs flex-1' isLast />
        </div>

        {res.length == 0 && <EmptyPlaceholder />}

        {res.map((item, index) => (
          <div className='flex' key={item.id ?? index}>
            <SimpleColumn
              name={`${index + 1}`}
              className='text-xs flex-[0.3]'
            />
            <SimpleColumn
              name={formatDateTime(item.insert_dttm)}
              className='text-xs flex-[0.8]'
            />
            <SimpleColumn
              name={`${item.nama_obat || '-'} | Dosis: ${
                item.dosis || '-'
              } | Jumlah: ${item.jumlah_obat ?? '-'} | Sisa: ${
                item.sisa_obat || '-'
              }`}
              className='text-xs flex-[2]'
            />
            <SimpleColumn
              name={
                item.jam_diberi
                  ? formatDateTime(item.jam_diberi)
                  : formatDateTime(item.insert_dttm)
              }
              className='text-xs flex-[0.8]'
            />
            <SimpleColumn
              name={item.frekuensi || '-'}
              className='text-xs flex-[0.7]'
            />
            <SimpleColumn
              name={item.cara_pemberian || '-'}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={item.user?.nama || '-'}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={`${item.nama_verifikasi || '-'}${
                item.keterangan_verifikasi
                  ? ` (${item.keterangan_verifikasi})`
                  : ''
              }`}
              className='text-xs flex-1'
              isLast
            />
          </div>
        ))}
      </div>
    </LayoutBorderNo>
  )
}
