import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import { getAnalisaData } from '@/services/analisa-data'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatTanggalISO } from '@/utils/date_helper'

interface AnalisaDataProps {
  isReport?: boolean
  no?: string
  noreg?: string
}

export default function FormulirAnalisaData({
  isReport = false,
  no = '',
  noreg = '',
}: AnalisaDataProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.analisaData, noreg],
    queryFn: () => getAnalisaData({ noreg }),
  })

  const res = data?.response != null ? data.response : null
  console.log(res)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0) return <EmptyPlaceholder />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className=' bg-white  px-2'>
        <h2 className='text-center mb-10 mt-3 text-xl font-semibold'>
          ANALISA DATA
        </h2>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='flex px-2'>
          <SimpleColumn name='No' className='text-xs flex-[0.5]' />
          <SimpleColumn name='Tanggal/Pukul' className='text-xs flex-1' />
          <SimpleColumn name='Data' className='text-xs flex-1' />
          <SimpleColumn
            name='Diagnosa Keperawatan'
            className='text-xs flex-1'
          />
          <SimpleColumn name='Nama Perawat' isLast className='text-xs flex-1' />
        </div>

        <div className='mb-2'>
          {res!.map((item, index) => (
            <div key={index} className='px-2 flex'>
              <SimpleColumn
                name={`${index + 1}`}
                className='text-xs flex-[0.5]'
              />
              <SimpleColumn
                name={`${formatTanggalISO(item.insert_dttm)}`}
                className='text-xs flex-1 text-center'
              />
              <SimpleColumn name={`${item.data}`} className='text-xs flex-1' />
              <SimpleColumn
                name={`${(item.analisa_data ?? []).map((item) => item.nama_diagnosa).join(', ')}`}
                className='text-xs flex-1'
              />
              <SimpleColumn
                hasQR={true}
                name={`${item.pegawai?.nama ?? '-'}`}
                isLast
                className='text-xs  flex-1'
              />
            </div>
          ))}
        </div>
      </div>
    </LayoutBorderNo>
  )
}
