import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import Text from '@/components/text'
import { getPermintaanDnr } from '@/services/dnr'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDateTime } from '@/utils/formatDate'

interface ReportPermintaanDnrProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportPermintaanDnr({
  isReport = false,
  noreg = '',
  no,
}: ReportPermintaanDnrProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.permintaanDnr,
      noreg,
      pasien?.no_rm,
    ],
    queryFn: () => getPermintaanDnr({ no_reg: noreg, no_rm: pasien!.no_rm }),
    enabled: !!noreg && !!pasien?.no_rm,
  })

  const res = data?.response

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return <EmptyPlaceholder />

  const permintaan = res.permintaan

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          PERMINTAAN PENOLAKAN TINDAKAN RESUSITASI
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='border border-black my-2 p-2'>
          <Text
            kStyle='min-w-[250px]'
            k='Yang Menyatakan'
            v={permintaan.nama_yang_menyatakan || permintaan.nama}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Hubungan dengan Pasien'
            v={permintaan.hubungan}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Umur / Tanggal Lahir'
            v={permintaan.umur}
          />
          <Text kStyle='min-w-[250px]' k='Alamat' v={permintaan.alamat} />
          <Text
            kStyle='min-w-[250px]'
            k='Jenis Kelamin'
            v={permintaan.jenis_kelamin}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Tanggal'
            v={formatDateTime(permintaan.tanggal)}
          />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='PERNYATAAN' />
          <p className='mt-2'>
            Dengan ini menyatakan dengan sesungguh-sungguhnya telah memberikan
            penolakan tindakan resusitasi kepada saya / keluarga saya sendiri,
            apabila suatu saat karena sakit yang saya / keluarga saya derita
            membutuhkan tindakan resusitasi.
          </p>
          <p className='mt-2'>
            Saya juga telah menyatakan dengan sesungguhnya bahwa saya:
          </p>
          <p className='mt-1'>
            • Telah diberikan informasi dan penjelasan serta risiko dan
            kemungkinan yang terjadi apabila tidak dilakukan tindakan
            resusitasi.
          </p>
          <p>
            • Telah paham sepenuhnya informasi dan penjelasan yang diberikan
            dokter.
          </p>
          <p>
            • Bertanggung jawab atas semua risiko yang ditimbulkan akibat
            pernyataan penolakan ini.
          </p>
        </div>

        <div className='grid grid-cols-2 gap-2 mt-4'>
          <div className='text-center'>
            <Text isHeader k='Yang Menyatakan' />
            <div className='h-14' />
            <p>{permintaan.nama_yang_menyatakan || permintaan.nama || '-'}</p>
          </div>
          <div className='text-center'>
            <Text isHeader k='Dokter Yang Menjelaskan' />
            <div className='h-14' />
            <p>{permintaan.nama_dokter || '-'}</p>
          </div>
        </div>

        <div className='grid grid-cols-2 gap-2 mt-4'>
          <div className='text-center'>
            <Text isHeader k='Saksi 1' />
            <div className='h-10' />
            <p>{permintaan.nama_saksi1 || '-'}</p>
          </div>
          <div className='text-center'>
            <Text isHeader k='Saksi 2' />
            <div className='h-10' />
            <p>{permintaan.nama_saksi2 || '-'}</p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
