import { Restrain } from '@/features/pemasangan-restrain/restrain'
import { TBAnak } from '@/features/tb-anak/tb-anak'
import { TindakanTransfusi } from '@/features/transfusi-darah/transfusi'
import type { Labor, Radiologi, Response } from '@/type'

import { post } from './api-2'

const getPemeriksaanLab = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<Labor[]>> => {
  const response = await post(`/v1/hasil-labor/get`, {
    no_reg: noreg,
  })

  return response.data
}

