import type { Response } from '@/type'

import { get } from './api-2'

export interface PersetujuanHiv {
  tanggal: string
  bertanda_tangan: {
    nama: string
    alamat: string
  }
  pasien: {
    nama: string
    tgl_lahir: string
    no_rm: string
    jenis_kelamin: string
    alamat: string
  }
  nama_perawat: string
  ttd_perawat: string
  ttd_pembuat_pernyataan: string
  nama_petugas_labor: string
  ttd_petugas_labor: string
}

const getPersetujuanHiv = async ({
  no_reg,
  no_rm,
}: {
  no_reg: string
  no_rm: string
}): Promise<Response<PersetujuanHiv>> => {
  const params = { no_reg, no_rm }
  const response = await get('/v1/persetujuan-permeriksaan-hiv', params, params)

  return response.data
}

export { getPersetujuanHiv }
