import { cn } from '@/lib/utils'
import { AsesmenAwalMedisIGD } from '@/models/asesmen-awal-medis-igd.model'

const TablePemeriksaanFisik = ({ data }: { data: AsesmenAwalMedisIGD }) => {
  const {
    mata,
    tht,
    mulut,
    leher,
    thyroid,
    dada,
    paru,
    jantung,
    perut,
    usus,
    kulit,
    anggota_gerak,
    ginjal,
    alat_kelamin,
    getah_bening,
    superior,
    inferior,
    hati,
    abdomen_lainnya,
    abdomen,
  } = data.fisik ?? {}

  return (
    <div>
      <Item
        left='Kepala'
        mid={
          <div className='flex flex-col flex-1'>
            <p className='border-b-[1px]  border-black p-1'>Mata</p>
            <p className='border-b-[1px]  border-black p-1'>THT</p>
            <p className='border-b-[0]  border-black p-1'>Mulut/Gigi</p>
          </div>
        }
        right={
          <div>
            <p className='p-1 border-black border-b-[1px] '>{mata}</p>
            <p className='p-1 border-black border-b-[1px] '>{tht}</p>
            <p className='p-1 border-b-[0] '>{mulut}</p>
          </div>
        }
      />
      <Item
        left='Leher'
        mid={
          <div className='flex flex-col flex-1'>
            <div>
              <p className='border-b-[1px] border-black p-1'>Thyroid</p>
              <p className='border-b-[1px] border-black p-1'>Leher</p>
              <p className='border-b-[0] border-black p-1'>Lain-lain</p>
            </div>
          </div>
        }
        right={
          <>
            <p className='p-1 border-black border-b-[1px]'>{thyroid ?? '-'}</p>
            <p className='p-1 border-black border-b-[1px]'>{leher}</p>
            <p className='p-1 border-b-[0]'>-</p>
          </>
        }
      />
      <Item
        left='Dada'
        mid={
          <div className='flex flex-col flex-1'>
            <div>
              <p className='border-b-[1px] border-black p-1'>Dinding Dada</p>
              <p className='border-b-[1px] border-black p-1'>Suara Jantung</p>
              <p className='border-b-[0] border-black p-1'>Suara Paru</p>
            </div>
          </div>
        }
        right={
          <>
            <p className='p-1 border-black border-b-[1px]'>{dada}</p>
            <p className='p-1 border-black border-b-[1px]'>{jantung}</p>
            <p className='p-1 border-b-[0]'>{paru}</p>
          </>
        }
      />
      <Item
        left='Abdomen'
        mid={
          <div className='flex flex-col flex-1'>
            <div>
              <p className='border-b-[1px] border-black p-1'>Abdomen</p>
              <p className='border-b-[1px] border-black p-1'>Dinding Perut</p>
              <p className='border-b-[1px] border-black p-1'>Hati / Lien</p>
              <p className='border-b-[1px] border-black p-1'>
                Peristaltik Usus
              </p>
              <p className='border-b-[0] border-black p-1'>Lain-lain</p>
            </div>
          </div>
        }
        right={
          <>
            <p className='p-1 border-black border-b-[1px]'>{abdomen}</p>
            <p className='p-1 border-black border-b-[1px]'>{perut}</p>
            <p className='p-1 border-black border-b-[1px]'>{hati}</p>
            <p className='p-1 border-black border-b-[1px]'>{usus}</p>
            <p className='p-1 border-b-[0]'>{abdomen_lainnya}</p>
          </>
        }
      />

      <Item
        left='Punggung'
        mid={
          <div className='flex flex-col flex-1'>
            <p className='border-b-[1px] border-black p-1'>Kulit</p>
            <p className='border-b-[0] border-black p-1'>CV, Ginjal</p>
          </div>
        }
        right={
          <>
            <p className='p-1 border-black border-b-[1px]'>{kulit}</p>
            <p className='p-1 border-b-[0]'>{ginjal}</p>
          </>
        }
      />
      <Item
        left='Kelanjar Getah Bening'
        mid={
          <div className='flex flex-col flex-1'>
            {/* <p className='border-b-[1px] border-black p-1'>Anggota Gerak</p> */}
          </div>
        }
        right={
          <>
            <p className='p-1  border-b-[1px]'>{getah_bening}</p>
          </>
        }
      />
      <Item
        left='Anggota Gerak'
        mid={
          <div className='flex flex-col flex-1'>
            {/* <p className='border-b-[1px] border-black p-1'>Anggota Gerak</p> */}
          </div>
        }
        right={
          <>
            <p className='p-1  border-b-[1px]'>{anggota_gerak}</p>
          </>
        }
      />
      <Item
        left='Genetalia'
        mid={<></>}
        right={
          <>
            <p className='p-1 border-black border-b-[0px]'>{alat_kelamin}</p>
          </>
        }
      />
      <Item
        isLast
        left='Extremitas'
        mid={
          <div className='flex flex-col flex-1'>
            <p className='border-b-[1px] border-black p-1'>Superior</p>
            <p className='border-b-[1px] border-black p-1'>Inferior</p>
          </div>
        }
        right={
          <>
            <p className='p-1 border-black border-b-[1px]'>{superior}</p>
            <p className='p-1 border-black border-b-[1px]'>{inferior}</p>
          </>
        }
      />
    </div>
  )
}

export default TablePemeriksaanFisik

const Item = ({
  left,
  mid,
  right,
  isLast = false,
}: {
  left: string
  mid: React.ReactNode
  right: React.ReactNode
  isLast?: boolean
}) => {
  return (
    <div className='flex'>
      <div
        className={cn(
          'flex border border-black border-b-0 px-2 min-w-[200px]',
          isLast && 'border-b-[1px]',
        )}
      >
        <p>{left}</p>
      </div>
      <div className='flex border border-black border-b-0 border-l-0 min-w-[100px]'>
        {mid}
      </div>
      <div className='flex flex-1 border border-black border-b-0 border-l-0'>
        <div className='flex-1'>{right}</div>
      </div>
    </div>
  )
}
