import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { constants } from '@/utils/constants'

import ReportHDComponent from './component/ReportHD'
import { getHD } from './report-hd'

interface HaemodialisaProps {
  isReport?: boolean
  noreg?: string
}

const FormulirHaemodialisa = ({ noreg = '' }: HaemodialisaProps) => {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.pengkajianHD, noreg],
    queryFn: () =>
      getHD({
        noreg: noreg!,
      }),
    enabled: !!noreg,
  })

  const res = data?.response ?? null

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo>
      <div className='p-4'>
        <ReportHeader />

        <h1 className='text-center text-black font-semibold mb-1 mt-3'>
          ASESMEN AWAL PASIEN HD
        </h1>

        <div className='mt-4'>
          <ReportHDComponent data={res} />
        </div>
      </div>
    </LayoutBorderNo>
  )
}

export default FormulirHaemodialisa
