import { ReasesmenResikoJatuhDewasa } from './reasesmen'

const SCHEMA = [
  {
    faktor: 'Riwayat jatuh',
    field: 'r_jatuh' as const,
    opsi: [
      { label: 'Ya', poin: 25 },
      { label: 'Tidak', poin: 0 },
    ],
  },
  {
    faktor: 'Diagnosis sekunder (≥ diagnosis medis)',
    field: 'diagnosis' as const,
    opsi: [
      { label: 'Ya', poin: 15 },
      { label: 'Tidak', poin: 0 },
    ],
  },
  {
    faktor: 'Bantuan ambulasi',
    field: 'ambulasi' as const,
    opsi: [
      { label: 'Furniture : dinding, meja, kursi, lemari', poin: 30 },
      { label: 'Kruk / tongkat / walker', poin: 15 },
      {
        label: 'Di tempat tidur / butuh bantuan perawat / memakai kursi roda',
        poin: 0,
      },
    ],
  },
  {
    faktor: 'Terpasang infuse',
    field: 'terpasang_infuse' as const,
    opsi: [
      { label: 'Ya', poin: 20 },
      { label: 'Tidak', poin: 0 },
    ],
  },
  {
    faktor: 'Gaya berjalan',
    field: 'gaya_berjalan' as const,
    opsi: [
      { label: 'Terganggu', poin: 20 },
      { label: 'Lemah', poin: 10 },
      { label: 'Normal / tirah baring / imobilisasi', poin: 0 },
    ],
  },
  {
    faktor: 'Status mental',
    field: 'status_mental' as const,
    opsi: [
      { label: 'Sering lupa akan keterbatasan yang dimiliki', poin: 15 },
      { label: 'Sadar akan kemampuan diri sendiri', poin: 0 },
    ],
  },
]

function getKategori(total: number) {
  if (total < 25)
    return { label: 'Tidak berisiko', color: 'bg-green-100 text-green-800' }
  if (total < 51)
    return { label: 'Risiko rendah', color: 'bg-yellow-100 text-yellow-800' }
  return { label: 'Risiko tinggi', color: 'bg-red-100 text-red-800' }
}

interface Props {
  data: ReasesmenResikoJatuhDewasa
}

export default function ReasesmenResikoJatuhDewasaReport({ data }: Props) {
  const kategori = getKategori(data.total)
  const tanggal = data.insertDttm?.split('T')[0] ?? '—'

  return (
    <div className='bg-white text-sm font-sans'>
      {/* Header */}
      <div className='flex justify-between items-start px-5 py-4 border-b border-gray-200'>
        <div></div>
        <div className='text-right text-xs grid grid-cols-2 gap-x-4 gap-y-0.5'>
          <span className='text-gray-400'>Tanggal</span>
          <span className='font-mono font-medium text-gray-800'>{tanggal}</span>
          <span className='text-gray-400'>Bagian</span>
          <span className='font-mono font-medium text-gray-800'>
            {data.kd_bagian}
          </span>
        </div>
      </div>
      <table
        className='w-full border-collapse'
        style={{ tableLayout: 'fixed' }}
      >
        <colgroup>
          <col style={{ width: '22%' }} />
          <col />
          <col style={{ width: '10%' }} />
          <col style={{ width: '10%' }} />
        </colgroup>
        <thead>
          <tr style={{ background: '#E8D5F0' }}>
            <th
              className='border border-gray-200 px-3 py-2 text-left text-lg font-medium'
              style={{ color: '#4A1B5E' }}
            >
              Faktor resiko
            </th>
            <th
              className='border border-gray-200 px-3 py-2 text-center text-lg font-medium'
              style={{ color: '#4A1B5E' }}
            >
              Skala
            </th>
            <th
              className='border border-gray-200 px-3 py-2 text-center text-lg font-medium'
              style={{ color: '#4A1B5E' }}
            >
              Poin
            </th>
            <th
              className='border border-gray-200 px-3 py-2 text-center text-lg font-medium'
              style={{ color: '#4A1B5E' }}
            >
              Hasil
            </th>
          </tr>
        </thead>
        <tbody>
          {SCHEMA.map(({ faktor, field, opsi }) => {
            // 1. Ambil nilai mentah dari data (misal: "Tidak" atau "Ya")
            const valueFromData = data[field]

            return opsi.map((opt, i) => {
              // 2. Perbaiki logika isSelected: bandingkan label opsi dengan data
              // Gunakan .toString() untuk berjaga-jaga jika tipe datanya campur
              const isSelected =
                valueFromData?.toString() === opt.label.toString()

              return (
                <tr key={`${field}-${i}`}>
                  {i === 0 && (
                    <td
                      rowSpan={opsi.length}
                      className='border border-gray-200 px-3 py-2 text-xs font-medium text-center text-gray-800 align-middle bg-white'
                    >
                      {faktor}
                    </td>
                  )}
                  <td
                    className={`border border-gray-200 px-3 py-2 text-xs align-middle ${
                      isSelected
                        ? 'bg-green-400 text-black font-bold'
                        : 'text-gray-700'
                    }`}
                  >
                    {opt.label}
                  </td>
                  <td className='border border-gray-200 px-3 py-2 text-center text-xs font-mono text-gray-500 align-middle'>
                    {opt.poin}
                  </td>

                  {/* Kolom Hasil (Checkmark) */}
                  {i === 0 && (
                    <td
                      rowSpan={opsi.length}
                      className='border border-gray-200 px-3 py-2 text-center align-middle'
                    >
                      {/* Cek apakah ada salah satu opsi di grup ini yang terpilih */}
                      {opsi.some((o) => o.label === valueFromData) && (
                        <span className='inline-flex items-center justify-center w-6 h-6 border-2 border-black rounded text-black font-bold'>
                          ✓
                        </span>
                      )}
                    </td>
                  )}
                </tr>
              )
            })
          })}
        </tbody>

        <tfoot>
          <tr className='bg-gray-50'>
            <td
              colSpan={3}
              className='border border-gray-200 px-4 py-2.5 text-right font-medium text-gray-800'
            >
              Total
            </td>
            <td className='border border-gray-200 px-3 py-2.5 text-center font-mono font-medium text-gray-900 text-base'>
              {data.total}
            </td>
          </tr>
        </tfoot>
      </table>

      {/* Kategori */}
      <div className='flex items-center gap-3 px-4 py-3 border-t border-gray-200'>
        <span className='text-xs text-gray-400'>Kategori:</span>
        <span
          className={`text-xs font-medium px-2.5 py-1 rounded ${kategori.color}`}
        >
          {kategori.label}
        </span>
      </div>
    </div>
  )
}
