import React from 'react'

/**
 * Interface untuk struktur data Downes Score
 * Berdasarkan sumber data: nifas, sianosis, retraksi, air_entry, merintih, total
 */
interface DownesScoreData {
  nifas?: number
  sianosis?: number
  retraksi?: number
  air_entry?: number
  merintih?: number
  total?: number
}

interface DownesScoreTableProps {
  data: DownesScoreData
}

interface ScoreRow {
  label: string
  key: keyof Omit<DownesScoreData, 'total'>
  v0: string
  v1: string
  v2: string
}

const DownesScoreTable: React.FC<DownesScoreTableProps> = ({ data }) => {
  // Fungsi pembantu untuk menentukan styling kotak skor sesuai Screenshot 2026-05-05 at 11.54.27.png
  const getBoxClass = (
    currentValue: number | undefined,
    targetValue: number,
  ): string => {
    const baseClass =
      'border rounded-md p-2 text-center text-[10px] h-full flex items-center justify-center transition-all '
    if (currentValue === targetValue) {
      return (
        baseClass + 'bg-green-800 text-white font-bold border-black shadow-md'
      )
    }
    return baseClass + 'bg-gray-50 text-black border-gray-300'
  }

  const rows: ScoreRow[] = [
    {
      label: 'Frekwensi Nafas',
      key: 'nifas',
      v0: '<60/menit',
      v1: '60-80/menit',
      v2: '>80/menit',
    },
    {
      label: 'Sianosis',
      key: 'sianosis',
      v0: 'Tidak Sianosi',
      v1: 'Sianosis hilang dengan O2',
      v2: 'Sianosis menetap walaupun diberi O2',
    },
    {
      label: 'Retraksi',
      key: 'retraksi',
      v0: 'Tidak ada retraksi',
      v1: 'Retraksi Ringan',
      v2: 'Retraksi Berat',
    },
    {
      label: 'Air Entry',
      key: 'air_entry',
      v0: 'Udara masuk bilateral baik',
      v1: 'Penurunan ringan udara masuk',
      v2: 'Tidak ada udara',
    },
    {
      label: 'Merintih',
      key: 'merintih',
      v0: 'Tidak merintih',
      v1: 'Dapat didengan dengan stetoskope',
      v2: 'Dapt didengar tanpa alat bantu',
    },
  ]

  return (
    <div className='w-full border border-black overflow-hidden bg-white mb-10'>
      <table className='w-full border-collapse'>
        <thead>
          <tr className='bg-gray-400 text-black uppercase text-xs'>
            <th className='border border-black p-2 w-[20%] text-left font-bold'>
              Parameter
            </th>
            <th className='border border-black p-2 w-[20%] font-bold'>
              Nilai 0
            </th>
            <th className='border border-black p-2 w-[20%] font-bold'>
              Nilai 1
            </th>
            <th className='border border-black p-2 w-[20%] font-bold'>
              Nilai 2
            </th>
            <th className='border border-black p-2 w-[20%] font-bold text-center'>
              Score
            </th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr key={row.key} className='border-b border-black last:border-b-0'>
              <td className='border-r border-black p-2 font-semibold text-xs bg-gray-50'>
                {row.label}
              </td>
              <td className='border-r border-black p-1 bg-white'>
                <div className={getBoxClass(data[row.key], 0)}>{row.v0}</div>
              </td>
              <td className='border-r border-black p-1 bg-white'>
                <div className={getBoxClass(data[row.key], 1)}>{row.v1}</div>
              </td>
              <td className='border-r border-black p-1 bg-white'>
                <div className={getBoxClass(data[row.key], 2)}>{row.v2}</div>
              </td>
              <td className='p-2 text-center font-bold text-lg bg-gray-50'>
                {data[row.key] ?? 0}
              </td>
            </tr>
          ))}
          {/* Baris Total sesuai Screenshot 2026-05-05 at 11.54.27.png */}
          <tr className='bg-gray-400'>
            <td className='border-r border-black p-2 font-bold text-xs uppercase'>
              Total
            </td>
            <td className='border-r border-black'></td>
            <td className='border-r border-black'></td>
            <td className='border-r border-black'></td>
            <td className='p-2 text-center font-black text-xl'>
              {data.total ?? 0}
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  )
}

export default DownesScoreTable
