// Converts JSON strings to/from your types
export class Convert {
  public static toNeonatus(json: string): Neonatus {
    return JSON.parse(json)
  }

  public static neonatusToJson(value: Neonatus): string {
    return JSON.stringify(value)
  }
}

const getNeonatus = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<Neonatus>> => {
  const response = await post(`/v2/neonatus/get`, {
    no_reg: noreg,
  })

  return response.data
}

export { getNeonatus }
