import { post } from '@/services/api-2'
import type { Response } from '@/type'

export interface IntervensiResikoJatuhAnak {
  tanggal: string
  ttd_pagi: Ttd
  ttd_sore: Ttd
  ttd_malam: Ttd
  intervensi: Intervensi[]
}

export interface Intervensi {
  no: number
  kategori: Kategori
  judul: string
  pagi: boolean
  sore: boolean
  malam: boolean
}

export enum Kategori {
  ResikoRendah = 'Resiko Rendah',
  ResikoSedangDanTinggi = 'Resiko Sedang dan Tinggi',
}

export interface Ttd {
  nama: string
  jam: string
}

export class Convert {
  public static toIntervensiResikoJatuhAnak(
    json: string,
  ): IntervensiResikoJatuhAnak {
    return JSON.parse(json)
  }

  public static intervensiResikoJatuhAnakToJson(
    value: IntervensiResikoJatuhAnak,
  ): string {
    return JSON.stringify(value)
  }
}

const getIntervensiAnak = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<IntervensiResikoJatuhAnak[]>> => {
  const response = await post(`/v1/intervensi-resiko-jatuh-anak/get`, {
    no_reg: noreg,
  })

  return response.data
}

export { getIntervensiAnak }
