import { FC } from 'react'
import QRCode from 'react-qr-code'

export type ResepHDType = 'inisiasi' | 'akut' | 'rutin' | 'pre_op' | 'sled'
export type DialisatType = 'asetat' | 'bicarbonat'
export type HeparnisasiType =
  | 'dosis_sirkulasi'
  | 'dosis_awal'
  | 'dosis_maintanance'
  | 'lmwh'
  | 'tanpa_heparin'
  | 'program_bilas'
export type DosisMainType = 'continue' | 'intermitten'

export interface MedicalInstructionValues {
  intervensi_koloborasi?: number[]
  resep_hd?: ResepHDType[]
  td_jam?: string
  qb_ml_mnt?: string
  qd_ml_mnt?: string
  uf_goal_ml?: string
  program_profiling_na?: boolean
  program_profiling_uf?: string
  program_profiling_bicarbonat?: string
  dialisat?: DialisatType[]
  dialisat_conductivity?: string
  dialisat_temperatur?: string
  heparnisasi?: HeparnisasiType[]
  dosis_sirkulasi_iu?: string
  dosis_awal_iu?: string
  dosis_maintanance_continue_iu?: string
  dosis_maintanance_type?: DosisMainType
  catatan_lain?: string
  dokter_nama?: string
  ttd_image?: string
}

export interface MedicalInstructionFormProps {
  values?: MedicalInstructionValues
}

interface CheckboxProps {
  checked: boolean
}

const Checkbox: FC<CheckboxProps> = ({ checked }) => (
  <span className='inline-flex items-center justify-center w-4 h-4 border border-gray-500 bg-white flex-shrink-0'>
    {checked && (
      <svg viewBox='0 0 10 10' className='w-3 h-3'>
        <polyline
          points='1.5,5 4,7.5 8.5,2'
          fill='none'
          stroke='#111'
          strokeWidth='1.8'
          strokeLinecap='round'
          strokeLinejoin='round'
        />
      </svg>
    )}
  </span>
)

interface InlineCheckboxProps {
  checked: boolean
  label?: string
}

const InlineCheckbox: FC<InlineCheckboxProps> = ({ checked, label }) => (
  <span className='inline-flex items-center gap-1'>
    <Checkbox checked={checked} />
    {label && <span className='text-xs'>{label}</span>}
  </span>
)

interface ValueCellProps {
  value?: string
  minW?: string
}

/** Underlined value display */
const Val: FC<ValueCellProps> = ({ value = '', minW = 'w-10' }) => (
  <span
    className={`inline-block border-b border-gray-600 text-center px-1 ${minW} text-xs`}
  >
    {value}
  </span>
)

// ─── Main component ───────────────────────────────────────────────────────────

/**
 * MedicalInstructionForm — View / Report Mode
 *
 * @example
 * <MedicalInstructionForm
 *   values={{
 *     intervensi_koloborasi: [1, 3],
 *     resep_hd: ["rutin"],
 *     td_jam: "5",
 *     qb_ml_mnt: "220",
 *     qd_ml_mnt: "500",
 *     uf_goal_ml: "1000",
 *     dialisat: ["bicarbonat"],
 *     dialisat_conductivity: "13.9",
 *     dialisat_temperatur: "37",
 *     heparnisasi: ["dosis_sirkulasi", "dosis_awal"],
 *     dosis_sirkulasi_iu: "2500",
 *     dosis_awal_iu: "2000",
 *     catatan_lain: "Pasien kooperatif",
 *     dokter_nama: "dr. F. Sahat Situmorang, SpPD",
 *   }}
 * />
 */
const MedicalInstructionForm: FC<MedicalInstructionFormProps> = ({
  values = {},
}) => {
  const {
    resep_hd = [],
    td_jam = '',
    qb_ml_mnt = '',
    qd_ml_mnt = '',
    uf_goal_ml = '',
    program_profiling_na = false,
    program_profiling_uf = '',
    program_profiling_bicarbonat = '',
    dialisat = [],
    dialisat_conductivity = '',
    dialisat_temperatur = '',
    heparnisasi = [],
    dosis_sirkulasi_iu = '',
    dosis_awal_iu = '',
    dosis_maintanance_continue_iu = '',
    dosis_maintanance_type,
    catatan_lain = '',
    dokter_nama = '',
  } = values

  return (
    <div className='bg-white font-sans text-xs text-gray-800'>
      {/* ════════════════════════════════════════
          SECTION 2 — INSTRUKSI MEDIS
      ════════════════════════════════════════ */}
      <div className='border-l border-r border-b border-gray-400'>
        <div className='border-b border-gray-400 px-3 py-2'>
          <span className='font-bold underline'>INTRUKSI MEDIS</span>
        </div>

        <div className='px-3 py-3 space-y-2'>
          {/* Resep HD row 1 */}
          <div className='flex items-center flex-wrap gap-x-3 gap-y-1'>
            <span className='shrink-0'>Resep HD :</span>
            <InlineCheckbox
              checked={resep_hd.includes('inisiasi')}
              label='Inisiasi'
            />
            <InlineCheckbox checked={resep_hd.includes('akut')} label='Akut' />
            <InlineCheckbox
              checked={resep_hd.includes('rutin')}
              label='Rutin'
            />
            <InlineCheckbox
              checked={resep_hd.includes('pre_op')}
              label='Pre-op'
            />
            <InlineCheckbox checked={resep_hd.includes('sled')} label='SLED' />
            <Checkbox checked={false} />
          </div>

          {/* Resep HD row 2 — numeric params */}
          <div className='flex items-center flex-wrap gap-x-4 gap-y-1 pl-14'>
            <span>TD:</span>
            <Val value={td_jam} minW='w-6' />
            <span>Jam</span>
            <span className='ml-2'>QB:</span>
            <Val value={qb_ml_mnt} minW='w-8' />
            <span>ml/mnt</span>
            <span className='ml-2'>QD :</span>
            <Val value={qd_ml_mnt} minW='w-8' />
            <span>ml/mnt</span>
            <span className='ml-2'>UF Goal :</span>
            <Val value={uf_goal_ml} minW='w-10' />
            <span>ml</span>
          </div>

          {/* Program Profiling + Dialisat */}
          <div className='flex items-start justify-between flex-wrap gap-2'>
            {/* Left: Program Profiling */}
            <div className='space-y-1.5'>
              <span>Program Profiling :</span>
              <div className='flex items-center gap-3 mt-1'>
                <InlineCheckbox checked={program_profiling_na} label='Na -' />
                <InlineCheckbox
                  checked={!!program_profiling_uf}
                  label={`UF ${program_profiling_uf || '200'}`}
                />
                <InlineCheckbox
                  checked={!!program_profiling_bicarbonat}
                  label={`Bicarbonat ${program_profiling_bicarbonat || '3,0'}`}
                />
              </div>
            </div>

            {/* Right: Dialisat */}
            <div className='space-y-1'>
              <span>Dialisat :</span>
              <div className='flex items-center gap-3 mt-1'>
                <InlineCheckbox
                  checked={dialisat.includes('asetat')}
                  label='Asetat'
                />
                <InlineCheckbox
                  checked={dialisat.includes('bicarbonat')}
                  label='Bicarbonat'
                />
              </div>
              <div className='flex items-center gap-2'>
                <Checkbox checked={!!dialisat_conductivity} />
                <span>Condactivity</span>
                <Val value={dialisat_conductivity || '13,9'} minW='w-10' />
              </div>
              <div className='flex items-center gap-2'>
                <Checkbox checked={!!dialisat_temperatur} />
                <span>Temperatur</span>
                <Val value={dialisat_temperatur || '37'} minW='w-8' />
                <span>°C</span>
              </div>
            </div>
          </div>

          {/* ── Heparnisasi ── */}
          <div className='pt-1'>
            <span className='font-bold'>Heparnisasi :</span>
          </div>

          <div className='space-y-1.5 pl-0'>
            {/* Dosis Sirkulasi */}
            <div className='flex items-center gap-3'>
              <Checkbox checked={heparnisasi.includes('dosis_sirkulasi')} />
              <span className='w-36'>Dosis Sirkulasi</span>
              <Val value={dosis_sirkulasi_iu || '2500'} minW='w-10' />
              <span>IU</span>
            </div>

            {/* Dosis Awal */}
            <div className='flex items-center gap-3'>
              <Checkbox checked={heparnisasi.includes('dosis_awal')} />
              <span className='w-36'>Dosis Awal</span>
              <Val value={dosis_awal_iu || '2000'} minW='w-10' />
              <span>IU</span>
            </div>

            {/* Dosis Maintanance */}
            <div className='flex items-start gap-3'>
              <Checkbox checked={heparnisasi.includes('dosis_maintanance')} />
              <span className='w-36 pt-0.5'>Dosis Maintanance:</span>
              <div className='space-y-1'>
                <div className='flex items-center gap-2'>
                  <Checkbox checked={dosis_maintanance_type === 'continue'} />
                  <span>Continue</span>
                  <Val
                    value={dosis_maintanance_continue_iu || '1000'}
                    minW='w-10'
                  />
                  <span>IU/Jam</span>
                </div>
                <div className='flex items-center gap-2'>
                  <Checkbox
                    checked={dosis_maintanance_type === 'intermitten'}
                  />
                  <span>Intermitten</span>
                  <Val value='' minW='w-10' />
                  <span>IU/Jam</span>
                </div>
              </div>
            </div>

            {/* LMWH */}
            <div className='flex items-center gap-2'>
              <Checkbox checked={heparnisasi.includes('lmwh')} />
              <span>LMWH :</span>
            </div>

            {/* Tanpa Heparin */}
            <div className='flex items-center gap-2'>
              <Checkbox checked={heparnisasi.includes('tanpa_heparin')} />
              <span>Tanpa Heparin, Penyebab :</span>
            </div>

            {/* Program bilas */}
            <div className='flex items-center gap-2'>
              <Checkbox checked={heparnisasi.includes('program_bilas')} />
              <span>Program bilas NaCl 0,9 % 100 cc/jam/1/2/jam</span>
            </div>
          </div>

          {/* Extra space to match original */}
          <div className='h-4' />
        </div>
      </div>

      {/* ════════════════════════════════════════
          SECTION 3 — CATATAN LAIN & TTD DOKTER
      ════════════════════════════════════════ */}
      <div className='border-l border-r border-b border-gray-400'>
        <div className='grid grid-cols-2 divide-x divide-gray-400 min-h-32'>
          {/* Left: Catatan Lain */}
          <div className='px-3 py-2'>
            <p className='mb-2'>Catatan Lain :</p>
            {catatan_lain && (
              <p className='text-xs text-gray-700 whitespace-pre-wrap'>
                {catatan_lain}
              </p>
            )}
          </div>

          {/* Right: TTD & Nama Dokter */}
          <div className='px-3 py-2 flex flex-col items-center justify-center gap-2'>
            <span className='text-xs'>TTD &amp; Nama Dokter</span>
            {dokter_nama ? (
              <QRCode value={dokter_nama} className='h-[50px] w-[50px]' />
            ) : (
              <div className='h-[50px] w-[50px]' />
            )}

            {dokter_nama ? (
              <span className='text-xs text-center'>({dokter_nama})</span>
            ) : (
              <span className='text-xs text-center'>-----------------</span>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

export default MedicalInstructionForm
