import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import Text from '@/components/text'
import { getEfekSampingObat } from '@/services/efek-samping-obat'
import { useAuthStore } from '@/store/auth.store'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDateTime } from '@/utils/formatDate'

interface ReportEfekSampingObatProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportEfekSampingObat({
  isReport = false,
  noreg = '',
  no,
}: ReportEfekSampingObatProps) {
  const { pasien } = usePasienStore((state) => state)
  const { user } = useAuthStore((state) => state)
  const kdBagian = user?.kd_bagian || pasien?.kd_bagian || ''

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.efekSampingObat, noreg, kdBagian],
    queryFn: () => getEfekSampingObat({ no_reg: noreg, kd_bagian: kdBagian }),
    enabled: !!noreg && !!kdBagian,
  })

  const res = data?.response

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return <EmptyPlaceholder />

  const eso = res.efek_samping_obat

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          FORMULIR PELAPORAN EFEK SAMPING OBAT
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='border border-black my-2 p-2'>
          <Text
            kStyle='min-w-[250px]'
            k='Penyakit Utama'
            v={eso.penyakit_utama}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Reaksi ESO yang Pernah Dialami'
            v={eso.reaksi_eso}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Penyakit / Kondisi Lain yang Menyertai'
            v={eso.penyakit_kondisi_menyertai}
          />
          <Text kStyle='min-w-[250px]' k='Hamil' v={eso.hamil} />
          <Text kStyle='min-w-[250px]' k='Suku' v={eso.suku} />
          <Text kStyle='min-w-[250px]' k='Berat Badan' v={`${eso.bb} kg`} />
          <Text kStyle='min-w-[250px]' k='Pekerjaan' v={eso.pekerjaan} />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='OBAT YANG DICURIGAI' />
          <Text
            kStyle='min-w-[250px]'
            k='Tanggal Mulai Terjadi ESO'
            v={formatDateTime(eso.tanggal_eso)}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Bentuk / Manifestasi ESO'
            v={eso.bentuk_eso}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Data Laboratorium'
            v={eso.data_laboratorium}
          />

          <div className='flex mt-4'>
            <SimpleColumn name='No' className='text-xs flex-[0.3]' />
            <SimpleColumn name='Nama Obat' className='text-xs flex-[1.5]' />
            <SimpleColumn name='Bentuk Sediaan' className='text-xs flex-1' />
            <SimpleColumn name='Rute' className='text-xs flex-[0.7]' />
            <SimpleColumn name='Aturan Pakai' className='text-xs flex-1' />
            <SimpleColumn name='Tanggal Mulai' className='text-xs flex-1' />
            <SimpleColumn name='Tanggal Akhir' className='text-xs flex-1' />
            <SimpleColumn name='Keterangan' className='text-xs flex-1' isLast />
          </div>

          {(eso.obat_yang_dicurigai ?? []).length == 0 && <EmptyPlaceholder />}

          {(eso.obat_yang_dicurigai ?? []).map((item, index) => (
            <div className='flex' key={item.id ?? index}>
              <SimpleColumn
                name={`${index + 1}`}
                className='text-xs flex-[0.3]'
              />
              <SimpleColumn
                name={item.nama_obat || '-'}
                className='text-xs flex-[1.5]'
              />
              <SimpleColumn
                name={item.bentuk_sediaan || '-'}
                className='text-xs flex-1'
              />
              <SimpleColumn
                name={item.rute || '-'}
                className='text-xs flex-[0.7]'
              />
              <SimpleColumn
                name={item.aturan_pakai || '-'}
                className='text-xs flex-1'
              />
              <SimpleColumn
                name={item.tanggal_mulai || '-'}
                className='text-xs flex-1'
              />
              <SimpleColumn
                name={item.tanggal_akhir || '-'}
                className='text-xs flex-1'
              />
              <SimpleColumn
                name={item.keterangan || '-'}
                className='text-xs flex-1'
                isLast
              />
            </div>
          ))}
        </div>

        <div className='border border-black my-2 p-2'>
          <p className='font-semibold'>
            TINDAKAN YANG DILAKUKAN UNTUK MENGATASI REAKSI ESO
          </p>
          <Text
            kStyle='min-w-[250px]'
            k='Obat dihentikan / reaksi hilang'
            v={eso.reaksi_obat_eso}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Instruksi Dokter'
            v={eso.instruksi_dokter}
          />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='KESUDAHAN ESO' />
          <Text
            kStyle='min-w-[250px]'
            k='Tanggal'
            v={formatDateTime(eso.tanggal_kesudahan_eso)}
          />
          <Text kStyle='min-w-[250px]' k='Hasil' v={eso.hasil} />
        </div>

        <div className='flex justify-end mt-4'>
          <div className='text-center text-xs'>
            <p>Petugas</p>
            <div className='h-16' />
            <p>{res.user || '-'}</p>
            <p>{formatDateTime(res.insert_dttm)}</p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
