import type { Response } from '@/type'

import { get } from './api-2'

export interface InstruksiDokterPascaBedah {
  instruksi: string
}

export interface HariPascaBedah {
  no: number
  judul: string
}

export interface DiperhatikanPascaBedah {
  keterangan: string
}

export interface TerapiOralPascaBedah {
  namaObat: string
  dosis: string
  frekuensi: string
}

export interface AsuhanMedisPascaBedah {
  id: number
  tanggal_tindakan: string
  tindakan_operasi: string
  instruksi_dokter: InstruksiDokterPascaBedah[]
  diet: string
  hari: HariPascaBedah[]
  ganti_verban: string
  yang_diperhatikan: DiperhatikanPascaBedah[]
  terapi_oral: TerapiOralPascaBedah[]
  tindak_lanjut: {
    berobat_jalan: string
    kontrol: string
  }
  dokter: {
    nama: string
    ttd: string
  }
}

const getAsuhanMedisPascaBedah = async (
  noreg: string,
): Promise<Response<AsuhanMedisPascaBedah[]>> => {
  const params = { noreg }
  const response = await get('/v1/all-asuhan-medis', params, params)

  return response.data
}

export { getAsuhanMedisPascaBedah }
