import { useState } from 'react'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import ButtonListIntervensi from './component/ButtonList'
import ResikoJatuhReport from './component/IntervensiDewasa'
import { getIntervensiDewasa } from './intervensi-dewasa'

interface IntervensiResikoJatuhDewasaProps {
  isReport?: boolean
  noreg?: string
}

const FormulirIntervensiResikoJatuhDewasa = ({
  noreg = '',
  isReport = true,
}: IntervensiResikoJatuhDewasaProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.intervensiResikoJatuhDewasa,
      noreg,
    ],
    queryFn: () =>
      getIntervensiDewasa({
        noreg: noreg!,
      }),
    enabled: !!noreg,
  })

  const res = data?.response ?? []

  const [selectedIndex, setSelectedIndex] = useState(0) // ✅ selalu di atas

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo>
      {isReport && <ReportHeader />}
      <div className='p-4'>
        <ButtonListIntervensi
          items={res}
          onChange={(idx) => setSelectedIndex(idx)}
        />

        <h1 className='text-center text-black font-semibold  mt-4'>
          INTERVENSI RISIKO JATUH PASIEN DEWASA
        </h1>

        <p className='text-center mb-3'>
          Beri tanda (✓) pada tindakan yang dilaksanakan
        </p>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='mt-4'>
          <ResikoJatuhReport data={res[selectedIndex]} />
        </div>
      </div>
    </LayoutBorderNo>
  )
}

export default FormulirIntervensiResikoJatuhDewasa
