import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import { getImplementasiKeperawatan } from '@/services/implementasi-keperawatan'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDateTime } from '@/utils/formatDate'

interface ReportImplementasiKeperawatanProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportImplementasiKeperawatan({
  isReport = false,
  noreg = '',
  no,
}: ReportImplementasiKeperawatanProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.implementasiKeperawatan, noreg],
    queryFn: () => getImplementasiKeperawatan(noreg),
    enabled: !!noreg,
  })

  const res = data?.response ?? []

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          CATATAN IMPLEMENTASI KEPERAWATAN
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='flex mt-4'>
          <SimpleColumn name='No' className='text-xs flex-[0.4]' />
          <SimpleColumn name='Jenis Tindakan' className='text-xs flex-[2]' />
          <SimpleColumn
            name='Waktu Pelaksanaan & Nama / Paraf'
            className='text-xs flex-[1.5]'
          />
        </div>

        {res.length == 0 && <EmptyPlaceholder />}

        {res.map((item, index) => (
          <div className='flex' key={index}>
            <SimpleColumn
              name={`${index + 1}`}
              className='text-xs flex-[0.4]'
            />
            <SimpleColumn
              name={item.deskripsi || '-'}
              className='text-xs flex-[2]'
            />
            <SimpleColumn
              name={`${formatDateTime(item.insert_dttm)} - ${item.user?.nama ?? '-'}`}
              className='text-xs flex-[1.5]'
            />
          </div>
        ))}
      </div>
    </LayoutBorderNo>
  )
}
