import { SimpleColumn } from '@/components/simple-column'
import type { ResikoJatuhGetup } from '@/models/asesmen-awal-keperawatan-igd.model'

const TableHasilResikoJatuh = ({
  title,
  data,
}: {
  title?: string
  data: ResikoJatuhGetup
}) => {
  const hasil = data.hasil.split('-')[0].toLowerCase() ?? ''

  return (
    <div className='mb-2'>
      {/* Table */}
      <p className='text-xs font-semibold'>{title ?? ''}</p>
      {/* Header */}
      <div className='flex mt-4'>
        <SimpleColumn name='No' className='border-b-0 text-xs w-[50px]' />
        <SimpleColumn name='Hasil' className='border-b-0 text-xs flex-1' />
        <SimpleColumn
          name='Penilaian / Pengkajian'
          className='border-b-0 text-xs flex-1'
        />
        <SimpleColumn
          name='Keterangan'
          className='border-b-0 text-xs flex-1'
          isLast
        />
      </div>
      {/* Header */}

      {/* Body */}
      <div className='border-b-[1px] border-black'>
        <Item
          n1='1.'
          n2='Tidak beresiko'
          n3='Tidak ditemukan a dan b'
          n4={hasil.includes('tidak beresiko') ? '✓' : ''}
        />
        <Item
          n1='2.'
          n2='Resiko rendah'
          n3='Ditemukan salah satu dari a dan b'
          n4={hasil.includes('resiko rendah') ? '✓' : ''}
        />
        <Item
          n1='3.'
          n2='Resiko tinggi'
          n3='Ditemukan a dan b'
          n4={hasil.includes('resiko tinggi') ? '✓' : ''}
        />
      </div>
      {/* Body */}
    </div>
  )
}

export default TableHasilResikoJatuh

const Item = ({
  n1,
  n2,
  n3,
  n4,
}: {
  n1?: string
  n2?: string
  n3?: string
  n4?: string
}) => {
  return (
    <div className='flex boder border-b-black'>
      <SimpleColumn name={n1} className='border-b-0 text-xs w-[50px]' />
      <SimpleColumn name={n2} className='border-b-0 text-xs flex-1' />
      <SimpleColumn name={n3} className='border-b-0 text-xs flex-1' />
      <SimpleColumn isLast name={n4} className='border-b-0 text-xs flex-1' />
    </div>
  )
}
