import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { DiagnosaTable } from '@/features/pasien-pulang/rekam-medis/components/diagnosa-table'
import { LaborTable } from '@/features/pasien-pulang/rekam-medis/components/labor-table'
import { TextTitle } from '@/features/pasien-pulang/rekam-medis/components/text-title'
import { getReportResumeMedis } from '@/services/resume-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import PemeriksaanLainList from './pemeriksaan-lain'
import TerapiPanel from './terapi'
import { TindakanTable } from './tindakan-table'

interface ReportResumeMedisProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportResumeMedis({
  isReport = false,
  noreg = '',
}: ReportResumeMedisProps) {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.reportResumeMedis, noreg],
    queryFn: () => getReportResumeMedis(noreg),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : null

  const { pasien } = usePasienStore((state) => state)

  console.log(res)

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={'RM RI'}>
      {isReport && <ReportHeader />}
      <div className='mx-auto bg-white p-2 text-xs'>
        <div className='text-center border-b-2 border-black pb-2 mb-4'>
          <h1 className='text-xl font-bold tracking-[0.2em] uppercase mb-3'>
            Resume Medis
          </h1>
          {pasien != null && (
            <InformasiPasien
              nama={pasien.nama_pasien}
              noRM={pasien.no_rm}
              tanggalLahir={pasien.tgl_lahir}
            />
          )}
        </div>

        {/* Informasi Pasien */}

        {/* Informasi Pasien */}
        <table className='w-full border-collapse border border-black mb-0 text-xs'>
          <tbody>
            <tr>
              <td className='border border-black p-1 w-1/4'>
                Tanggal Masuk : {res?.tgl_masuk}
              </td>
              <td className='border border-black p-1 w-1/4' align='right'>
                Tanggal Keluar : {res?.tgl_keluar}
              </td>
            </tr>
            <tr>
              <td className='border border-black p-1 font-bold'>
                Dokter Penanggung Jawab (DPJP) : {res?.dokter_dpjp}
              </td>
            </tr>
            <tr>
              <td className='border border-black p-1 w-1/4'>
                Rawat Tim Dokter :
              </td>
              <td className='border border-black p-1'>
                {/* {res?.rawat_tim_dokter} */}
              </td>
            </tr>
          </tbody>
        </table>
        <br />

        {/* Alasan & Diagnosa Masuk */}
        <table className='w-full border-collapse border-x border-b border-t border-black'>
          <tbody>
            <tr>
              <td className='border-r border-black p-1 w-1/4 font-semibold text-center'>
                Alasan Dirawat
                <br />
                (Sesuai Klinikal Patway)
              </td>
              <td className='p-1 italic'>{res?.alasan_dirawat}</td>
            </tr>
            <tr>
              <td className='border-t border-r border-black p-1 w-1/4 font-semibold text-center align-middle'>
                Diagnosa Masuk
              </td>
              <td className='border-t border-black p-1 whitespace-pre-line'>
                <DiagnosaTable data={res != null ? res.diagnosa_masuk : []} />
              </td>
            </tr>
            <tr>
              <td className='border-t border-r border-black p-1 w-1/4 font-semibold'>
                Pemeriksaan Fisik yang penting
              </td>
              <td className='border-t border-black p-1 whitespace-pre-line'>
                {res?.pemeriksaan_fisik}
              </td>
            </tr>

            <tr>
              <td className='border-t border-r border-black p-1 w-1/4 font-semibold'>
                Penunjang Lain
              </td>
              <td className='border-t border-black p-1 whitespace-pre-line'>
                <p className='flex-1 font-semibold'>PEMERIKSAAN PENUNJANG</p>
                <div>
                  <TextTitle title='Laboratorium' />
                  <LaborTable data={res != null ? res?.labor : []} />
                </div>
                <div>
                  <TextTitle title='Pemeriksaan Lain' />
                  <PemeriksaanLainList
                    data={res != null ? res?.pemeriksaan_lain : []}
                  />
                </div>
              </td>
            </tr>

            <tr>
              <td className='border-t border-r border-black p-1 w-1/4 font-semibold text-center align-middle'>
                Diagnosa Keluar (Diagnosa Utama - ICD10)
              </td>
              <td className='border-t border-black p-1 whitespace-pre-line'>
                <DiagnosaTable data={res != null ? res.diagnosa_utama : []} />
              </td>
            </tr>

            <tr>
              <td className='border-t border-r border-black p-1 w-1/4 font-semibold text-center align-middle'>
                Diagnosa Sekunder
              </td>
              <td className='border-t border-black p-1 whitespace-pre-line'>
                <DiagnosaTable data={res != null ? res.diagnosa_lain : []} />
              </td>
            </tr>

            <tr>
              <td className='border-t border-r border-black p-1 w-1/4 font-semibold text-center align-middle'>
                Tindakan Operasi
              </td>
              <td className='border-t border-black p-1 whitespace-pre-line'>
                <TindakanTable data={res != null ? res.tindakan : []} />
              </td>
            </tr>

            <tr>
              <td className='border-t border-r border-black p-1 w-1/4 font-semibold text-center align-top'>
                Terapi
              </td>
              <td className='border-t border-black p-1 whitespace-pre-line'>
                <TerapiPanel
                  obatDiberi={
                    res?.terapi_diberi?.map((nama, id) => ({ id, nama })) ?? []
                  }
                  obatPulang={
                    res?.terapi_pulang?.map((nama, id) => ({ id, nama })) ?? []
                  }
                />
              </td>
            </tr>

            <tr>
              <td className='border-t border-r border-black p-1 w-1/4 font-semibold text-center align-middle'>
                Instruksi
              </td>
              <td className='border-t border-black p-1 whitespace-pre-line'>
                {res?.instruksi}
              </td>
            </tr>

            <tr>
              <td className='border-t border-r border-black p-1 w-1/4 font-semibold text-center align-middle'>
                Follow up
              </td>
              <td className='border-t border-black p-1 whitespace-pre-line'>
                {res?.follow_up}
              </td>
            </tr>

            <tr>
              <td className='border-t border-r border-black p-1 w-1/4 font-semibold text-center align-middle'>
                Cara Pulang
              </td>
              <td className='border-t border-black p-1 whitespace-pre-line'>
                {res?.cara_pulang}
              </td>
            </tr>

            <tr>
              <td className='border-t border-r border-black p-1 w-1/4 font-semibold text-center align-middle'>
                Kondisi Pulang
              </td>
              <td className='border-t border-black p-1 whitespace-pre-line'>
                {res?.kondisi_pulang}
              </td>
            </tr>
          </tbody>
        </table>

        <table className='w-full'>
          <tr className='border border-black w-full '>
            <td className='border border-black text-center align-middle p-2 w-full'>
              <div className='w-full flex flex-col items-center justify-center text-xs'>
                <p className='font-semibold'>Dokter DPJP</p>

                <QRCode
                  value={res?.dokter_dpjp ?? '-'}
                  className='w-[60px] h-[60px] my-1'
                />

                <p className='text-center'>({res?.dokter_dpjp ?? '-'})</p>
              </div>
            </td>
          </tr>
        </table>
      </div>
      <div></div>
    </LayoutBorderNo>
  )
}
