import type { Response } from '@/type'

import { get } from './api-2'

export interface RiwayatRekonsiliasi {
  id: string
  is_enable: boolean
  nama: string
}

export interface AlergiRekonsiliasi {
  id: string
  nama: string
}

export interface ObatRekonsiliasi {
  id: string
  nama_obat: string
  dosis: string
  aturan_pakai: string
  cara_pemberian: string
  waktu_pemberian_terakhir: string
  tindak_lanjut: string
  perubahan_aturan_pakai: string
}

export interface RekonsiliasiObatAdmisi {
  riwayat_penyakit: RiwayatRekonsiliasi[]
  riwayat_pengobatan_terdahulu: RiwayatRekonsiliasi[]
  alergi_obat: AlergiRekonsiliasi[]
  manafestasi_alergi: AlergiRekonsiliasi[]
  dampak: string
  rekonsiliasi_obat_data: ObatRekonsiliasi[]
  nama_dpjp: string
  ttd_dpjp: string
  tanggal_dpjp: string
  nama_perawat: string
  ttd_perawat: string
  tanggal_perawat: string
  nama_apoteker: string
  ttd_apoteker: string
  tanggal_apoteker: string
}

const getRekonsiliasiObatAdmisi = async (
  noreg: string,
): Promise<Response<RekonsiliasiObatAdmisi>> => {
  const response = await get(
    '/v1/rekonsiliasi-obat-saat-admisi',
    { noreg },
    { noreg },
  )

  return response.data
}

export { getRekonsiliasiObatAdmisi }
