import { post } from '@/services/api-2'
import type { Response } from '@/type'

export interface ReasesmenResikoJatuhDewasa {
  reasesmenResikoJatuhDewasaToJson: any
  insertDttm: string
  pelayanan: string
  kd_bagian: string
  noreg: string
  kategori: string
  ket_person: string
  r_jatuh: string
  diagnosis: string
  ambulasi: string
  terapi: string
  terpasang_infuse: string
  gaya_berjalan: string
  status_mental: string
  total: number
}

// Converts JSON strings to/from your types
export class Convert {
  public static toReasesmenResikoJatuhDewasa(
    json: string,
  ): ReasesmenResikoJatuhDewasa {
    return JSON.parse(json)
  }

  public static reasesmenResikoJatuhDewasaToJson(
    value: ReasesmenResikoJatuhDewasa,
  ): string {
    return JSON.stringify(value)
  }
}

const getReasesemeDewasa = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<ReasesmenResikoJatuhDewasa[]>> => {
  const response = await post(`/v1/reasesmen-jatuh-dewasa/get`, {
    no_reg: noreg,
  })

  return response.data
}

export { getReasesemeDewasa }
