// ─── SUB COMPONENTS ──────────────────────────────────────────────────────────

function SectionHeader({ title }: { title: string }) {
  return (
    <div style={styles.sectionHeader}>
      <span style={styles.sectionTitle}>{title}</span>
    </div>
  )
}

function FieldItem({
  label,
  value,
  style,
}: {
  label: string
  value?: string
  style?: React.CSSProperties
}) {
  return (
    <div style={{ ...styles.fieldItem, ...style }}>
      <div style={styles.fieldLabel}>{label}</div>
      <div
        style={
          value
            ? styles.fieldValue
            : { ...styles.fieldValue, ...styles.fieldEmpty }
        }
      >
        {value || '—'}
      </div>
    </div>
  )
}

function VitalCard({
  label,
  value,
  unit,
  accentColor,
}: {
  label: string
  value?: string
  unit?: string
  accentColor?: string
}) {
  return (
    <div style={styles.vitalCard}>
      <div
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          height: 2,
          background: accentColor ?? '#2563eb',
        }}
      />
      <div style={styles.vitalLabel}>{label}</div>
      <div style={styles.vitalValue}>
        {value || '—'}
        {unit && <span style={styles.vitalUnit}>{unit}</span>}
      </div>
    </div>
  )
}

