export default RekamMedisForm

function Checkbox({ checked }: { checked: boolean }) {
  return (
    <span className='inline-flex items-center justify-center w-4 h-4 border border-gray-500 bg-white flex-shrink-0'>
      {checked && (
        <svg viewBox='0 0 10 10' className='w-3 h-3'>
          <polyline
            points='1.5,5 4,7.5 8.5,2'
            fill='none'
            stroke='#111'
            strokeWidth='1.6'
            strokeLinecap='round'
            strokeLinejoin='round'
          />
        </svg>
      )}
    </span>
  )
}

function isResikoTinggi(total: string): boolean {
  const val = Number(total)
  return val > 50
}

function isResikoRendah(total: string): boolean {
  const val = Number(total)
  return val >= 25 && val <= 50
}

function isTidakBeresiko(total: string): boolean {
  const val = Number(total)
  return val >= 0 && val <= 24
}
