export default FormulirAsesmenAnak

const Row = ({ label, value }: { label: string; value?: string | number }) => (
  <tr className='border-b border-black last:border-b-0'>
    <td className='border-r border-black p-2 w-1/3 font-normal text-[11px] md:text-xs uppercase leading-tight'>
      {label}
    </td>
    <td className='p-2 text-[11px] md:text-xs leading-relaxed whitespace-pre-wrap'>
      {value || ''}
    </td>
  </tr>
)

function toScoreNyeri(n: number) {
  if (n == 1 || n == 2) {
    return asesmenNyeriIcon.AN1
  }

  if (n == 3 || n == 4) {
    return asesmenNyeriIcon.AN2
  }

  if (n == 5 || n == 6) {
    return asesmenNyeriIcon.AN3
  }

  if (n == 7 || n == 8) {
    return asesmenNyeriIcon.AN4
  }

  if (n == 9 || n == 10) {
    return asesmenNyeriIcon.AN5
  }

  return asesmenNyeriIcon.AN1
}
