
import { post } from './api-2'
import type { Response, } from '@/type'


const getAnalisaData = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<AnalisaData[]>> => {
  const response = await post(`/v1/laporan-analisa-data`,
    {no_reg: noreg}
  )

  return response.data
}

export { getAnalisaData }


export interface AnalisaData {
    id:            number;
    insert_dttm:   string;
    kode_analisa:  string;
    kd_bagian:     string;
    user_id:       string;
    noreg:         string;
    data:          string;
    hasil:         string;
    user_teratasi: string;
    tgl:           string;
    jam:           string;
    analisa_data:  AnalisaDatum[];
    pegawai:       Pegawai;
}

export interface AnalisaDatum {
    id:            number;
    noreg:         string;
    kode:          string;
    id_diagnosa:   string;
    nama_diagnosa: string;
}

export interface Pegawai {
    id:            string;
    nama:          string;
    jenis_kelamin: string;
    tgl_lahir:     string;
}
