function toTotalSkor(n1: string, n2: string): number {
  let skor = 0

  if (n1 === 'Tidak Yakin') skor += 2
  if (n1 === 'Ya, ada penurunan berat badan sebanyak 1-5 kg') skor += 1
  if (n1 === 'Ya, ada penurunan berat badan sebanyak 6-10 kg') skor += 2
  if (n1 === 'Ya, ada penurunan berat badan sebanyak 11-15 kg') skor += 3
  if (n1 === 'Ya, ada penurunan berat badan sebanyak >15 kg') skor += 4
  if (n2 === 'Ya') skor += 1

  return skor
}

export default toTotalSkor
