import type { Response } from '@/type'

import { post } from './api-2'

const getInformasiPasienDiRuangRawatan = async ({
  no_reg,
}: {
  no_reg: string
}): Promise<Response<InformasiPasienDiruangRawatan>> => {
  const response = await post(`v1/laporan-informasi-pasien`, {
    no_reg,
  })

  return response.data
}

export { getInformasiPasienDiRuangRawatan }

