import { CheckIcon, CrossIcon } from 'lucide-react'

import { SimpleColumn } from '@/components/simple-column'
import { formatDate } from '@/utils/formatDate'

import { Restrain } from './restrain'

export function DataRestrain({ data }: { data: Restrain[] }) {
  const group: Record<string, Restrain[]> = {}

  for (let i = 0; i < data.length; i++) {
    const curr = data[i]
    const tanggal = formatDate(curr.insert_dttm)

    if (!group[tanggal]) {
      group[tanggal] = []
    }
    group[tanggal].push(curr)
  }

  const list = Object.keys(group).map((k) => {
    return group[k]
  })

  console.log('list labor', list)

  if (list != null && list.length > 0) {
    return (
      <div className='border border-black'>
        {list.map((k, idx) => (
          <div key={idx}>
            <div className='flex text-xs'>
              <SimpleColumn name={String(idx + 1)} className='w-[100px]' />
              <SimpleColumn name={k[0].kesadaran} className='flex-[0.5]' />
              <SimpleColumn name={k[0].hr} className='flex-[0.5]' />
              <SimpleColumn name={k[0].temp} className='flex-[0.5]' />
              <div className='flex flex-col flex-[0.5] gap-2 text-center justify-center items-center p-2 border-y border-black border-l'>
                {k[0].tangan_kanan ? <CheckIcon /> : <CrossIcon />}
              </div>
              <div className='flex flex-col flex-[0.5] gap-2 text-center justify-center items-center p-2 border-y border-black border-l'>
                {k[0].tangan_kiri ? <CheckIcon /> : <CrossIcon />}
              </div>
              <div className='flex flex-col flex-[0.5] gap-2 text-center justify-center items-center p-2 border-y border-black border-l'>
                {k[0].kaki_kanan ? <CheckIcon /> : <CrossIcon />}
              </div>
              <div className='flex flex-col flex-[0.5] gap-2 text-center justify-center items-center p-2 border-y border-black border-l'>
                {k[0].kaki_kiri ? <CheckIcon /> : <CrossIcon />}
              </div>
              <div className='flex flex-col flex-[0.5] gap-2 text-center justify-center items-center p-2 border-y border-black border-l'>
                {k[0].luka ? <CheckIcon /> : <CrossIcon />}
              </div>
              <SimpleColumn
                name='PERAWAT'
                className='flex-[0.5]'
                isLast
                hasQR
              />
            </div>
          </div>
        ))}
      </div>
    )
  } else {
    return <p className='text-xs text-center font-medium'>Tidak ada data</p>
  }
}
