interface ObatItem {
  id: number
  nama: string
}

interface TerapiPanelProps {
  obatDiberi: ObatItem[]
  obatPulang: ObatItem[]
}

interface TerapiColumnProps {
  title: string
  items: ObatItem[]
}

function TerapiColumn({ title, items }: TerapiColumnProps) {
  return (
    <div className='flex-1 flex flex-col min-w-0 border-r last:border-r-0 border-gray-300'>
      {/* Header */}
      <div className='px-4 py-3 bg-gray-100 border-b border-gray-300'>
        <span className='text-sm font-semibold text-gray-700 tracking-wide'>
          {title}
        </span>
      </div>

      {/* Item list */}
      <div className='flex-1 overflow-y-auto p-3 space-y-2 bg-white'>
        {items.length === 0 && (
          <div className='flex items-center justify-center h-24 text-gray-300 text-sm italic'>
            Tidak ada data
          </div>
        )}
        {items.map((item) => (
          <div
            key={item.id}
            className='px-4 py-3 border border-gray-200 rounded-xl bg-white'
          >
            <span className='text-sm font-medium text-gray-800 leading-snug'>
              {item.nama}
            </span>
          </div>
        ))}
      </div>
    </div>
  )
}

export default function TerapiPanel({
  obatDiberi,
  obatPulang,
}: TerapiPanelProps) {
  return (
    <div
      className='border border-gray-400 rounded-sm shadow-lg overflow-hidden flex'
      style={{ minHeight: 520 }}
    >
      <TerapiColumn title='Terapi yang sudah diberi' items={obatDiberi} />
      <TerapiColumn title='Terapi pulang' items={obatPulang} />
    </div>
  )
}
