import type { Response } from '@/type'

import { post } from './api-2'

const getDischargePlanning = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<DischargePlanning>> => {
  const response = await post(`/v1/laporan-discharge-planning`, {
    noreg: noreg,
  })

  return response.data
}

export { getDischargePlanning }

