import { post } from '@/services/api-2'
import type { Response } from '@/type'

export interface Geriatri {
  tanggal: string
  jam: string
  total_skor: number
  riwayat_jatuh: Resiko[]
  status_mental: Resiko[]
  penglihatan: Resiko[]
  kebiasaan_berkemih: Resiko[]
  transfer: Resiko[]
  mobilitasi: Resiko[]
}

export interface Resiko {
  title: string
  jawaban: string
  skor: number
}

export class Convert {
  public static toGeriatri(json: string): Geriatri {
    return JSON.parse(json)
  }

  public static geriatriToJson(value: Geriatri): string {
    return JSON.stringify(value)
  }
}

const getReasesmenGeriatri = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<Geriatri[]>> => {
  const response = await post(`/v1/all-resiko-jatuh-geriatri/get`, {
    no_reg: noreg,
  })

  return response.data
}

export { getReasesmenGeriatri }
