import type { Response } from '@/type'

import { get } from './api-2'

export interface LaporanTbDewasa {
  tanggal: string
  tb_1: string
  tb_2: string
  tb_3: string
  tb_4: string
  tb_5: string
  tb_6: string
  tb_7: string
  tb_8: string
  tb_9: string
  tb_10: string
  tb_11: string
  tb_12: string
}

const getLaporanTbDewasa = async ({
  noreg,
  bagian,
}: {
  noreg: string
  bagian: string
}): Promise<Response<LaporanTbDewasa>> => {
  const params = { noreg, kategori: 'DEWASA', bagian }
  const response = await get('/v4/report-data-tb', params, params)

  return response.data
}

export { getLaporanTbDewasa }
