import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { getSurveilansInfeksi } from '@/services/surveilans-infeksi'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import ReportSurveilansInfeksiFull, {
  SurveilansInfeksiData,
} from './report-surveilans-infeksi'

interface ReportSurveilansInfeksiProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

interface DiagnosaLike {
  diagnosa?: string
  description?: string
}

function toDiagnosaText(items: DiagnosaLike[] | undefined) {
  return (items ?? [])
    .map((item) => item.diagnosa || item.description || '')
    .filter(Boolean)
}

export default function ReportSurveilansInfeksi({
  isReport = false,
  noreg = '',
  no,
}: ReportSurveilansInfeksiProps) {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.surveilansInfeksi, noreg],
    queryFn: () => getSurveilansInfeksi(noreg),
    enabled: !!noreg,
  })

  const res = data?.response
  const { pasien } = usePasienStore((state) => state)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (!res) return <EmptyPlaceholder />

  const fullData = {
    ...res,
    riwayat_masuk: {
      tanggal_masuk: res.riwayat_masuk?.tanggal_masuk ?? '',
      diagnosa_masuk: toDiagnosaText(
        res.riwayat_masuk?.diagnosa_masuk as DiagnosaLike[],
      ),
    },
    tindakan_operasi: {
      ...res.tindakan_operasi,
      diagnosa: toDiagnosaText(
        res.tindakan_operasi?.diagnosa as DiagnosaLike[],
      ),
    },
  } as unknown as SurveilansInfeksiData

  return (
    <LayoutBorderNo no={no ?? 'RM. RI 35 B'}>
      {isReport && <ReportHeader />}

      {pasien != null && (
        <InformasiPasien
          nama={pasien.nama_pasien}
          noRM={pasien.no_rm}
          tanggalLahir={pasien.tgl_lahir}
          jk={pasien.jenis_kelamin}
        />
      )}

      <ReportSurveilansInfeksiFull data={fullData} />
    </LayoutBorderNo>
  )
}
