import { post } from '@/services/api-2'
import type { Diagnosa, Response } from '@/type'

const getReportAsuhanGizi = async ({
  noreg = '',
}: {
  noreg: string
}): Promise<Response<FormulirGizi>> => {
  const response = await post(`/v1/laporan-asuhan-gizi`, {
    noreg: noreg,
  })

  return response.data
}

export { getReportAsuhanGizi }

export interface FormulirGizi {
  tanggal: string
  jam: string
  umur: string
  diagnosa: Diagnosa[]
  fisik_gizi: FisikGizi
  biokimia: string
  klinik_fisik: string
  alergi_makan: AlergiMakan[]
  pola_makan: string
  riwayat_personal: string
  diagnosis_gizi: string
  intervensi_gizi: string
  monitoring_evaluasi: string
  nama_ahli_gizi: string
  ttd_ahli_gizi: string
}

export interface AlergiMakan {
  deskripsi: string
  hasil: string
}

export interface FisikGizi {
  bb: string
  tb: string
  imt: string
  lla: string
  lt: string
}

// Converts JSON strings to/from your types
export class Convert {
  public static toFormulirGizi(json: string): FormulirGizi {
    return JSON.parse(json)
  }

  public static formulirGiziToJson(value: FormulirGizi): string {
    return JSON.stringify(value)
  }
}
