import { post } from './api-2'

const getReportResumeMedis = async (
  no_reg: string,
): Promise<Response<ResumeMedis>> => {
  const response = await post(`/v1/laporan-resume-medis-ranap`, {
    no_reg: no_reg,
  })

  return response.data
}

export { getReportResumeMedis }

