export function formatTanggalIndonesia(dateInput: string): string {
  if (!dateInput || dateInput.trim() === '') return '-'

  const date = new Date(dateInput)
  if (isNaN(date.getTime())) return 'Tanggal tidak valid'

  const BULAN: string[] = [
    'Januari',
    'Februari',
    'Maret',
    'April',
    'Mei',
    'Juni',
    'Juli',
    'Agustus',
    'September',
    'Oktober',
    'November',
    'Desember',
  ]

  const pad = (n: number): string => String(n).padStart(2, '0')

  const tgl = date.getDate()
  const bulan = date.getMonth()
  const tahun = date.getFullYear()

  const jam = pad(date.getHours())
  const menit = pad(date.getMinutes())
  const detik = pad(date.getSeconds())

  return `${tgl} ${BULAN[bulan]} ${tahun} ${jam}:${menit}:${detik} WIB`
}

export function formatTglIndonesia(dateInput: string): string {
  if (!dateInput || dateInput.trim() === '') return '-'

  const date = new Date(dateInput)
  if (isNaN(date.getTime())) return 'Tanggal tidak valid'

  const BULAN: string[] = [
    'Januari',
    'Februari',
    'Maret',
    'April',
    'Mei',
    'Juni',
    'Juli',
    'Agustus',
    'September',
    'Oktober',
    'November',
    'Desember',
  ]

  const tgl = date.getDate()
  const bulan = date.getMonth()
  const tahun = date.getFullYear()

  return `${tgl} ${BULAN[bulan]} ${tahun}`
}

export function formatTanggal(dateString: string): string {
  const date = new Date(dateString)

  return new Intl.DateTimeFormat('id-ID', {
    day: 'numeric',
    month: 'long',
    year: 'numeric',
  }).format(date)
}

export function formatTanggalJamIndo(dateString: string): string {
  const bulan = [
    'Januari',
    'Februari',
    'Maret',
    'April',
    'Mei',
    'Juni',
    'Juli',
    'Agustus',
    'September',
    'Oktober',
    'November',
    'Desember',
  ]

  const date = new Date(dateString)

  const hari = date.getDate()
  const bulanIndex = date.getMonth()
  const tahun = date.getFullYear()
  const jam = date.getHours().toString().padStart(2, '0')
  const menit = date.getMinutes().toString().padStart(2, '0')

  return `${hari} ${bulan[bulanIndex]} ${tahun} ${jam}:${menit}`
}

export function formatJam(dateString: string): string {
  const date = new Date(dateString)

  const jam = date.getHours().toString().padStart(2, '0')
  const menit = date.getMinutes().toString().padStart(2, '0')

  return ` ${jam}:${menit}  WIB`
}

export function formatTanggalHariJamIndo(dateString?: string): string {
  if (!dateString || !dateString.trim()) return '-'

  const date = new Date(dateString)

  // handle invalid date
  if (isNaN(date.getTime())) return '-'

  const hariList = [
    'Minggu',
    'Senin',
    'Selasa',
    'Rabu',
    'Kamis',
    'Jumat',
    'Sabtu',
  ]

  const bulan = [
    'Januari',
    'Februari',
    'Maret',
    'April',
    'Mei',
    'Juni',
    'Juli',
    'Agustus',
    'September',
    'Oktober',
    'November',
    'Desember',
  ]

  const namaHari = hariList[date.getDay()]
  const hari = date.getDate()
  const bulanIndex = date.getMonth()
  const tahun = date.getFullYear()
  const jam = date.getHours().toString().padStart(2, '0')
  const menit = date.getMinutes().toString().padStart(2, '0')

  return `${namaHari}, ${hari} ${bulan[bulanIndex]} ${tahun} ${jam}:${menit} WIB`
}
