import type { Labor } from '@/models/asesmen-awal-medis-igd.model'
import type { Response } from '@/type'

import { post } from './api-2'

const getHasilFisioterapi = async (
  no_reg: string,
): Promise<Response<Labor[]>> => {
  const response = await post('/v1/hasil-pemeriksaan-fisioterapi-old', {
    no_reg,
  })

  return response.data
}

const getHasilGizi = async (no_reg: string): Promise<Response<Labor[]>> => {
  const response = await post('/v1/hasil-pemeriksaan-gizi-old', {
    no_reg,
  })

  return response.data
}

export { getHasilFisioterapi, getHasilGizi }
