import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { getInformasiPasienDiRuangRawatan } from '@/services/informasi-pasien'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import HospitalReport from './ruang'

interface FormulirInformasiPasienDiRuangPerawatProps {
  isReport?: boolean
  no?: string
  noreg?: string
}

export default function InformasiPasienDiruangPerawat({
  isReport = false,
  no = '',
  noreg = '',
}: FormulirInformasiPasienDiRuangPerawatProps) {
  const { pasien } = usePasienStore((state) => state)
  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.pernyataanPulangAtasPermintaanSendiri,
      noreg,
    ],
    queryFn: () => getInformasiPasienDiRuangRawatan({ no_reg: noreg! }),
  })

  const res = data?.response != null ? data.response : null
  console.log(res)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return <EmptyPlaceholder />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}
      <div className='doc-title mt-4 mb-4'>
        <h1>INFORMASI PASIEN DIRUANG PERAWATAN</h1>
      </div>

      {pasien != null && (
        <InformasiPasien
          nama={pasien.nama_pasien}
          noRM={pasien.no_rm}
          jk={pasien.jenis_kelamin}
        />
      )}

      <div className=' bg-white p-2 '>
        <HospitalReport
          ttd={{
            pasien: res?.nama_pasien || '',
            ttd_pasien: res?.ttd_pasien || '',
            petugas: res?.petugas || '',
            ttd_petugas: res?.ttd_petugas || '',
          }}
          sections={[
            {
              id: 'I',
              title: 'Fasilitas Kamar',
              items: [
                {
                  id: 1,
                  label: 'Tempat tidur dan cara penggunaanya',
                  accepted: res!.value1,
                }, // → ✓
                {
                  id: 2,
                  label: 'Bel Pasien, lampu-lampu dan stop kontak',
                  accepted: res!.value2,
                }, // → ✗

                {
                  id: 3,
                  label: 'TV, Kulkas, Lemari, Baju',
                  accepted: res!.value3,
                }, // → ✗
                {
                  id: 4,
                  label: 'Peralatan Makanan',
                  accepted: res!.value4,
                }, // →
                {
                  id: 5,
                  label: 'Kamar mandi : shower, toilet, wastafel dan pispot',
                  accepted: res!.value5,
                }, // →
              ],
            },
            {
              id: 'II',
              title: 'Peraturan Rumah Sakit',
              items: [
                {
                  id: 1,
                  label: 'Hak dan kewajiban Pasien',
                  accepted: res!.value6,
                },
                {
                  id: 2,
                  label: 'Waktu berkunjung keluarga',
                  accepted: res!.value7,
                },
                {
                  id: 3,
                  label: 'Pelayanan rohani sesuai keyakinan',
                  accepted: res!.value8,
                },
                {
                  id: 4,
                  label: 'Waktu berkunjung dokter/visite',
                  accepted: res!.value9,
                },
                {
                  id: 5,
                  label:
                    'Peraturan dilarang merokok dan membuat sampah sembarangan',
                  accepted: res!.value10,
                },
                {
                  id: 6,
                  label: 'Menyimpan barang-barang berharga milik pasien',
                  accepted: res!.value11,
                },
                {
                  id: 7,
                  label:
                    'Waktu makan pasien (tidak boleh membawa makanan dari luar untuk pasien yang mendapat diet khusus)',
                  accepted: res!.value12,
                },
                {
                  id: 8,
                  label:
                    'Hanya berhak memakai 1 (satu) tempat tidur untuk kelas I, II dan III',
                  accepted: res!.value13,
                },
                {
                  id: 9,
                  label:
                    'Waktu pasien pulang / meninggalkan rumah sakit (batas akhir)',
                  accepted: res!.value14,
                },
                {
                  id: 10,
                  label: 'Tertib administrasi',
                  accepted: res!.value15,
                },
              ],
            },

            {
              id: 'III',
              title: 'Pelayanan Keperawatan',
              items: [
                {
                  id: 1,
                  label: 'Informasi tentang Petugas yang merawat',
                  accepted: res!.value16,
                },
                {
                  id: 2,
                  label:
                    'Informasi perkembangan kondisi pasien dan rencana asuhan keperawatan dan kebidanan',
                  accepted: res!.value17,
                },
                {
                  id: 3,
                  label: 'Informasi tentang pasien pulang (Discharge Planning)',
                  accepted: res!.value18,
                },
              ],
            },

            {
              id: 'IV',
              title: 'Pelayanan Keperawatan',
              items: [
                {
                  id: 1,
                  label:
                    'Bila terjadi kebakaran, gempa, bencana dan kebocoran gas/bahan kimia (jangan menggunakan lift), keluarlah melalui tangga darurat',
                  accepted: res!.value19,
                },
              ],
            },
          ]}
        />
      </div>
    </LayoutBorderNo>
  )
}
