import type { AsesmenAwalKeperawatanRanap } from '@/models/asesmen-awal-keperawatan-ranap'
import type { Response } from '@/type'

import { post } from './api-2'

const getAsesmenPerawatRanap = async ({
  noReg,
  kdBagian,
}: {
  kdBagian: string
  noReg: string
}): Promise<Response<AsesmenAwalKeperawatanRanap>> => {
  const response = await post(`/v1/pengkajian-awal-keperawatan`, {
    kd_bagian: kdBagian,
    no_reg: noReg,
  })

  return response.data
}

export { getAsesmenPerawatRanap }
