export function formatTanggalISO(raw: string | null | undefined): string {
  if (!raw) return ''

  const d = new Date(raw)
  if (isNaN(d.getTime())) return raw

  return d.toLocaleDateString('id-ID', {
    day: '2-digit',
    month: 'long',
    year: 'numeric',
  })
}

export function formatTanggalV2(dateString: string): string {
  const date = new Date(dateString)

  const bulan = [
    'Januari',
    'Februari',
    'Maret',
    'April',
    'Mei',
    'Juni',
    'Juli',
    'Agustus',
    'September',
    'Oktober',
    'November',
    'Desember',
  ]

  const hari = date.getDate()
  const bulanNama = bulan[date.getMonth()]
  const tahun = date.getFullYear()

  return `${hari} ${bulanNama} ${tahun} `
}
