import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import Loading from '@/components/loading'
import { getResumeMedis } from '@/services/rekam-medis'
import { Pasien } from '@/type'
import { constants } from '@/utils/constants'

interface ReportResumeProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportResume({ noreg = '' }: ReportResumeProps) {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.resumeMedis, noreg],
    queryFn: () => getResumeMedis(noreg),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : null
  const pasien =
    res != null
      ? ({
          nama_pasien: res.nama_pasien,
          no_rm: res.no_rm,
          tgl_lahir: res.tanggal_lahir,
          jenis_kelamin: res.jenis_kelamin,
        } as Pasien)
      : ({} as Pasien)

  console.log('pasien', pasien)
  if (isLoading) return <Loading />
  if (isError) return <Error />

  return <EmptyPlaceholder />
}
