import { useQuery } from '@tanstack/react-query'

import { formatTanggalJamIndo } from '@/components/date/tgl-indo'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import TandaTanganField from '@/components/tanda-tangan'
import { postDataEdukasi } from '@/services/edukasi-terintegrasi'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import AssessmentEdukasiExact from './components/AssessmentEdukasiExact'

interface EdukasiTerintegrasiProps {
  isReport?: boolean
}

export function EdukasiTerintegrasi({
  isReport = false,
}: EdukasiTerintegrasiProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.pasien.edukasiTerintegrasi.list],
    queryFn: () => postDataEdukasi(pasien!.no_reg),
  })

  const res = data != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />

  const parseToArray = (value?: unknown): string[] => {
    if (!value) return []

    if (Array.isArray(value)) {
      return value
        .map(String)
        .map((v) => v.trim())
        .filter(Boolean)
    }

    if (typeof value !== 'string') return []

    const trimmed = value.trim()
    if (!trimmed || trimmed === 'null' || trimmed === 'undefined') return []

    try {
      const parsed = JSON.parse(trimmed)
      if (Array.isArray(parsed)) {
        return parsed
          .map(String)
          .map((v) => v.trim())
          .filter(Boolean)
      }
    } catch {
      return trimmed
        .split(',')
        .map((v) => v.trim())
        .filter(Boolean)
    }

    return []
  }

  return (
    <LayoutBorderNo no='RM. 20 REV 2023'>
      {/* Content */}
      {isReport && <ReportHeader />}
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-4'>
          EDUKASI TERINTEGRASI PASIEN/KELUARGA
        </h1>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}
        {/* Informasi Pasien */}

        <div>
          <AssessmentEdukasiExact
            selected={{
              tinggalBersama: parseToArray(
                res?.kebutuan_edukasi.tinggal_bersama,
              ),
              hambatan: parseToArray(res?.kebutuan_edukasi.hambatan),
              edukasiDiberikanKepada: parseToArray(
                res?.kebutuan_edukasi.edukasi_diberikan_kepada,
              ),
              kemampuanBahasa: parseToArray(
                res?.kebutuan_edukasi.kemampuan_bahasa,
              ),
              perluPenerjemah: parseToArray(
                res?.kebutuan_edukasi.perlu_penerjemah,
              ),
              agama: parseToArray(res?.kebutuan_edukasi.agama),
              kesediaanMenerimaEdukasi: parseToArray(
                res?.kebutuan_edukasi.kesediaan_menerima_edukasi,
              ),
              bacaTulis: parseToArray(res?.kebutuan_edukasi.baca_dan_tulis),
              kepercayaanLainnya: parseToArray(
                res?.kebutuan_edukasi.kepercayaan_lainnya,
              ),
              caraEdukasi: parseToArray(res?.kebutuan_edukasi.cara_edukasi),
              kebutuhanEdukasi: parseToArray(
                res?.kebutuan_edukasi.kebutuhan_edukasi,
              ),
              agama_lainnya: res?.kebutuan_edukasi.agama_lainnya || '',
              pendidikan: res?.kebutuan_edukasi.pendidikan || '',
              jenis_kelamin: res?.kebutuan_edukasi.jenis_kelamin || '',
            }}
          />
          <div className='flex text-xs'>
            <SimpleColumn head name='Tanggal & Jam' className='w-[100px]' />
            <SimpleColumn head name='Informasi/Edukasi yang diberikan' />
            <SimpleColumn head name='Metode' />
            <SimpleColumn head name='Pemberi Informasi' className='w-[210px]' />
            <SimpleColumn
              head
              name='Penerima Informasi'
              className='w-[210px]'
            />
            <SimpleColumn head name='Evaluasi' isLast={true} />
          </div>
          {/* Header */}

          {res?.edukasi?.map((item, index) => (
            <div className='flex text-xs text-wrap' key={index}>
              <SimpleColumn
                name={formatTanggalJamIndo(item.insert_dttm)}
                className='w-[100px]'
              />
              <SimpleColumn name={item.informasi} />
              <SimpleColumn name={item.metode} />
              <div className='w-[210px] flex text-center justify-center items-center p-2 border-y border-black border-l'>
                <TandaTanganField
                  imageUrl={
                    import.meta.env.VITE_BASE_API_URL_RME +
                    '/app/images/verifikasi_edukasi/' +
                    item.file_verifikasi_pemberi
                  }
                  name={item.pemberi_informasi}
                />
              </div>

              <div className='w-[210px] flex text-center justify-center items-center p-2 border-y border-black border-l'>
                <TandaTanganField
                  imageUrl={
                    import.meta.env.VITE_BASE_API_URL_RME +
                    '/app/images/verifikasi_edukasi/' +
                    item.file_verifikasi_penerima
                  }
                  name={item.penerima_informasi}
                />
              </div>
              <SimpleColumn name={item.evaluasi} isLast={true} />
            </div>
          ))}
        </div>
      </div>
      {/* Content */}
    </LayoutBorderNo>
  )
}
