import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { getPaps } from '@/services/paps'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import FormField from './componsent'
import SignatureField from './singnature'

interface FormulirPapsProps {
  isReport?: boolean
  no?: string
  noreg?: string
}

export default function FormulirPaps({
  isReport = false,
  no = '',
  noreg = '',
}: FormulirPapsProps) {
  const { pasien } = usePasienStore((state) => state)
  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.pernyataanPulangAtasPermintaanSendiri,
      noreg,
    ],
    queryFn: () => getPaps({ noreg }),
  })

  const res = data?.response != null ? data.response : null
  console.log(res)

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='mx-auto bg-white p-4 '>
        <h2 className='text-center text-xl font-semibold'>PERNYATAAN</h2>
        <h2 className='text-center text-xl font-semibold mb-4'>
          PULANG ATAS PERMINTAAN SENDIRI
        </h2>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='mb-2'>
          <p className='mb-6 font-medium'>
            Saya Yang bertanda tangan dibawah ini :
          </p>

          <FormField label='Nama' name='signerName' value={res?.dpaps?.nama} />
          <FormField
            label='Umur/Tanggal Lahir'
            name='signerAge'
            value={res?.dpaps?.umur}
          />
          <FormField
            label='Jenis Kelamin'
            name='signerGender'
            value={res?.dpaps?.jenis_kelamin}
          />
          <FormField
            label='Alamat'
            name='signerAddress'
            value={res?.dpaps?.alamat}
          />
          <FormField
            label='Bukti diri / KTP'
            name='signerIdProof'
            value={res?.dpaps?.ktp}
          />
        </div>

        <div className='mb-2'>
          <p className='text-justify '>
            Menyatakan dengan sesungguhnya bahwa saya telah mendapat penjelasan
            dari dokter dan mengerti mengenai kemungkinan-kemungkinan bahaya
            serta risiko yang akan timbul apabila menghentikan rawat inap
            (pulang paksa) terhadap pasien yang belum sembuh dari penyakitnya.
          </p>
        </div>

        <div className='mb-2'>
          <div className='border-t-2 pt-4 mb-6'>
            <h3 className='font-bold text-lg mb-1'>
              MENGHENTIKAN RAWAT INAP (PULANG PAKSA)
            </h3>
          </div>

          <div>
            <FormField
              label='Terhadap'
              name='patientName'
              value={res?.dpaps.terhadap}
            />
            <FormField
              label='Nama'
              name='patientName'
              value={res?.pasien.nama}
            />
            <FormField
              label='Umur/Tanggal Lahir'
              name='patientDob'
              value={res?.pasien?.umur}
            />
            <FormField
              label='Jenis Kelamin'
              name='patientGender'
              value={res?.pasien?.jenis_kelamin}
            />
            <FormField
              label='Alamat'
              name='patientAddress'
              value={res?.pasien?.alamat}
            />
            <FormField
              label='Bukti Diri / KTP'
              name='patientIdProof'
              value={res?.pasien?.ktp}
            />
            <FormField
              label='Dirawat di'
              name='patientRoom'
              value={res?.dpaps?.dirawat}
            />
            <FormField
              label='No. RM'
              name='patientMedicalRecord'
              value={res?.pasien?.no_rm}
            />
            <FormField
              label='Alasan PAPS'
              name='patientPapsReason'
              value={res?.dpaps?.alasan_paps}
            />
          </div>
        </div>

        <div className='mb-2'>
          <p className='text-justify '>
            Demikian surat pernyataan ini saya buat dengan kesadaran, tanpa
            paksaan serta menerima semua risiko dan tidak akan menuntut kepada
            pihak siapapun / pihak manapun.
          </p>
        </div>

        <div className=' pt-8'>
          <div className='grid grid-cols-2 gap-8 mb-16'>
            <SignatureField
              title='Dokter/Pelaksana'
              imageUrl={
                import.meta.env.VITE_BASE_API_URL_RME +
                '/app/images/formulir_paps/' +
                res?.dpaps?.ttd_dokter_merawat
              }
              name={res?.dpaps?.dokter_merawat}
            />
            <SignatureField
              title='Yang Membuat Penyataan'
              imageUrl={
                import.meta.env.VITE_BASE_API_URL_RME +
                '/app/images/formulir_paps/' +
                res?.dpaps?.ttd_pernyataan
              }
              name={res?.dpaps?.pernyataan}
            />
          </div>
        </div>

        <div className=' pt-8'>
          <div className='grid grid-cols-2 gap-8 mb-16'>
            <SignatureField
              title='Saksi 1'
              imageUrl={
                import.meta.env.VITE_BASE_API_URL_RME +
                '/app/images/formulir_paps/' +
                res?.dpaps?.ttd_saksi1
              }
              name={res?.dpaps?.saksi1}
            />
            <SignatureField
              title='Saksi 2'
              imageUrl={
                import.meta.env.VITE_BASE_API_URL_RME +
                '/app/images/formulir_paps/' +
                res?.dpaps?.ttd_saksi2
              }
              name={res?.dpaps?.saksi2}
            />
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
