import { ReactNode } from 'react'

import { cn } from '@/lib/utils'

interface SimpleColumnTtdProps {
  name?: string
  isLast?: boolean
  head?: boolean
  className?: string
  className2?: string
  imageUrl?: string
  isChild?: ReactNode
}

export function SimpleColumnTtd({
  name,
  head,
  isLast,
  className = 'flex-1',
  className2 = '',
  imageUrl = '',
  isChild,
}: SimpleColumnTtdProps) {
  if (isChild)
    return (
      <div
        className={cn(
          'flex flex-col gap-2 text-center justify-center items-center p-2 border-y border-black border-l',
          isLast && 'border-r',
          className,
          head && 'bg-gray-100',
        )}
      >
        {isChild}
      </div>
    )

  return (
    <div
      className={cn(
        'flex flex-col gap-2 text-center justify-center items-center p-2 border-y border-black border-l',
        isLast && 'border-r',
        className,
        head && 'bg-gray-100',
      )}
    >
      <div className='mb-4 h-24 flex items-center justify-center'>
        {imageUrl ? (
          <img
            src={
              import.meta.env.VITE_BASE_API_URL_RME +
              '/app/images/verifikasi_cppt/' +
              imageUrl
            }
            alt={`${name || ''}`}
            className='h-24 w-24'
          />
        ) : (
          <div className='mb-4 h-24 flex items-center justify-center text-gray-300'></div>
        )}
      </div>
      {name != '' ? <p className={cn(className2)}>({name})</p> : null}
      <div className='w-[150px] border-t border-black' />
    </div>
  )
}
