import { SimpleColumn } from '@/components/simple-column'

import { TBAnak } from './tb-anak'

export function DataTBAnak({ data }: { data: TBAnak[] }) {
  const group: Record<string, TBAnak[]> = {}

  // Populate group dari data
  data.forEach((item) => {
    const key = item.tanggal
    if (!group[key]) group[key] = []
    group[key].push(item)
  })

  const list = Object.keys(group).map((k) => group[k])

  if (list.length > 0) {
    return (
      <div className='border border-black'>
        {list.map((k, idx) => (
          <div key={idx}>
            <div className='flex text-xs'>
              <SimpleColumn name='1' className='w-[100px]' />
              <SimpleColumn name='Kontak TB' className='flex-[0.5]' />
              <SimpleColumn name={k[0].tb_1} className='flex-[0.5]' isLast />
            </div>
            <div className='flex text-xs'>
              <SimpleColumn name='2' className='w-[100px]' />
              <SimpleColumn
                name='Uji Tuberkulin (Mantouk)'
                className='flex-[0.5]'
              />
              <SimpleColumn name={k[0].tb_2} className='flex-[0.5]' isLast />
            </div>

            <div className='flex text-xs'>
              <SimpleColumn name='3' className='w-[100px]' />
              <SimpleColumn
                name='Berat badan / Keadaan gizi'
                className='flex-[0.5]'
              />
              <SimpleColumn name={k[0].tb_3} className='flex-[0.5]' isLast />
            </div>

            <div className='flex text-xs'>
              <SimpleColumn name='4' className='w-[100px]' />
              <SimpleColumn
                name='Demam yang tidak diketahui penyebabnya'
                className='flex-[0.5]'
              />
              <SimpleColumn name={k[0].tb_4} className='flex-[0.5]' isLast />
            </div>

            <div className='flex text-xs'>
              <SimpleColumn name='5' className='w-[100px]' />
              <SimpleColumn name='Batuk kronis' className='flex-[0.5]' />
              <SimpleColumn name={k[0].tb_5} className='flex-[0.5]' isLast />
            </div>

            <div className='flex text-xs'>
              <SimpleColumn name='6' className='w-[100px]' />
              <SimpleColumn
                name='Pembesaran klenjaerlimfe Ali, arsila, inguinal'
                className='flex-[0.5]'
              />
              <SimpleColumn name={k[0].tb_6} className='flex-[0.5]' isLast />
            </div>

            <div className='flex text-xs'>
              <SimpleColumn name='7' className='w-[100px]' />
              <SimpleColumn
                name='Pembekalan tulang/sendi panggul, lutut, falang'
                className='flex-[0.5]'
              />
              <SimpleColumn name={k[0].tb_7} className='flex-[0.5]' isLast />
            </div>

            <div className='flex text-xs'>
              <SimpleColumn name='8' className='w-[100px]' />
              <SimpleColumn name='Foto thoraks' className='flex-[0.5]' />
              <SimpleColumn name={k[0].tb_8} className='flex-[0.5]' isLast />
            </div>
          </div>
        ))}
      </div>
    )
  } else {
    return <p className='text-xs text-center font-medium'>Tidak ada data</p>
  }
}
