import type { Response } from '@/type'

import { put } from './api-2'

export interface ResumeMedisPerinatologi {
  identitas_bayi: {
    nama_bayi: string
    tgl_lahir: string
    no_rm: string
    no_reg: string
    umur: string
    jk: string
    tgl_masuk: string
    tgl_keluar: string
    dokter_anak: string
    nama_ibu: string
    ruang: string
    agama: string
    alamat: string
    dokter_obgyn: string
  }
}

const getResumeMedisPerinatologi = async ({
  no_reg,
  no_rm,
}: {
  no_reg: string
  no_rm: string
}): Promise<Response<ResumeMedisPerinatologi>> => {
  const response = await put('/v1/report-resume-medis-perinatologi', {
    no_reg,
    no_rm,
  })

  return response.data
}

export { getResumeMedisPerinatologi }
