import React from 'react'
import QRCode from 'react-qr-code'

import { IntervensiResikoJatuhAnak, Kategori, Ttd } from '../intervensi-anak'

function Cell({ value }: { value: boolean }) {
  return (
    <td className='text-center px-3 py-2'>
      {value ? (
        <span className='text-green-600 font-bold text-lg'>✓</span>
      ) : (
        <span className='text-gray-400 text-lg'>—</span>
      )}
    </td>
  )
}

function TtdBox({ label, ttd }: { label: string; ttd: Ttd }) {
  return (
    <div className='flex-1 border border-gray-300 text-center'>
      <div className='bg-gray-50 border-b border-gray-300 py-1 px-2 text-xs font-semibold text-gray-600 uppercase tracking-wide text-center'>
        {label}
      </div>

      <div className='py-3 px-2 flex flex-col items-center justify-center'>
        <QRCode value={ttd.nama} className='h-[50px] w-[50px]' />
        <div className='text-xs text-gray-700 font-medium mt-1 text-center'>
          {ttd.nama}
        </div>
      </div>
    </div>
  )
}

interface Props {
  data: IntervensiResikoJatuhAnak
}

export default function IntervensiResikoJatuhAnakReport({ data }: Props) {
  const grouped = data.intervensi.reduce<
    Record<string, typeof data.intervensi>
  >((acc, item) => {
    if (!acc[item.kategori]) acc[item.kategori] = []
    acc[item.kategori].push(item)
    return acc
  }, {})

  const kategoriOrder = [Kategori.ResikoRendah, Kategori.ResikoSedangDanTinggi]

  return (
    <div className='bg-white mx-auto font-sans'>
      {/* Header */}
      <div className='border-b-2 border-gray-800 px-6 py-4 flex items-center justify-between'>
        <div>
          <div className='text-xs text-gray-400 font-mono uppercase tracking-widest mb-0.5'>
            Formulir Keperawatan
          </div>
          <h1 className='text-lg font-bold text-gray-900'>
            Intervensi Risiko Jatuh Anak
          </h1>
        </div>
        <div className='text-right'>
          <div className='text-xs text-gray-400 font-mono'>Tanggal</div>
          <div className='font-mono font-semibold text-gray-800 text-sm'>
            {data.tanggal}
          </div>
        </div>
      </div>

      {/* Table */}
      <div className='overflow-x-auto'>
        <table className='w-full border-collapse'>
          <thead>
            <tr className='bg-gray-50'>
              <th className='border border-gray-300 px-3 py-2 text-center text-xs font-bold text-gray-700 uppercase tracking-wide w-12'>
                No.
              </th>
              <th className='border border-gray-300 px-4 py-2 text-left text-xs font-bold text-gray-700 uppercase tracking-wide'>
                Intervensi
              </th>
              <th
                colSpan={3}
                className='border border-gray-300 px-3 py-2 text-center text-xs font-bold text-gray-700 uppercase tracking-wide'
              >
                Tanggal / Sihif — {data.tanggal}
              </th>
            </tr>
            <tr className='bg-gray-50'>
              <th className='border border-gray-300' />
              <th className='border border-gray-300' />
              {(['PAGI', 'SORE', 'MALAM'] as const).map((s) => (
                <th
                  key={s}
                  className='border border-gray-300 px-3 py-1.5 text-center text-xs font-semibold text-gray-600 w-20'
                >
                  {s}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {kategoriOrder.map((kat) => {
              const items = grouped[kat]
              if (!items) return null
              const isRendah = kat === Kategori.ResikoRendah
              return (
                <React.Fragment key={kat}>
                  <tr>
                    <td
                      colSpan={2}
                      className={`border border-gray-300 px-4 py-2 font-semibold text-sm text-white ${
                        isRendah ? 'bg-blue-500' : 'bg-orange-500'
                      }`}
                    >
                      {kat}
                    </td>
                    <td
                      colSpan={3}
                      className={
                        isRendah
                          ? 'bg-blue-500 border border-gray-300'
                          : 'bg-orange-500 border border-gray-300'
                      }
                    />
                  </tr>
                  {items.map((item) => (
                    <tr
                      key={item.no}
                      className='hover:bg-gray-50 transition-colors'
                    >
                      <td className='border border-gray-300 text-center px-3 py-2 text-sm text-gray-500 font-mono'>
                        {item.no}
                      </td>
                      <td className='border border-gray-300 px-4 py-2 text-sm text-gray-800 leading-snug'>
                        {item.judul}
                      </td>
                      <Cell value={item.pagi} />
                      <Cell value={item.sore} />
                      <Cell value={item.malam} />
                    </tr>
                  ))}
                </React.Fragment>
              )
            })}
          </tbody>
        </table>
      </div>

      {/* TTD */}
      <div className='border-t border-gray-300 px-6 py-4'>
        <div className='text-xs font-semibold text-gray-500 uppercase tracking-wide mb-3'>
          Tanda Tangan Perawat
        </div>
        <div className='flex'>
          <TtdBox label='Pagi' ttd={data.ttd_pagi} />
          <TtdBox label='Sore' ttd={data.ttd_sore} />
          <TtdBox label='Malam' ttd={data.ttd_malam} />
        </div>
      </div>
    </div>
  )
}
