import { useState } from 'react'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { constants } from '@/utils/constants'

import ReasesmenResikoJatuhDewasaReport from './ListResikoJatuh'
import ButtonList from './component/ButtonList'
import { getReasesemeDewasa } from './reasesmen'

interface ReasesmenResikoJatuhAnakProps {
  isReport?: boolean
  noreg?: string
}

const FormulirReasesmenResikoJatuhDewasa = ({
  noreg = '',
  isReport = true,
}: ReasesmenResikoJatuhAnakProps) => {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.reasesmenResikoJatuhDewasa, noreg],
    queryFn: () =>
      getReasesemeDewasa({
        noreg: noreg!,
      }),
    enabled: !!noreg,
  })

  const res = data?.response ?? []

  const [selectedIndex, setSelectedIndex] = useState(0) // ✅ selalu di atas

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo>
      {isReport && <ReportHeader />}
      <div className='p-4'>
        <ButtonList items={res} onChange={(idx) => setSelectedIndex(idx)} />

        <h1 className='text-center text-black font-semibold mb-1 mt-4'>
          RE-ASESMEN RISIKO JATUH PADA PASIEN DEWASA BERDASARKAN PENILAIAN Skala
          Jatuh Morse / Morse Falls Scale (MFS)
        </h1>

        <p className='text-center'>
          Lakukan pengkajian (skoring) risiko jatuh pada saat terjadi perubahan
          kondisi pasien/therapi, saat pasien pindah ruangan lain, pasien risiko
          tinggi dikaji setiap 24 jam atau sesaat terjadi kasus jatuh.
        </p>

        <div className='mt-4'>
          {res && res.length > 0 && res[selectedIndex] ? (
            <ReasesmenResikoJatuhDewasaReport data={res[selectedIndex]} />
          ) : (
            <div>Kosong</div>
          )}
        </div>
      </div>
    </LayoutBorderNo>
  )
}

export default FormulirReasesmenResikoJatuhDewasa
