import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import { getPemantauanAsesmenUlangNyeri } from '@/services/pemantauan-asesmen-ulang-nyeri'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDateTime } from '@/utils/formatDate'

interface ReportPemantauanAsesmenUlangNyeriProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportPemantauanAsesmenUlangNyeri({
  isReport = false,
  noreg = '',
  no,
}: ReportPemantauanAsesmenUlangNyeriProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.pemantauanNyeri, noreg],
    queryFn: () => getPemantauanAsesmenUlangNyeri(noreg),
    enabled: !!noreg,
  })

  const res = data?.response ?? []

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          PEMANTAUAN ASESMEN ULANG NYERI
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='flex mt-4'>
          <SimpleColumn name='Tanggal / Pukul' className='text-xs flex-[1.2]' />
          <SimpleColumn name='Skor Nyeri' className='text-xs flex-[0.6]' />
          <SimpleColumn name='Nama Obat' className='text-xs flex-1' />
          <SimpleColumn name='Dosis & Frekuensi' className='text-xs flex-1' />
          <SimpleColumn name='Rute' className='text-xs flex-[0.6]' />
          <SimpleColumn
            name='Intervensi Non Farmakologi'
            className='text-xs flex-1'
          />
          <SimpleColumn
            name='Waktu Kaji Ulang'
            className='text-xs flex-[0.8]'
          />
          <SimpleColumn name='Perawat' className='text-xs flex-1' isLast />
        </div>

        {res.length == 0 && <EmptyPlaceholder />}

        {res.map((item, index) => (
          <div className='flex' key={item.id_nyeri ?? index}>
            <SimpleColumn
              name={formatDateTime(item.insert_dttm)}
              className='text-xs flex-[1.2]'
            />
            <SimpleColumn
              name={`${item.skor_nyeri ?? '-'}`}
              className='text-xs flex-[0.6]'
            />
            <SimpleColumn
              name={item.nama_obat || '-'}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={item.dosis_frekuensi || '-'}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={item.rute || '-'}
              className='text-xs flex-[0.6]'
            />
            <SimpleColumn
              name={`${item.non_farmakologi ?? '-'}`}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={`${item.waktu_kaji ?? '-'}`}
              className='text-xs flex-[0.8]'
            />
            <SimpleColumn
              name={item.perawat?.nama || '-'}
              className='text-xs flex-1'
              isLast
            />
          </div>
        ))}
      </div>
    </LayoutBorderNo>
  )
}
