import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import TableRow from '../neonatal/component/tablerow'
import TableHeader from './component/back-header'
import DownesScoreTable from './component/down-score'
import RisikoJatuhTable from './component/humpy-dumpy'
import FisikSkalaTable from './component/skala-nyeri'
import { getNeonatus } from './neonatus'

interface NeonatusProps {
  isReport?: boolean
  noreg?: string
}

const FormulirNeonatus = ({ noreg = '' }: NeonatusProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.neonatus, noreg],
    queryFn: () =>
      getNeonatus({
        noreg: noreg!,
      }),
    enabled: !!noreg,
  })

  const res = data?.response != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo>
      <div className='p-4'>
        <h1 className='text-center text-black font-semibold'>
          PENGKAJIAN AWAL KEPERAWATAN NEONATUS
        </h1>
        <p className='items-center flex text-center justify-center mb-7'>
          (Pengkajian harus selesai setelah pasien selesai diperiksa)
        </p>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}
        {/* Informasi Pasien */}
        <TableHeader label='IDENTITAS ORANG TUA' />

        <div className='mb-4 flex'>
          <div className='w-full border-y border-l border-r border-black px-2 py-1'>
            <div className='flex items-center justify-start gap-4'>
              <p className='w-[150px] text-sm font-semibold'>Nama Ayah</p>
              <p className='text-sm'>: {res?.profil_ortu.nama_ayah}</p>
            </div>
            <div className='flex items-center justify-start gap-4'>
              <p className='w-[150px] text-sm font-semibold'>Pendidikan Ayah</p>
              <p className='text-sm'>: {res?.profil_ortu.pendidikan_ayah}</p>
            </div>

            <div className='flex items-center justify-start gap-4'>
              <p className='w-[150px] text-sm font-semibold'>Alamat Ayah</p>
              <p className='text-sm'>: {res?.profil_ortu.alamat_ayah}</p>
            </div>
          </div>
          <div className='w-full border-y border-black border-r px-2 py-1'>
            <div className='flex items-center '>
              <p className='w-[180px] text-sm font-semibold'>Nama Ibu </p>
              <p className='text-sm'>: {res?.profil_ortu.nama_ibu}</p>
            </div>
            <div className='flex items-center'>
              <p className='w-[180px] text-sm font-semibold'>Pendidikan Ibu</p>
              <p className='text-sm'>: {res?.profil_ortu.pendidikan_ibu}</p>
            </div>
            <div className='flex items-center'>
              <p className='w-[180px] text-sm font-semibold'>Alamat Ibu </p>
              <p className='text-sm'>: {res?.profil_ortu.alamat_ibu}</p>
            </div>
          </div>
        </div>

        <TableHeader label='RIWAYAT KEHAMILAN' />
        <table className='w-full border-collapse border-x border-b border-t border-black mb-10'>
          <TableRow
            label='Status Kehamilan  '
            value={
              'G: ' +
              res?.asesmen.status_kehamilan_g +
              ' , P: ' +
              res?.asesmen.status_kehamilan_p +
              ' , A: ' +
              res?.asesmen.status_kehamilan_a +
              ' , H: ' +
              res?.asesmen.status_kehamilan_h
            }
          />
          <TableRow
            label='Periksa Antenatal  '
            value={res?.asesmen.pemeriksaan_antenatal}
          />
          <TableRow
            label='Komplikasi Antenatal  '
            value={res?.asesmen.komplikasi_antenatal}
          />
        </table>

        <TableHeader label='KEADAAN BAYI SAAT LAHIR' />
        <table className='w-full border-collapse border-x border-b border-t border-black mb-10'>
          <TableRow
            label='Jenis Persalinan  '
            value={res?.asesmen.kebidanan_jenis_persalinan}
          />
          <TableRow
            label='BB Lahir  '
            value={res?.asesmen.kebidanan_lama_persalinan}
          />
          <TableRow
            label='Lama Persalinan  '
            value={res?.asesmen.kebidanan_lama_persalinan}
          />
          <TableRow
            label='Waktu Pecah Ketubah  '
            value={res?.asesmen.kebidanan_pecah_ketuban}
          />
          <TableRow
            label='Nilai APGAR  '
            value={res?.asesmen.kebidanan_apgar}
          />
          <TableRow
            label='Umur Kehamilan  '
            value={res?.asesmen.kebidanan_umur_kehamilan}
          />
          <TableRow
            label='Kelainan Saat Dilahirkan  '
            value={res?.asesmen.kebidanan_kelainan_saat_dilahirkan}
          />
        </table>

        <TableHeader label='ALERGI/REAKSI' />
        <div className='flex text-xs  mt-2'>
          <SimpleColumn head name='MAKANAN' />
          <SimpleColumn head name='OBAT' />
          <SimpleColumn head name='LAINNYA' isLast />
        </div>

        <div className='flex text-xs  mb-10'>
          <SimpleColumn name={res?.riwayat_alergi.makanan} />
          <SimpleColumn name={res?.riwayat_alergi.obat} />
          <SimpleColumn name={res?.riwayat_alergi.lainnya} isLast />
        </div>

        <TableHeader label='ANAMNESA' />
        <table className='w-full border-collapse border-x border-b border-black mb-10'>
          <tbody>
            <TableRow
              label='Tanggal'
              value={res?.asesmen.insert_dttm || '2 Mei 2026 19:07:26 WIB'}
            />
            <TableRow
              label='Pengkajian'
              value={res?.asesmen?.anamnesa || 'Allowanamnese'}
            />
            <TableRow
              label='Cara Masuk'
              value={res?.asesmen?.cara_masuk || 'Tempat Tidur Dorong'}
            />
            <TableRow
              label='Asal Pasien'
              value={res?.asesmen?.asal_pasien || 'Rujukan'}
            />
            <TableRow
              label='BB saat masuk Rumah Sakit'
              value={
                res?.asesmen?.bb_saat_masuk
                  ? `${res.asesmen.bb_saat_masuk} gram`
                  : '2600 gram'
              }
            />
            <TableRow
              label='Keluhan Utama'
              value={
                res?.asesmen?.keluhan_utama ||
                'sesak mulai usia 1hari,sianosis lingkar perut 28 cm gembung ada'
              }
            />
          </tbody>
        </table>

        <TableHeader label='RIWAYAT PERSALINAN MASA LALU' />
        <div className='flex text-xs  mt-2'>
          <SimpleColumn head name='NO.' className='w-[90px]' />
          <SimpleColumn head name='Jenis Kelamin' />
          <SimpleColumn head name='Berat Badan' />
          <SimpleColumn head name='Keadaan Saat Ini' />
          <SimpleColumn head name='Jenis Persalinan' />
          <SimpleColumn head name='Komplikasi Persalinan' isLast />
        </div>

        {res.riwayat_persalinan.map((item, index) => (
          <div className='flex text-xs mb-10  '>
            <SimpleColumn name={String(index + 1)} className='w-[90px]' />
            <SimpleColumn name={item.jenis_kelamin} />
            <SimpleColumn name={item.berat_badan} />
            <SimpleColumn name={item.keadaan_saat_ini} />
            <SimpleColumn name={item.jenis_persalinan} />
            <SimpleColumn name={item.komplikasi_persalinan} isLast />
          </div>
        ))}

        <>
          {/* RIWAYAT PSIKOLOSOSIAL BUDAYA */}
          <TableHeader label='RIWAYAT PSIKOLOSOSIAL BUDAYA' />
          <table className='w-full border-collapse border-x border-b border-black mb-10'>
            <tbody>
              <TableRow
                label='Penerima Ibu terhadap kelahiran bayi'
                value={res?.asesmen?.penerima_ibu || 'Menerima'}
              />
              <TableRow
                label='Penerima ayah terhadap kehadiran bayi'
                value={res?.asesmen?.penerima_ayah || 'Menerima'}
              />
              <TableRow
                label='Hubungan ibu dengan ayah'
                value={res?.asesmen?.hubungan_ibu || 'Baik'}
              />
              <TableRow
                label='Kebiasaan yang dilakukan / tidak boleh dilakukan pada masa kehamilan'
                value={res?.asesmen?.kebiasaan_dilakukan}
              />
            </tbody>
          </table>

          {/* NUTRISI */}
          <TableHeader label='NUTRISI' />
          <table className='w-full border-collapse border-x border-b border-black mb-10'>
            <tbody>
              <TableRow label='ASI' value={res?.asesmen?.nutrisi_asi} />
              <TableRow label='PASI' value={res?.asesmen?.nutrisi_pasi} />
            </tbody>
          </table>
        </>

        <>
          {/* ELIMINASI */}
          <TableHeader label='ELIMINASI' />
          <table className='w-full border-collapse border-x border-b border-black mb-10'>
            <tbody>
              <TableRow
                label='Miksi'
                value={res?.asesmen?.eliminasi_miksi || 'Sudah'}
              />
              <TableRow
                label='Defikasi'
                value={
                  res?.asesmen?.eliminasi_defikasi ||
                  'Sudah, Warna ...hitam kecoklatan (meconium)'
                }
              />
            </tbody>
          </table>

          {/* PEMERIKSAAN FISIK */}
          <TableHeader label='PEMERIKSAAN FISIK' />
          <table className='w-full border-collapse border-x border-b border-black mb-10'>
            <tbody>
              <TableRow
                label='Suara Napas'
                value={res?.fisik.suara_napas || 'Ronchi'}
              />
              <TableRow
                label='Ekstremitas'
                value={res?.fisik.ekstremitas || 'Lemah'}
              />
              <TableRow
                label='Tangisan'
                value={res?.fisik.tangisan || 'Kurang Kuat'}
              />
              <TableRow label='Gerakan' value={res?.fisik.gerakan || 'Lemah'} />
            </tbody>
          </table>
        </>

        <>
          {/* VITAL SIGN */}
          <TableHeader label='VITAL SIGN' />
          <table className='w-full border-collapse border-x border-b border-black mb-10'>
            <tbody>
              <TableRow
                label='GCS'
                value={`E:${res?.vital_sign?.gcs_e ?? '-'} V:${res?.vital_sign?.gcs_v ?? '-'} M:${res?.vital_sign?.gcs_m ?? '-'}`}
              />
              <TableRow label='Kesadaran' value={res?.vital_sign?.kesadaran} />
              <TableRow label='Tekanan Darah' value={res?.vital_sign?.td} />
              <TableRow
                label='Pernapasan'
                value={res?.vital_sign?.pernafasan}
              />
              <TableRow label='Nadi' value={res?.vital_sign?.nadi} />
              <TableRow label='Sp O2' value={res?.vital_sign?.spo2} />
              <TableRow label='Suhu' value={res?.vital_sign?.suhu} />
              <TableRow label='Berat Badan' value={res?.vital_sign?.bb} />
              <TableRow label='Tinggi Badan' value={res?.vital_sign?.tb} />
              <TableRow label='Pupil' value={res?.vital_sign?.pupil} />
              <TableRow label='Akral' value={res?.vital_sign?.akral} />
              <TableRow
                label='Reaksi Cahaya Kiri'
                value={res?.vital_sign?.reaksi_cahaya_kiri}
              />
              <TableRow
                label='Reaksi Cahaya Kanan'
                value={res?.vital_sign?.reaksi_cahaya_kanan}
              />
              <TableRow
                label='Jalan Nafas'
                value={res?.vital_sign?.jalan_nafas}
              />
            </tbody>
          </table>
        </>

        <TableHeader label='DOWNES SCORE' />
        <DownesScoreTable
          data={{
            nifas: res.down_score.nifas,
            sianosis: res.down_score.sianosis,
            retraksi: res.down_score.retraksi,
            air_entry: res.down_score.air_entry,
            merintih: res.down_score.merintih,
            total: res.down_score.total,
          }}
        />
        <TableHeader label='RESPONSE NYERI' />
        <FisikSkalaTable
          data={{
            postur_tubuh: res.nyeri_nips.postur_tubuh,
            pola_tidur: res.nyeri_nips.pola_tidur,
            ekspresi_wajah: res.nyeri_nips.ekspresi_wajah,
            tangisa: res.nyeri_nips.tangisa,
            warna: res.nyeri_nips.warna,
            respirasi: res.nyeri_nips.respirasi,
            denyut_jantung: res.nyeri_nips.denyut_jantung,
            saurasi_oksigen: res.nyeri_nips.saurasi_oksigen,
            tekanan_darah: res.nyeri_nips.tekanan_darah,
            perepsi_perawat: res.nyeri_nips.perepsi_perawat,
            total: res.nyeri_nips.total,
          }}
        />

        <TableHeader label='PENILAIAN RISIKO JATUH ANAK HUMPY DUMPY' />

        <RisikoJatuhTable
          data={{
            noreg: '',
            umur: res.resiko_jatuh.umur,
            jenis_kelamin: res.resiko_jatuh.jenis_kelamin,
            diagnosa: res.resiko_jatuh.diagnosa,
            gangguan_kognitif: res.resiko_jatuh.gangguan_kognitif,
            faktor_lingkungan: res.resiko_jatuh.faktor_lingkungan,
            respon_lingkungan: res.resiko_jatuh.respon_lingkungan,
            penggunaan_obat_obatan: res.resiko_jatuh.penggunaan_obat_obatan,
            skor: res.resiko_jatuh.skor,
          }}
        />

        <>
          {/* VITAL SIGN */}
          <TableHeader label='KEBUTUHAN EDUKASI' />
          <table className='w-full border-collapse border-x border-b border-black mb-10'>
            <tbody>
              <TableRow
                label='Terdapat hambatan dalam pembelajaran'
                value={res.asesmen.kebutuhan_hambatan_pembelajaran}
              />

              <TableRow
                label='Kebutuhan pembelajaran keluarga'
                value={res.asesmen.kebutuhan_pembelajaran_keluarga}
              />

              <TableRow
                label='Dibutuhkan terjemah'
                value={res.asesmen.butuh_penerjemah}
              />
            </tbody>
          </table>
        </>

        <div className='flex text-xs'>
          <SimpleColumn head name='NO.' className='w-[90px]' />
          <SimpleColumn
            head
            name='DIAGNOSA KEPERAWATAN'
            className='w-[350px]'
          />
          <SimpleColumn
            head
            name='TINDAKAN KEPERAWATAN DAN KOLABORASI '
            isLast
          />
        </div>

        <>
          {res.asuhan.map((item, index) => (
            <div
              key={index}
              className='flex text-[11px] border border-black break-inside-avoid'
            >
              <div className='w-[90px] border-r border-black  p-2 font-bold '>
                {index + 1}
              </div>

              {/* Kolom Diagnosa */}
              <div className='border-r w-[350px] border-black p-2 font-bold uppercase'>
                {item.diagnosa?.judul}
              </div>

              <div className='p-2 space-y-4 w-[490px]'>
                <section>
                  <h3 className='font-bold uppercase mb-1'>TINDAKAN</h3>
                  <div className='whitespace-pre-line'>
                    {item.implementasi?.[0]?.deskripsi}
                  </div>
                  <p className='mt-2 italic font-semibold'>
                    Pelaksana: {item.perawat?.nama}
                  </p>
                </section>

                {/* INTERVENSI KEPERAWATAN */}
                <section>
                  <h3 className='font-bold uppercase mb-1'>
                    INTERVENSI KEPERAWATAN
                  </h3>
                  <ul className='list-none space-y-0.5'>
                    {item.deskripsi_siki?.map((siki, i) => (
                      <li key={i}>{siki.nama_siki}</li>
                    ))}
                  </ul>
                </section>

                {/* MASALAH KEPERAWATAN */}
                <section>
                  <h3 className='font-bold uppercase mb-1'>
                    MASALAH KEPERAWATAN
                  </h3>
                  <ul className='list-none space-y-0.5'>
                    {item.deskripsi_slki?.map((slki, i) => (
                      <li key={i}>{slki.nama_sllki}</li>
                    ))}
                  </ul>
                </section>
              </div>
            </div>
          ))}
        </>

        <>
          {/* VITAL SIGN */}
          <TableHeader label='RENCANA KEPERAWATAN INTERDISIPLIN/REFERAL' />
          <table className='w-full border-collapse border-x border-b border-black mb-10'>
            <tbody>
              <TableRow
                label='Diet dan Nutrisi'
                value={res.asesmen.rencana_farmasi}
              />

              <TableRow
                label='Konseling Menyesui'
                value={res.asesmen.rencana_konseling}
              />
            </tbody>
          </table>
        </>

        <div className='flex flex-col items-center justify-center p-4 mt-8 bg-white font-sans text-black'>
          {/* Label Atas */}
          <div className='text-center space-y-1 mb-2'>
            <p className='text-[12px] md:text-sm font-medium'>
              Tanggal/Pukul : {res.asesmen.insert_dttm}
            </p>
            <p className='text-[12px] md:text-sm font-medium'>
              Perawat yang melakukan pengkajian
            </p>
          </div>

          {/* Kontainer QR Code */}
          <div className='relative w-24 h-24 md:w-32 md:h-32 mb-3'>
            {/* Menggunakan img untuk placeholder QR Code seperti di gambar */}
            <QRCode className='h-[100px] w-[100px]' value={res.perawat.nama} />
          </div>

          {/* Nama Perawat dengan Garis Bawah */}
          <div className='text-center'>
            <p className='text-sm md:text-base font-bold underline decoration-1 underline-offset-4 capitalize'>
              ( {res.perawat.nama} )
            </p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}

export default FormulirNeonatus
