import type { Response } from '@/type'

import { put } from './api-2'

export interface InstruksiMedisFarmakologiReport {
  id: number
  insert_dttm: string
  nama_obat: string
  dosis: string
  frekuensi: string
  jam_diberi: string
  cara_pemberian: string
  jumlah_obat: number
  sisa_obat: string
  nama_verifikasi: string
  keterangan_verifikasi: string
  verifikasi_at: string
  user: {
    nama: string
  }
}

const getInstruksiMedisFarmakologiReport = async (
  no_reg: string,
): Promise<Response<InstruksiMedisFarmakologiReport[]>> => {
  const response = await put('/v1/instruksi-medis-farmakologi', { no_reg })

  return response.data
}

export { getInstruksiMedisFarmakologiReport }
