import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import { asesmenNyeriIcon } from '@/assets/images/asesmen_nyeri'
import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import Text from '@/components/text'
import { LaborTable } from '@/features/pasien-pulang/rekam-medis/components/labor-table'
import { RadiologiTable } from '@/features/pasien-pulang/rekam-medis/components/radiologi-table'
import { TextTitle } from '@/features/pasien-pulang/rekam-medis/components/text-title'
import TablePengkajianResikoJatuhRajal from '@/features/pasien/components/asesmen-awal-keperawatan-igd/table-pengkajian-resiko-jatuh-rajal'
import TableFlaccRajal from '@/features/pasien/triase/table-flacc-rajal'
import { getAsesmenRajal } from '@/services/asesmen-dokter-igd'
import { usePasienStore } from '@/store/pasien.store'
// import { usePasienStore } from '@/store/pasien.store'
import { constants, toHeaderNo, toHeaderTitle } from '@/utils/constants'
import { formatDate } from '@/utils/formatDate'

interface ReportRawatInapProps {
  isReport?: boolean
  noreg?: string
  norm?: string
  no?: string
}

export default function ReportRawatInap({
  isReport = false,
  noreg,
  norm,
}: ReportRawatInapProps) {
  // store
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.asesmenRajal, noreg],
    queryFn: () => getAsesmenRajal({ noreg: noreg!, noRm: norm! }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : null
  console.log('res ', res)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.asesmen_perawat.riwayat_penyakit_terdahulu == '')
    return <EmptyPlaceholder />

  return (
    <>
      <LayoutBorderNo no={toHeaderNo(res.asesmen_dokter.kd_bagian)}>
        {isReport && <ReportHeader />}

        {/* Content */}
        <div className='p-2 text-xs'>
          <h1 className='text-center text-black font-semibold my-4'>
            {toHeaderTitle(res.asesmen_dokter.kd_bagian)}
            {/* Assesmen Pasien Rawat Jalan */}
          </h1>

          <div className='flex justify-between mb-4'>
            <p className='text-xs'>
              Diisi oleh perawat Poliklinik dengan lengkap (Awal)
            </p>
            <p className='text-xs'>
              Tanggal : {formatDate(res.asesmen_dokter.insert_dttm)}
            </p>
          </div>

          <Text
            kStyle='min-w-[150px]'
            k='RPT (Tuliskan)'
            v={res.asesmen_perawat.riwayat_penyakit_terdahulu}
          />
          <Text
            kStyle='min-w-[150px]'
            k='Riwayat Alergi'
            v='OBAT: MAKANAN: LAINNYA:'
          />

          <p className='flex-1 font-semibold my-4'>Skala Nyeri</p>
          <div className='flex p-4'>
            <div className='flex flex-col flex-1 items-center justify-center p-4'>
              <img
                src={toScoreNyeri(res.asesmen_perawat.skala_nyeri)}
                className='h-[100px] object-contain mb-4'
              />
              <Text kStyle='min-w-[16px]' k='Skala Nyeri' />
            </div>
            <div className='flex flex-col flex-1 p-4'>
              <Text
                kStyle='min-w-[16px]'
                k='P'
                v={res.asesmen_perawat.skala_nyeri_p}
              />
              <Text
                kStyle='min-w-[16px]'
                k='Q'
                v={res.asesmen_perawat.skala_nyeri_q}
              />
              <Text
                kStyle='min-w-[16px]'
                k='R'
                v={res.asesmen_perawat.skala_nyeri_r}
              />
              <Text
                kStyle='min-w-[16px]'
                k='S'
                v={res.asesmen_perawat.skala_nyeri_s}
              />
              <Text
                kStyle='min-w-[16px]'
                k='T'
                v={res.asesmen_perawat.skala_nyeri_t}
              />
            </div>
          </div>
          <p className='flex-1 font-semibold my-4'>Skala FLACC</p>
          {/* Skala FLACC */}
          <TableFlaccRajal data={res.asesmen_perawat} />
          {/* Skala FLACC */}

          <p className='flex-1 font-semibold my-4'>
            ASESMEN RESIKO JATUH RAWAT JALAN <br />
            GET UP AND GO TEST
          </p>

          <TablePengkajianResikoJatuhRajal data={res.asesmen_perawat} />

          <p className='text-xs mb-4'>
            Hasil Kajian Skrining Resiko Jatuh:
            {res.asesmen_perawat.aseskep_hasil_kaji_rj} Tindakan:{' '}
            {res.asesmen_perawat.aseskep_hasil_kaji_rj_tind}
          </p>

          <Text
            kStyle='min-w-[150px]'
            k='Keluhan Sekarang'
            v={res.asesmen_perawat.riwayat_penyakit_terdahulu}
          />
          <p className='flex-1 font-semibold my-4'>Vital Sign</p>
          <div>
            <Text
              kStyle='min-w-[150px]'
              k='TD'
              v={`${res.vital_sign.td} mmHg`}
            />
            <Text
              kStyle='min-w-[150px]'
              k='N'
              v={`${res.vital_sign.nadi} /mnt`}
            />
            <Text
              kStyle='min-w-[150px]'
              k='Pernafasan'
              v={`${res.vital_sign.pernafasan} /mnt`}
            />
            <Text
              kStyle='min-w-[150px]'
              k='Suhu'
              v={`${res.vital_sign.suhu} °C`}
            />
            <Text
              kStyle='min-w-[150px]'
              k='TB'
              v={`${res.vital_sign.tinggi_badan} cm`}
            />
            <Text
              kStyle='min-w-[150px]'
              k='BB'
              v={`${res.vital_sign.berat_badan} kg`}
            />
          </div>

          <div className='my-4' />

          <Text
            kStyle='min-w-[150px]'
            k='Anamnese'
            v={`${res.asesmen_dokter.asesmed_anamnesa}`}
          />
          <Text
            kStyle='min-w-[150px]'
            k='Pemeriksaan Fisik'
            v={`${res.asesmen_dokter.asesmed_pem_fisik}`}
          />
          <p className='flex-1 font-semibold my-4'>Penunjang</p>
          <div>
            <TextTitle title='Laboratorium' />
            <LaborTable data={res != null ? res.labor : []} />
          </div>
          <div>
            <TextTitle title='Pemeriksaan Lain' />
            <RadiologiTable data={res != null ? res.radiologi : []} />
          </div>
          <p className='flex-1 font-semibold mt-4'>Diagnosa</p>
          <div>
            {(res.diagnosa ?? []).map((i, index) => (
              <p className='flex-1 text-xs' key={index}>
                ({i.diagnosa}) {i.description}
              </p>
            ))}
          </div>
          <p className='flex-1 font-semibold mt-4'>Terapi</p>
          <div>
            {(res.terapi ?? []).map((i, index) => (
              <p className='flex-1 text-xs' key={index}>
                ({i.nama_obat}) {`${i.jumlah} ${i.satuan}`}
              </p>
            ))}
          </div>
        </div>
        {/* Content */}

        <div className='flex items-start justify-between'>
          <div className='p-2 mb-1 m-2'>
            <div className='flex flex-col gap-4 items-center text-center text-xs'>
              {pasien != null && pasien.nama_pasien != '' && (
                <>
                  <p className='text-xs'>Pasien / Keluarga</p>
                  <QRCode
                    value={pasien.nama_pasien ?? '-'}
                    className='w-[50px] h-[50px] object-contain'
                  />
                  <p className=''>({pasien.nama_pasien ?? '-'})</p>
                </>
              )}
            </div>
          </div>

          <div className='p-2 mb-1 m-2'>
            <div className='flex flex-col gap-4 items-center text-center text-xs'>
              {res != null && res.asesmen_perawat.namaperawat != '' && (
                <>
                  <p className='text-xs'>Perawat</p>
                  <QRCode
                    value={res.asesmen_perawat.namaperawat ?? '-'}
                    className='w-[50px] h-[50px] object-contain'
                  />
                  <p className=''>({res.asesmen_perawat.namaperawat ?? '-'})</p>
                </>
              )}
            </div>
          </div>
          <div className='p-2 mb-1 m-2'>
            <div className='flex flex-col gap-4 items-center text-center text-xs'>
              {res != null && res.asesmen_dokter.dokter != '' && (
                <>
                  <p className='text-xs'>Dokter </p>
                  <QRCode
                    value={res.asesmen_dokter.dokter ?? '-'}
                    className='w-[50px] h-[50px] object-contain'
                  />
                  <p className=''>({res.asesmen_dokter.dokter ?? '-'})</p>
                </>
              )}
            </div>
          </div>
        </div>
      </LayoutBorderNo>
    </>
  )
}

function toScoreNyeri(n: number) {
  if (n == 1 || n == 2) {
    return asesmenNyeriIcon.AN1
  }

  if (n == 3 || n == 4) {
    return asesmenNyeriIcon.AN2
  }

  if (n == 5 || n == 6) {
    return asesmenNyeriIcon.AN3
  }

  if (n == 7 || n == 8) {
    return asesmenNyeriIcon.AN4
  }

  if (n == 9 || n == 10) {
    return asesmenNyeriIcon.AN5
  }

  return asesmenNyeriIcon.AN1
}
