import type { Response } from '@/type'

import { patch } from './api-2'

export interface PemantauanAsesmenUlangNyeri {
  id_nyeri: number
  insert_dttm: string
  nama_obat: string
  dosis_frekuensi: string
  rute: string
  skor_nyeri: number
  non_farmakologi: number
  waktu_kaji: number
  perawat: {
    nama: string
  }
}

const getPemantauanAsesmenUlangNyeri = async (
  noreg: string,
): Promise<Response<PemantauanAsesmenUlangNyeri[]>> => {
  const response = await patch('/v4/asesmen-ulang-nyeri', { noreg })

  return response.data
}

export { getPemantauanAsesmenUlangNyeri }
