import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import Text from '@/components/text'
import { getAsuhanMedisPascaBedah } from '@/services/asuhan-medis-pasca-bedah'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate } from '@/utils/formatDate'

interface ReportAsuhanMedisPascaBedahProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportAsuhanMedisPascaBedah({
  isReport = false,
  noreg = '',
  no,
}: ReportAsuhanMedisPascaBedahProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.asuhanMedisPascaBedah, noreg],
    queryFn: () => getAsuhanMedisPascaBedah(noreg),
    enabled: !!noreg,
  })

  const res = data?.response ?? []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res.length == 0) return <EmptyPlaceholder />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          ASUHAN MEDIS PASCA BEDAH
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        {res.map((item, index) => (
          <div className='border border-black my-2 p-2' key={item.id ?? index}>
            <p className='font-semibold mb-2'>DATA #{index + 1}</p>
            <Text
              kStyle='min-w-[250px]'
              k='Tanggal Tindakan'
              v={formatDate(item.tanggal_tindakan)}
            />
            <Text
              kStyle='min-w-[250px]'
              k='Tindakan Operasi'
              v={item.tindakan_operasi}
            />
            <Text kStyle='min-w-[250px]' k='Diet' v={item.diet} />
            <Text
              kStyle='min-w-[250px]'
              k='Ganti Verban'
              v={item.ganti_verban}
            />

            <Text isHeader k='Instruksi Dokter' kStyle='mt-2' />
            {(item.instruksi_dokter ?? []).map((instruksi, i) => (
              <p key={i}>- {instruksi.instruksi || '-'}</p>
            ))}

            <Text isHeader k='Hari' kStyle='mt-2' />
            <div className='flex'>
              <SimpleColumn name='No' className='text-xs flex-[0.3]' />
              <SimpleColumn name='Judul' className='text-xs flex-[3]' isLast />
            </div>
            {(item.hari ?? []).map((hari, i) => (
              <div className='flex' key={i}>
                <SimpleColumn
                  name={`${hari.no ?? i + 1}`}
                  className='text-xs flex-[0.3]'
                />
                <SimpleColumn
                  name={hari.judul || '-'}
                  className='text-xs flex-[3]'
                  isLast
                />
              </div>
            ))}

            <Text isHeader k='Yang Diperhatikan' kStyle='mt-2' />
            {(item.yang_diperhatikan ?? []).map((hal, i) => (
              <p key={i}>- {hal.keterangan || '-'}</p>
            ))}

            <Text isHeader k='Terapi Oral' kStyle='mt-2' />
            <div className='flex'>
              <SimpleColumn name='Nama Obat' className='text-xs flex-[1.5]' />
              <SimpleColumn name='Dosis' className='text-xs flex-1' />
              <SimpleColumn
                name='Frekuensi'
                className='text-xs flex-1'
                isLast
              />
            </div>
            {(item.terapi_oral ?? []).map((terapi, i) => (
              <div className='flex' key={i}>
                <SimpleColumn
                  name={terapi.namaObat || '-'}
                  className='text-xs flex-[1.5]'
                />
                <SimpleColumn
                  name={terapi.dosis || '-'}
                  className='text-xs flex-1'
                />
                <SimpleColumn
                  name={terapi.frekuensi || '-'}
                  className='text-xs flex-1'
                  isLast
                />
              </div>
            ))}

            <Text
              kStyle='min-w-[250px]'
              k='Tindak Lanjut'
              v={`${item.tindak_lanjut?.berobat_jalan || '-'} / ${
                item.tindak_lanjut?.kontrol || '-'
              }`}
            />
            <Text
              kStyle='min-w-[250px]'
              k='Dokter'
              v={item.dokter?.nama || '-'}
            />
          </div>
        ))}
      </div>
    </LayoutBorderNo>
  )
}
