import { post } from '@/services/api-2'
import type { Response } from '@/type'

export interface MonitorTransfusiDarah {
  id_transfusi: number
  insert_dttm: string
  noreg: string
  user_id: string
  kd_bagian: string
  no_kantung: string
  jenis_darah: string
  tgl_kadaluarsa: string
  gol_darah: string
  jam_pemberi: string
  reaksi: Reaksi[]
  perawat: Perawat
  bagian: Bagian
  pukul: string
  isi: string
  td: string
  nadi: string
  rr: string
  temp: string
}

export interface Bagian {
  kd_bag: string
  bagian: string
  pelayanan: string
}

export interface Perawat {
  id_perawat: string
  nama: string
  alamat: string
  jenis_kelamin: string
  status: string
}

export interface Reaksi {
  id_reaksi: number
  id_transfusi: number
  user_id: string
  insert_ddtm: Date
  noreg: string
  reaksi: string
  keterangan: string
}

// Converts JSON strings to/from your types
export class Convert {
  public static toMonitorTransfusiDarah(json: string): MonitorTransfusiDarah {
    return JSON.parse(json)
  }

  public static monitorTransfusiDarahToJson(
    value: MonitorTransfusiDarah,
  ): string {
    return JSON.stringify(value)
  }
}

const getMonitoringTransfusi = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<MonitorTransfusiDarah[]>> => {
  const response = await post(`/v4/monitoring-transfusi-darah/get`, {
    no_reg: noreg,
  })

  return response.data
}

export { getMonitoringTransfusi }
