/* ========================= */

type RowGroupProps = {
  no?: string
  title?: string
  children: React.ReactNode
}

const GRID = 'grid grid-cols-[50px_180px_1fr_80px]'

export function RowGroup({ no = '', title = '', children }: RowGroupProps) {
  return (
    <div className={`${GRID} border-b text-sm`}>
      <div className='border-r p-3  text-center'>{no}</div>
      <div className='border-r p-3'>{title}</div>
      <div className='col-span-2 divide-y'>{children}</div>
    </div>
  )
}

/* ========================= */

export function ViewRow({ keterangan = '', skor = 0, is_active }: ResikoJatuh) {
  return (
    <div
      className={`grid grid-cols-[1fr_80px] justify-between items-center p-3 ${
        is_active ? 'bg-green-300 font-semibold' : ''
      }`}
    >
      <span>{keterangan}</span>
      <span>{skor}</span>
    </div>
  )
}
