import { useState } from 'react'

import { IntervensiResikoJatuhDewasa } from '../intervensi-dewasa'

type Props = {
  items: IntervensiResikoJatuhDewasa[]
  onChange?: (index: number, item: IntervensiResikoJatuhDewasa) => void
}

export default function ButtonListIntervensi({ items, onChange }: Props) {
  const [isActive, setIsActive] = useState<number>(0)

  const handleClick = (index: number) => {
    setIsActive(index)
    onChange?.(index, items[index]) // ⬅️ kirim keluar
  }

  return (
    <div className='flex gap-2'>
      {items.map((item, index) => (
        <button
          key={index}
          onClick={() => handleClick(index)}
          className={`px-4 py-2 rounded ${
            isActive === index ? 'bg-green-500 text-white' : 'bg-gray-200'
          }`}
        >
          {item.tanggal}
        </button>
      ))}
    </div>
  )
}
