import { AsesmenAwalMedisIGD } from '@/models/asesmen-awal-medis-igd.model'
import { ReportAsesmenRajal } from '@/models/asesmen-rajal'
import type { AsesmenDokterIgd, Response } from '@/type'

import { get } from './api'
import { post, put } from './api-2'

const getAsesmenDokterIgd = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<AsesmenDokterIgd>> => {
  const response = await get(`/v1/asesmen-dokter-igd/${noreg}`)

  return response.data
}

const getAsesmenDokterIgdV2 = async ({
  noRm = '',
  noreg = '',
}: {
  noRm: string
  noreg: string
}): Promise<Response<AsesmenAwalMedisIGD>> => {
  const response = await put(
    `/v1/report-asesmen-awal-medis-dokter-igd-harapan`,
    {
      no_rm: noRm,
      no_reg: noreg,
      tanggal: '',
      person: 'Dokter',
      kd_bagian: 'IGD001',
      pelayanan: 'RAJAL',
    },
  )

  return response.data
}

const getAsesmenRajal = async ({
  noRm = '',
  noreg = '',
}: {
  noRm: string
  noreg: string
}): Promise<Response<ReportAsesmenRajal>> => {
  const response = await post(`/v1/report-asesmen-rajal`, {
    no_rm: noRm,
    no_reg: noreg,
  })

  return response.data
}

export { getAsesmenDokterIgd, getAsesmenDokterIgdV2, getAsesmenRajal }
