import type { Response } from '@/type'

import { put } from './api-2'

export interface ImplementasiKeperawatan {
  user: {
    id_perawat: string
    nama: string
  }
  bagian: {
    bagian: string
    pelayanan: string
  }
  insert_dttm: string
  deskripsi: string
}

const getImplementasiKeperawatan = async (
  no_reg: string,
): Promise<Response<ImplementasiKeperawatan[]>> => {
  const response = await put('/v1/report-implementasi-keperawatan', {
    no_reg,
  })

  return response.data
}

export { getImplementasiKeperawatan }
