import type { AsesmenAwalMedisRanap } from '@/models/asesmen-awal-medis-ranap'
import type { Response } from '@/type'

import { post } from './api-2'

const getAsesmenAwalMedisRanap = async ({
  noReg,
}: {
  noReg: string
}): Promise<Response<AsesmenAwalMedisRanap>> => {
  const response = await post(`/v1/report-asesmen-ranap`, {
    no_reg: noReg,
  })

  return response.data
}

export { getAsesmenAwalMedisRanap }
