import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import TableRow from './component/tablerow'
import { getNeonatal } from './neon'

interface NeonatalProps {
  isReport?: boolean
  noreg?: string
}

const FormulirNeonatal = ({ noreg = '' }: NeonatalProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.neonatal, noreg],
    queryFn: () =>
      getNeonatal({
        noreg: noreg!,
      }),
    enabled: !!noreg,
  })

  const res = data?.response != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo>
      <div className='p-4'>
        <h1 className='text-center text-black font-semibold'>
          PENGKAJIAN ASUHAN KEBIDANAN
        </h1>
        <h1 className='text-center text-black font-semibold mb-3'>
          PADA BAYI BARU LAHIR
        </h1>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}
        {/* Informasi Pasien */}

        <table className='w-full border-collapse border-x border-b border-t border-black'>
          <tbody>
            <tr>
              <td className='border-r border-black p-1 w-1/4 font-semibold text-center'>
                Diagnosa Medis <br /> / Dokter
              </td>
              <td className='p-1 italic'>{''}</td>
            </tr>
            <tr>
              <td className='border-t border-r border-black p-1 w-1/4 font-semibold text-center align-middle'>
                Ruang / Kelas
              </td>
              <td className='border-t border-black p-1 whitespace-pre-line'>
                {res?.asesmen.ruangan}
              </td>
            </tr>
            <TableRow label='Tanggal/Pukul' value={res?.tanggal} />
            <TableRow
              label='Datang Dengan'
              value={res?.asesmen.datang_dengan}
            />
          </tbody>
        </table>

        <br />
        <h1 className='font-semibold text-lg'>ANAMNESA DATA SUBJECTIF</h1>
        <h2 className='font-semibold text-lg'>
          1. Riwayat Penyakit Kehamilan :
        </h2>
        <table className='w-full border-collapse border-x border-b border-t border-black mb-5'>
          <TableRow
            label='Status GPA'
            value={`G : ${res?.asesmen?.status_g} P : ${res?.asesmen?.status_p} A : ${res?.asesmen?.status_a}`}
          />
          <TableRow
            label='Riwayat Status Kehamilan'
            value={res.asesmen.status_kehamilan}
          />
        </table>

        <h2 className='font-semibold text-lg'>
          2. Riwayat Persalinan Sekarang (jelaskan) :
        </h2>
        <table className='w-full border-collapse border-x border-b border-t border-black mb-10'>
          <TableRow
            label='Penolong Persalinan'
            value={res?.asesmen.penolong_persalinan}
          />
          <TableRow
            label='Jenis Persalinan'
            value={res?.asesmen.jenis_persalinan}
          />
          <TableRow label='DLL' value={res?.asesmen.dll} />
        </table>

        <>
          <h2 className='font-semibold text-lg'>PEMERIKSAAN FISIK</h2>

          {/* 1. KEPALA */}
          <h2 className='font-semibold text-lg uppercase'>1. Kepala</h2>
          <table className='w-full border-collapse border border-black mb-5'>
            <tbody>
              <TableRow label='Ubun-ubun' value={res?.fisik.ubun_ubun} />
              <TableRow
                label='Caput Succedenum'
                value={res?.fisik.caput_succedenum}
              />
              <TableRow
                label='Chepal Hematoma'
                value={res?.fisik.chepal_hematoma}
              />
              <TableRow
                label='Ukuran Lingkar Kepala'
                value={res?.fisik.ukuran_lingkar_kepala}
              />
            </tbody>
          </table>

          {/* 2. MATA */}
          <h2 className='font-semibold text-lg uppercase'>2. Mata</h2>
          <table className='w-full border-collapse border border-black mb-5'>
            <tbody>
              <TableRow label='Bentuk' value={res?.fisik.bentuk_mata} />
              <TableRow label='Kotoran' value={res?.fisik.kotoran_mata} />
              <TableRow
                label='Konjungtiva'
                value={res?.fisik.konjungtiva_mata}
              />
            </tbody>
          </table>

          {/* 3. HIDUNG */}
          <h2 className='font-semibold text-lg uppercase'>3. Hidung</h2>
          <table className='w-full border-collapse border border-black mb-5'>
            <tbody>
              <TableRow
                label='Bentuk Hidung'
                value={res?.fisik.bentuk_hidung}
              />
              <TableRow
                label='Pernafasan Cupping Hidung'
                value={res?.fisik.pernafasan_cupping_hidung}
              />
              <TableRow label='Sekret' value={res?.fisik.sekret_hidung} />
            </tbody>
          </table>

          {/* 4. MULUT */}
          <h2 className='font-semibold text-lg uppercase'>4. Mulut</h2>
          <table className='w-full border-collapse border border-black mb-5'>
            <tbody>
              <TableRow label='Warna Bibir' value={res?.fisik.warna_bibir} />
              <TableRow label='Palatum' value={res?.fisik.palatum_mulut} />
              <TableRow label='Lidah' value={res?.fisik.lidah} />
              <TableRow label='Gusi' value={res?.fisik.gusi} />
            </tbody>
          </table>

          {/* 5. TELINGA */}
          <h2 className='font-semibold text-lg uppercase'>5. Telinga</h2>
          <table className='w-full border-collapse border border-black mb-5'>
            <tbody>
              <TableRow label='Bentuk' value={res?.fisik.bentuk_telinga} />
              <TableRow
                label='Pengeluaran Cairan'
                value={res?.fisik.pengeluaran_cairan_telinga}
              />
            </tbody>
          </table>
        </>

        <>
          {/* 6. LEHER */}
          <h2 className='font-semibold text-lg uppercase'>6. Leher</h2>
          <table className='w-full border-collapse border border-black mb-5'>
            <tbody>
              <TableRow
                label='Pembengkakan Kelenjar'
                value={res?.fisik.pembengkakan_kelenjar_leher}
              />
              <TableRow
                label='Kelenjar Getah Bening'
                value={res?.fisik.kelenjar_getah_bening_leher}
              />
            </tbody>
          </table>

          {/* 7. DADA */}
          <h2 className='font-semibold text-lg uppercase'>7. Dada</h2>
          <table className='w-full border-collapse border border-black mb-5'>
            <tbody>
              <TableRow label='Bentuk Dada' value={res?.fisik.dada} />
              <TableRow label='Lingkar Dada' value={res?.fisik.lingkar_dada} />
            </tbody>
          </table>

          {/* 8. ABDOMEN */}
          <h2 className='font-semibold text-lg uppercase'>8. Abdomen</h2>
          <table className='w-full border-collapse border border-black mb-5'>
            <tbody>
              <TableRow label='Keadaan Tali Pusat' value={res?.fisik.abdomen} />
              <TableRow
                label='Perdarahan Tali Pusat'
                value={res?.fisik.keadaan_tali_pusat}
              />
              <TableRow
                label='Tanda Tanda Infeksi'
                value={res?.fisik.tanda_tanda_infeksi}
              />
              <TableRow
                label='Hernia Umbilikalis'
                value={res?.fisik.hernia_umbilikalis}
              />
            </tbody>
          </table>

          {/* 9. GENETALIA */}
          <h2 className='font-semibold text-lg uppercase'>9. Genetalia</h2>
          <div className='border-x border-t border-black p-1 font-semibold'>
            Laki-laki :
          </div>
          <table className='w-full border-collapse border border-black mb-5'>
            <tbody>
              <TableRow
                label='Lubang Uretra'
                value={res?.fisik.lubang_uretra}
              />
              <TableRow label='Testis' value={res?.fisik.testis} />
            </tbody>
          </table>
        </>

        <>
          {/* 10. KEADAAN PUNGGUNG */}
          <h2 className='font-semibold text-lg uppercase'>
            10. Keadaan Punggung
          </h2>
          <table className='w-full border-collapse border border-black mb-5'>
            <tbody>
              <TableRow
                label='Spina Bifida'
                value={res?.fisik.keadaan_tali_pusat}
              />
            </tbody>
          </table>

          {/* 11. ANUS */}
          <h2 className='font-semibold text-lg uppercase'>11. Anus</h2>
          <table className='w-full border-collapse border border-black mb-5'>
            <tbody>
              <TableRow label='Lubang' value={res?.fisik.anus} />
            </tbody>
          </table>

          {/* 12. EKSTREMITAS */}
          <h2 className='font-semibold text-lg uppercase'>12. Ekstremitas</h2>
          <table className='w-full border-collapse border border-black mb-5'>
            <tbody>
              <TableRow
                label='Gerakan Tangan'
                value={res?.fisik.gerakan_tangan}
              />
              <TableRow
                label='Jari-Jari Tangan'
                value={res?.fisik.jari_jari_tangan}
              />
              <TableRow label='Akrosisanosis' value={res?.fisik.akrosianosis} />
            </tbody>
          </table>

          {/* 13. EKSTREMITAS BAWAH */}
          <h2 className='font-semibold text-lg uppercase'>
            13. Ekstremitas Bawah
          </h2>
          <table className='w-full border-collapse border border-black mb-5'>
            <tbody>
              <TableRow label='Gerakan Kaki' value={res?.fisik.gerakan_kaki} />
              <TableRow
                label='Jari-Jari Kaki'
                value={res?.fisik.jari_jari_kaki}
              />
              <TableRow label='Akrosisanosis' value={res?.fisik.akrosianosis} />
            </tbody>
          </table>

          {/* 14. KULIT */}
          <h2 className='font-semibold text-lg uppercase'>14. Kulit</h2>
          <table className='w-full border-collapse border border-black mb-5'>
            <tbody>
              <TableRow label='Warna Kulit' value={res?.fisik.kulit} />
              <TableRow label='Tanda Lahir' value={res?.fisik.tanda_lahir} />
              <TableRow label='Verniks' value={res?.fisik.verniks} />
            </tbody>
          </table>
        </>
        <>
          {/* 15. REFLEKS */}
          <h2 className='font-semibold text-lg uppercase'>15. Refleks</h2>
          <table className='w-full border-collapse border border-black mb-5'>
            <tbody>
              <TableRow label='Refleks Moro' value={res?.fisik.refleks_moro} />
              <TableRow
                label='Refleks Rooting'
                value={res?.fisik.refleks_rooting}
              />
              <TableRow
                label='Refleks Graps/Piatar'
                value={res?.fisik.refleks_graps}
              />
              <TableRow
                label='Refleks Sucking'
                value={res?.fisik.refleks_sucking}
              />
              <TableRow
                label='Refleks Tonic Neck'
                value={res?.fisik.refleks_tonic_neck}
              />
              <TableRow
                label='Refleks Babinski'
                value={res?.fisik.refleks_babinski}
              />
            </tbody>
          </table>

          {/* 16. ANTROPEMETRI */}
          <h2 className='font-semibold text-lg uppercase'>16. Antropemetri</h2>
          <table className='w-full border-collapse border border-black mb-5'>
            <tbody>
              <TableRow
                label='Lingkar Kepala'
                value={res?.fisik.lingkar_kepala}
              />
              <TableRow label='Lingkar Dada' value={res?.fisik.lingkar_dada} />
            </tbody>
          </table>

          {/* 17. ELIMINASI */}
          <h2 className='font-semibold text-lg uppercase'>17. Eliminasi</h2>
          <table className='w-full border-collapse border border-black mb-5'>
            <tbody>
              <TableRow label='Miksi' value={res?.fisik.eliminasi_miksi} />
              <TableRow
                label='Meconeum'
                value={res?.fisik.eliminasi_meconeum}
              />
            </tbody>
          </table>
        </>

        <div className='flex text-xs'>
          <SimpleColumn head name='NO.' className='w-[90px]' />
          <SimpleColumn head name='DIAGNOSA KEBIDANAN' />
          <SimpleColumn
            head
            name='TINDAKAN KEBIDANAN '
            isLast
            className='w-[490px]'
          />
        </div>
        <div className='flex text-xs mb-10'>
          <SimpleColumn name='1.' className='w-[90px]' />
          <SimpleColumn name='DIAGNOSA KEBIDANAN' />
          <div
            className='flex  text-center justify-center items-center p-2 border-y border-black border-l
              isLast && border-r w-[490px]'
          >
            <div className='space-y-4'>
              {res?.kebidanan?.implementasi?.map((item, index) => (
                <div
                  key={item.id || index}
                  className='border-b flex justify-start border-gray-200 pb-3 last:border-0'
                >
                  {/* Loop Teks Deskripsi */}
                  <div className='text-sm  flex justify-start text-gray-700 leading-relaxed'>
                    <ul className='list-disc ml-5 text-start  justify-start'>
                      {item.deskripsi?.split('\n').map((line, idx) => (
                        <li key={idx} className='mb-1'>
                          {line}
                        </li>
                      ))}
                    </ul>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
        {/* Header */}

        <div className='flex flex-col gap-2 text-center justify-center items-center'>
          <QRCode value={''} className='h-[50px] w-[50px] items-center' />
          <p className=''>{res.nama_ppa}</p>
        </div>
      </div>
    </LayoutBorderNo>
  )
}

export default FormulirNeonatal
