import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import { getLaporanTbDewasa } from '@/services/laporan-tb-dewasa'
import { useAuthStore } from '@/store/auth.store'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportLaporanTbDewasaProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

const itemTb = [
  { key: 'tb_1', label: 'Batuk berdahak selama > 2-3 minggu' },
  { key: 'tb_2', label: 'Terasa nyeri dada' },
  { key: 'tb_3', label: 'Batuk berdarah' },
  { key: 'tb_4', label: 'Sesak nafas' },
  { key: 'tb_5', label: 'Demam hilang timbul' },
  { key: 'tb_6', label: 'Keringat malam hari tanpa aktivitas' },
  { key: 'tb_7', label: 'Pembesaran kelenjar getah bening > 2 mm' },
  { key: 'tb_8', label: 'Nafsu makan berkurang' },
  { key: 'tb_9', label: 'Berat badan menurun' },
  {
    key: 'tb_10',
    label: 'Riwayat kontak atau sedang kontak langsung dengan penderita TB',
  },
  {
    key: 'tb_11',
    label:
      'Pernah minum obat paru-paru kurang dari 1 bulan atau lebih dari 1 bulan',
  },
  { key: 'tb_12', label: 'Penyakit lain: DM, Asma, HIV, PPOK' },
] as const

function mark(value: string) {
  if (value == 'true' || value == '1' || value == 'ya') return '✓'
  return value || '-'
}

export default function ReportLaporanTbDewasa({
  isReport = false,
  noreg = '',
  no,
}: ReportLaporanTbDewasaProps) {
  const { pasien } = usePasienStore((state) => state)
  const { user } = useAuthStore((state) => state)
  const bagian = user?.kd_bagian || pasien?.kd_bagian || ''

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.tbDewasa, noreg, bagian],
    queryFn: () => getLaporanTbDewasa({ noreg, bagian }),
    enabled: !!noreg && !!bagian,
  })

  const res = data?.response

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return <EmptyPlaceholder />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          SKRINING TB DEWASA
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <p className='mt-2 font-semibold'>
          Petunjuk: Berikan tanda (✓) pada kolom yang sesuai dengan kondisi
          pasien.
        </p>
        <p>Tanggal: {res.tanggal || '-'}</p>

        <div className='flex mt-4'>
          <SimpleColumn name='No' className='text-xs flex-[0.3]' />
          <SimpleColumn
            name='Gejala / Faktor Risiko'
            className='text-xs flex-[3]'
          />
          <SimpleColumn name='Hasil' className='text-xs flex-[0.6]' isLast />
        </div>

        {itemTb.map((item, index) => (
          <div className='flex' key={item.key}>
            <SimpleColumn
              name={`${index + 1}`}
              className='text-xs flex-[0.3]'
            />
            <SimpleColumn name={item.label} className='text-xs flex-[3]' />
            <SimpleColumn
              name={mark(res[item.key])}
              className='text-xs flex-[0.6]'
              isLast
            />
          </div>
        ))}
      </div>
    </LayoutBorderNo>
  )
}
