import type { Pasien, Response } from '@/type'

import { post } from './api'

import { post as postApi } from './api'

const getPasienByPelayanan = async ({
  kd_bagian = '',
  date_from = '',
  date_to = '',
}: {
  kd_bagian: string
  date_from: string
  date_to: string
}): Promise<Response<Pasien[]>> => {
  const response = await post('/v1/antrean-pasien', {
    kd_bagian,
    date_from,
    date_to,
  })

  return response.data
}

const getPasienPulangByDate = async ({
  date = '',
}: {
  date: string
}): Promise<Response<Pasien[]>> => {
  const response = await post('/v1/pasien-pulang-by-date', {
    date: date,
  })

  return response.data
}

const getPasienPulangRanapByDate = async ({
  date = '',
}: {
  date: string
}): Promise<Response<Pasien[]>> => {
  const response = await postApi('/v1/pasien-pulang-ranap-by-date', {
    date: date,
  })

  return response.data
}

export {
  getPasienByPelayanan,
  getPasienPulangByDate,
  getPasienPulangRanapByDate,
}
