import { AsesmenAwalKeperawatanIGD } from '@/models/asesmen-awal-keperawatan-igd.model'
import { Response } from '@/type'

import { put } from './api-2'

const getAsesmenKeperawatanIgd = async ({
  no_reg,
  no_rm,
  tanggal,
}: {
  no_rm: string
  no_reg: string
  tanggal: string
}): Promise<Response<AsesmenAwalKeperawatanIGD>> => {
  const response = await put(`/v1/report-asesmen-awal-keperawatan-atau-bidan`, {
    kd_bagian: 'IGD001',
    no_reg: no_reg,
    no_rm: no_rm,
    pelayanan: 'rajal',
    person: 'Perawat',
    tanggal: tanggal,
  })

  return response.data
}

export { getAsesmenKeperawatanIgd }
