import { post } from '@/services/api-2'
import type { Response } from '@/type'

export interface TindakanTransfusiDarah {
  tanggal: string
  value1: boolean
  value2: boolean
  value3: boolean
  value4: boolean
  value5: boolean
  nama_pemberi: string
  nama_penerima: string
  ttd_pemberi: string
  ttd_penerima: string
}

const getTransfusi = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<TindakanTransfusiDarah>> => {
  const response = await post(`/v4/informasi-transfusi-darah/get`, {
    no_reg: noreg,
  })

  return response.data
}

export { getTransfusi }
