import QRCode from 'react-qr-code'
import { match } from 'ts-pattern'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { DiagnosaTable } from '@/features/pasien-pulang/rekam-medis/components/diagnosa-table'
import Medical from '@/features/pasien-pulang/rekam-medis/components/form-asesmen-medis-ranap/medical'
import Neurologi from '@/features/pasien-pulang/rekam-medis/components/form-asesmen-medis-ranap/neurologi'
import { LaborTable } from '@/features/pasien-pulang/rekam-medis/components/labor-table'
import { RadiologiTable } from '@/features/pasien-pulang/rekam-medis/components/radiologi-table'
import { TextTitle } from '@/features/pasien-pulang/rekam-medis/components/text-title'
import { AsesmenAwalMedisRanap, init } from '@/models/asesmen-awal-medis-ranap'
import { getAsesmenAwalMedisRanap } from '@/services/asesmen-awal-medis-ranap'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatTanggal } from '@/utils/formatDate'

import MedicalForm from './medical'
import PerawatRuanganForm from './perawat-ruangan'

interface ReportAsesmenAwalMedisRanapProps {
  isReport?: boolean
  noreg?: string
  norm?: string
  no?: string
}

const ReportAsesmenAwalMedisRanap = ({
  noreg,
  isReport,
}: ReportAsesmenAwalMedisRanapProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.asesmenAWalMedisRanap, noreg!],
    queryFn: () => getAsesmenAwalMedisRanap({ noReg: noreg! }),
    enabled: !!noreg,
  })

  const res = data?.response ?? (init as AsesmenAwalMedisRanap)
  console.log('res ', res)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.asesmen_dokter.asesmed_keluh_utama == '')
    return <EmptyPlaceholder />

  const dataMedical = {
    tanggalMasuk: formatTanggal(res?.asesmen_dokter.tanggal_masuk) || '',
    masukPukul: res?.asesmen_dokter.jam_masuk || '',
    keluhanUtama: res?.asesmen_dokter.asesmed_keluh_utama || '',
    telaah: res?.asesmen_dokter.asesmed_telaah || '',
    rptDll: res?.asesmen_dokter.asesmed_rwyt_dahulu || '',
    riwayatPenyakitKeluarga: res?.asesmen_dokter.asemen_penyakit_keluarga || '',
  }

  const dataRuangan = {
    keadaanUmum: res?.vital_sign.keadaan_umum,
    kesadaran: res?.fisik.kesadaran || '',
    vitalSign: {
      td: res?.vital_sign.td || '',
      n: res?.vital_sign.nadi || '',
      rr: res?.vital_sign.pernafasan || '',
      s: res?.vital_sign.suhu || '',
      tb: res?.vital_sign.tinggi_badan || '',
      bb: res?.vital_sign.berat_badan || '',
    },
    pemfisik: {
      kepala: res?.fisik.kepala || '',
      leher: res?.fisik.leher || '',
      dada: res?.fisik.dada || '',
      abdomen: res?.fisik.abdomen || '',
      punggung: res?.fisik.punggung || '',
      perut: res?.fisik.perut || '',
      genetalia: res?.fisik.genetalia || '',
      ekstremitas: res?.fisik.ekstremitas || '',
    },
  }

  return (
    <LayoutBorderNo>
      {isReport && <ReportHeader />}
      {render(res.asesmen_dokter.kd_bag, res)}

      <h1 className='text-center text-black font-semibold mb-4'>
        ASESMEN AWAL MEDIS PASIEN DI RUANG RAWAT INAP
      </h1>

      {/* Informasi Pasien */}
      {pasien != null && (
        <InformasiPasien
          nama={pasien.nama_pasien}
          noRM={pasien.no_rm}
          tanggalLahir={pasien.tgl_lahir}
          jk={pasien.jenis_kelamin}
        />
      )}

      {/* Subyektif */}
      <div className='border border-black'>
        <MedicalForm data={dataMedical}></MedicalForm>
        <PerawatRuanganForm data={dataRuangan}></PerawatRuanganForm>

        {/* Asesmen */}
        <div className='border border-black p-2 ml-5 mr-5'>
          <div className='flex items-center justify-between'>
            <TextTitle title='Asesmen (Diagnosa Kerja)' />
          </div>
          <DiagnosaTable data={res != null ? res.diagnosa : []} />
        </div>
        {/* Asesmen */}

        {/* Asesmen */}
        <div className='border border-black my-2 p-2 ml-5 mr-5'>
          <p className='flex-1 font-semibold mt-4'>Terapi</p>
          <div>
            {(res.terapi ?? []).map((i, index) => (
              <p className='flex-1 text-xs' key={index}>
                ({i.nama_obat}) {`${i.jumlah} ${i.satuan}`}
              </p>
            ))}
          </div>
        </div>
        {/* Asesmen */}

        <div className='border border-black my-2 p-2 ml-5 mr-5'>
          <p className='flex-1 font-semibold'>PEMERIKSAAN PENUNJANG</p>
          <div>
            <TextTitle title='Laboratorium' />
            <LaborTable data={res != null ? res.labor : []} />
          </div>
          <div>
            <TextTitle title='Pemeriksaan Lain' />
            <RadiologiTable data={res != null ? res.radiologi : []} />
          </div>

          <div className='border border-black my-2 p-2'>
            <div>
              <div className='border-black border-t-0 flex items-center'>
                <div className='p-2 flex justify-center border-black'>
                  <p className='text-xs'>Penjelasan</p>
                </div>
                <p className='text-xs ml-2'>
                  {' '}
                  {res?.asesmen_dokter.penjelasan || '-'}
                </p>
              </div>

              <div className='border-black border-t-0 flex items-center'>
                <div className='p-2 flex justify-center border-black'>
                  <p className='text-xs'>Konsul ke dan alasan konsul</p>
                </div>
                <p className='text-xs ml-2'>
                  {' '}
                  {res?.asesmen_dokter.alasanKonsulen || '-'}
                </p>
              </div>

              <div className='border-black border-t-0 flex items-center'>
                <div className='p-2 flex justify-center border-black'>
                  <p className='text-xs'>Prognosis</p>
                </div>
                <p className='text-xs ml-2'>
                  {' '}
                  {res?.asesmen_dokter.asesmed_prognosis || '-'}
                </p>
              </div>
            </div>
          </div>
        </div>

        <table className='w-full'>
          <tr className=' w-full '>
            <td className=' text-center align-middle p-2 w-full'>
              <div className='w-full flex flex-col items-center justify-center text-xs'>
                <p className='font-semibold'>Dokter Yang Memeriksa</p>

                <QRCode
                  value={res?.asesmen_dokter.dokter ?? '-'}
                  className='w-[60px] h-[60px] my-1'
                />

                <p className='text-center'>
                  ({res?.asesmen_dokter.dokter ?? '-'})
                </p>
              </div>
            </td>
          </tr>
        </table>
      </div>
      {/* Subyektif */}
    </LayoutBorderNo>
  )
}

function render(kd_bag: string, data: AsesmenAwalMedisRanap) {
  return match(kd_bag)
    .with('POL020', () => <Medical res={data} />)
    .with('POL033', () => <Medical res={data} />)
    .with('POL021', () => <Medical res={data} />)
    .with('POL011', () => <Medical res={data} />)
    .with('POL012', () => <Medical res={data} />)
    .with('POL013', () => <Medical res={data} />)
    .with('POL026', () => <Neurologi res={data} />)
    .with('POL027', () => <Medical res={data} />)
    .with('POL019', () => <Medical res={data} />)
    .otherwise(() => null)
}

export default ReportAsesmenAwalMedisRanap
