import type { MonitoringCairanModel } from '@/models/monitoring-cairan.model'
import type { Response } from '@/type'

import { post } from './api-2'

const getMonitoringCairan = async ({
  no_reg,
  kd_bagian,
}: {
  no_reg: string
  kd_bagian: string
}): Promise<Response<MonitoringCairanModel[]>> => {
  const response = await post(`v4/monitoring-cairan-pasien`, {
    no_reg,
    kd_bagian,
  })

  return response.data
}


const getBalanceCairan = async ({
  no_reg,
}: {
  no_reg: string
}): Promise<Response<MonitoringCairanModel[]>> => {
  const response = await post(`v4/monitoring-balance-cairan-pasien`, {
    no_reg,
  })

  return response.data
}

export { getMonitoringCairan,getBalanceCairan }
