import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { TindakanTransfusiDarah, getTransfusi } from './tindakan-transfusi'
import TindakanTransfusiDarahForm from './transfusi'

// ── Types ────────────────────────────────────────────────────────────────────

interface TindakanTranfusiProps {
  isReport?: boolean
  noreg?: string
}

// ── Component ────────────────────────────────────────────────────────────────

const TindakanTransfusiDarahPage = ({
  noreg = '',
  isReport = true,
}: TindakanTranfusiProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery<{
    response: TindakanTransfusiDarah | null
  }>({
    queryKey: [constants.queryKey.rekamMedis.informasiTransfusiDarah, noreg],
    queryFn: () => getTransfusi({ noreg }),
    enabled: !!noreg,
  })

  const res: TindakanTransfusiDarah | null = data?.response ?? null

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo>
      {isReport && <ReportHeader />}
      <div className='p-4'>
        <h1 className='text-center text-black font-semibold mb-1'>
          INFORMASI TINDAKAN TRANSFUSI DARAH
        </h1>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        {/* Form — renders with empty defaults when res is null */}
        <TindakanTransfusiDarahForm data={res ?? undefined} />

        <div className='mt-0' />
      </div>
    </LayoutBorderNo>
  )
}

export default TindakanTransfusiDarahPage
