import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { getDischargePlanning } from '@/services/discharge-planing'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import KriteriaDischargePlanning from './kriteria'

interface FormulirDischargePlanningProps {
  isReport?: boolean
  no?: string
  noreg?: string
}

export default function FormulirDischargePlanning({
  isReport = false,
  no = '',
  noreg = '',
}: FormulirDischargePlanningProps) {
  const { pasien } = usePasienStore((state) => state)
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.dischargePlanning, noreg],
    queryFn: () => getDischargePlanning({ noreg }),
  })

  const res = data?.response != null ? data.response : null
  console.log(res)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return <EmptyPlaceholder />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='text-center border-b-2 border-double border-gray-800 pb-4 mb-8'>
        <h1 className='text-center text-xl font-semibold'>RENCANA PULANG</h1>

        <h1 className='text-xl font-bold uppercase tracking-wider text-gray-900'>
          ( Discharge Planning )
        </h1>

        <div className='p2 mt-2'>
          {pasien != null && (
            <InformasiPasien
              nama={pasien.nama_pasien}
              noRM={pasien.no_rm}
              tanggalLahir={pasien.tgl_lahir}
              jk={pasien.jenis_kelamin}
            />
          )}
        </div>
      </div>

      <KriteriaDischargePlanning
        kriteriaAnswers={{
          syaratKetentuan: res!.n1,
          keterbatasanMobilitas: res!.n2,
          perawatanLanjut: res!.n3,
          bantuanAktifitas: res!.n4,
          belumMandiri: res!.n5,
        }}
        perencanaanChecked={{
          perawatanDiri: res!.p1,
          pantauanObat: res!.p2,
          pemantauanDiet: res!.p3,
          perawatanLuka: res!.p4,
          latihanFisik: res!.p5,
          pendampinganTenaga: res!.p6,
          perawatanRumah: res!.p7,
          bantuanFisik: res!.p8,
          caraMenyusui: res!.p9,
          caraMemandikan: res!.p10,
          perawatanTaliPusat: res!.p11,
          imunisasi: res!.p12,
          tumbuhKembang: res!.p13,
          keadaanKritisPadaBayi: res!.p14,
          nutrisiUntukBayi: res!.p15,
        }}
        ttd={{
          pasien: res?.nama_keluarga_pasien || '',
          ttd_mpp: res?.ttd_mpp || '',
          dpjp: res?.nama_dpjp || '',
          ttd_dpjp: res?.ttd_dpjp || '',
          mpp: res?.nama_mpp || '',
          kepala_ruangan: res?.nama_kepala_ruangan || '',
          ttd_kepala_ruangan: res?.ttd_kepala_ruangan || '',
          ttd_pasien: res?.ttd_keluarga_pasien || '',
        }}
      ></KriteriaDischargePlanning>
    </LayoutBorderNo>
  )
}
