import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import Text from '@/components/text'
import { getResumeMedisPerinatologi } from '@/services/resume-medis-perinatologi'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate } from '@/utils/formatDate'

interface ReportResumeMedisPerinatologiProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportResumeMedisPerinatologi({
  isReport = false,
  noreg = '',
  no,
}: ReportResumeMedisPerinatologiProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.resumeMedisPerinatologi,
      noreg,
      pasien?.no_rm,
    ],
    queryFn: () =>
      getResumeMedisPerinatologi({
        no_reg: noreg,
        no_rm: pasien!.no_rm,
      }),
    enabled: !!noreg && !!pasien?.no_rm,
  })

  const res = data?.response

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || !res.identitas_bayi) return <EmptyPlaceholder />

  const bayi = res.identitas_bayi

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          RESUME MEDIS PERINATOLOGI
        </h1>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='IDENTITAS BAYI' />
          <Text kStyle='min-w-[250px]' k='Nama Bayi' v={bayi.nama_bayi} />
          <Text
            kStyle='min-w-[250px]'
            k='Tanggal Lahir'
            v={formatDate(bayi.tgl_lahir)}
          />
          <Text kStyle='min-w-[250px]' k='No. RM' v={bayi.no_rm} />
          <Text kStyle='min-w-[250px]' k='No. Register' v={bayi.no_reg} />
          <Text kStyle='min-w-[250px]' k='Umur' v={bayi.umur} />
          <Text kStyle='min-w-[250px]' k='Jenis Kelamin' v={bayi.jk} />
          <Text
            kStyle='min-w-[250px]'
            k='Tanggal Masuk'
            v={formatDate(bayi.tgl_masuk)}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Tanggal Keluar'
            v={formatDate(bayi.tgl_keluar)}
          />
          <Text kStyle='min-w-[250px]' k='Ruang' v={bayi.ruang} />
          <Text kStyle='min-w-[250px]' k='Agama' v={bayi.agama} />
          <Text kStyle='min-w-[250px]' k='Alamat' v={bayi.alamat} />
          <Text kStyle='min-w-[250px]' k='Nama Ibu' v={bayi.nama_ibu} />
          <Text kStyle='min-w-[250px]' k='Dokter Anak' v={bayi.dokter_anak} />
          <Text kStyle='min-w-[250px]' k='Dokter Obgyn' v={bayi.dokter_obgyn} />
        </div>
      </div>
    </LayoutBorderNo>
  )
}
