export default function AsesmenAwalMedis({
  isReport = false,
  no,
  noreg,
}: AsesmenAwalMedisProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.asesmenDokterIgd, noreg],
    queryFn: () =>
      getAsesmenDokterIgdV2({ noreg: noreg!, noRm: pasien!.no_rm }),
    enabled: !!noreg,
  })

  const res = data?.response ?? INITIAL_DATA

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return <EmptyPlaceholder />

  return (
    <>
      <LayoutBorderNo no={no}>
        {isReport && <ReportHeader />}

        {/* Content */}
        <div className='p-2 text-xs'>
          <h1 className='text-center text-black font-semibold'>
            ASESMEN AWAL MEDIS PASIEN DI RUANG GAWAT DARURAT
          </h1>

          {/* Subyektif */}
          <div className='border border-black my-2 p-2'>
            <Text
              kStyle='min-w-[250px]'
              k='Keluhan Utama'
              v={res.asesmen.keluh_utama ?? '-'}
            />
            <Text
              kStyle='min-w-[250px]'
              k='Kesadaran'
              v={res.fisik.kesadaran ?? '-'}
            />
            <Text
              kStyle='min-w-[250px]'
              k='Telaah'
              v={res.asesmen.telaah ?? '-'}
            />
            <Text
              kStyle='min-w-[250px]'
              k='Riwayat Penyakit Terdahulu'
              v={res.asesmen.rwt_dahulu ?? '-'}
            />
            <Text
              kStyle='min-w-[250px]'
              k='Riwayat Penyakit Keluarga'
              v={res.asesmen.riwayat_penyakit_keluarga ?? '-'}
            />
          </div>
          {/* Subyektif */}

          {/* Pemeriksaan Fisik */}
          <div className='border border-black my-2 p-2'>
            <div className='flex items-center justify-between'>
              <p className='flex-1 font-semibold'>PEMERIKSAAN FISIK</p>
            </div>
            <TablePemeriksaanFisik data={res} />
          </div>

          <div className='border border-black my-2 p-2'>
            <p className='flex-1 font-semibold'>PEMERIKSAAN PENUNJANG</p>
            <div>
              <TextTitle title='Laboratorium' />
              <LaborTable data={res != null ? res.labor : []} />
            </div>
            <div>
              <TextTitle title='Pemeriksaan Lain' />
              <RadiologiTable data={res != null ? res.radiologi : []} />
            </div>
          </div>
          {/* Pemeriksaan Penunjang */}

          {/* Asesmen */}
          <div className='border border-black my-2 p-2'>
            <div className='flex items-center justify-between'>
              <TextTitle title='Asesmen (Diagnosa Kerja)' />
            </div>
            <DiagnosaTable data={res != null ? res.diagnosa : []} />
          </div>
          {/* Asesmen */}

          {/* PROGNOSA */}
          <div className='border border-black my-2 p-2'>
            <Text k='Prognosa' v={res.asesmen.prognosis ?? '-'} />
          </div>
          {/* PROGNOSA */}

          {/* Alasan Opname */}
          <div className='border border-black my-2 p-2'>
            <Text k='Alasan Opname' v={res.asesmen.alasan_opname ?? '-'} />
          </div>
          {/* Alasan Opname */}

          {/* Terapi */}
          <div className='border border-black my-2 p-2'>
            <Text k='Rencana Asuhan/Terapi' v={res.asesmen.terapi ?? '-'} />
          </div>
          {/* Terapi */}

          {/* Konsul Ke */}
          <div className='border border-black my-2 p-2'>
            <Text k='Konsul Ke' v={formatName(res.asesmen.konsulke ?? '')} />
          </div>
          {/* Konsul Ke */}
        </div>
        {/* Content */}

        <div className='flex items-start justify-between'>
          {/* Dokter Yang Memeriksa */}
          <div className='p-2 mb-1 m-2'>
            <div className='flex flex-col gap-4 items-center text-center text-xs'>
              {res != null && res.asesmen.nama_dokter != '' && (
                <>
                  <p className='text-sm'>Dokter Yang Memeriksa</p>
                  <QRCode
                    value={res.asesmen.nama_dokter ?? '-'}
                    className='w-[50px] h-[50px] object-contain'
                  />
                  <p className=''>({res.asesmen.nama_dokter ?? '-'})</p>
                </>
              )}
            </div>
          </div>
          {/* Dokter Yang Memeriksa */}
          <div className='p-2 mb-1 m-2'>
            <div className='flex flex-col gap-4 items-center text-center text-xs'>
              <p>Tanggal : {formatDateTime(res.asesmen.insert_dttm)}</p>
            </div>
          </div>
          {/* Dokter Yang Memeriksa */}
        </div>

        {/* Dialog */}
      </LayoutBorderNo>
    </>
  )
}
