import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import { getKartuCairanIntensive } from '@/services/kartu-intensive'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportKartuCairanIntensiveProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportKartuCairanIntensive({
  isReport = false,
  noreg = '',
  no,
}: ReportKartuCairanIntensiveProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.kartuCairanIntensive, noreg],
    queryFn: () => getKartuCairanIntensive(noreg),
    enabled: !!noreg,
  })

  const res = data?.response ?? []

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          KARTU CAIRAN INTENSIVE
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='flex mt-4'>
          <SimpleColumn name='Jam' className='text-xs flex-[0.6]' />
          <SimpleColumn name='Cairan Masuk I' className='text-xs flex-1' />
          <SimpleColumn name='Cairan Masuk II' className='text-xs flex-1' />
          <SimpleColumn name='Cairan Masuk III' className='text-xs flex-1' />
          <SimpleColumn name='Cairan Masuk NGT' className='text-xs flex-1' />
          <SimpleColumn name='Nama Cairan' className='text-xs flex-[1.4]' />
          <SimpleColumn name='Keluar Urine' className='text-xs flex-1' />
          <SimpleColumn name='Keluar NGT' className='text-xs flex-1' />
          <SimpleColumn name='Drain / DLL' className='text-xs flex-1' />
          <SimpleColumn name='Keterangan' className='text-xs flex-1' isLast />
        </div>

        {res.length == 0 && <EmptyPlaceholder />}

        {res.map((item, index) => (
          <div className='flex' key={item.id_kartu ?? index}>
            <SimpleColumn
              name={item.jam?.substring(11, 19) || item.jam || '-'}
              className='text-xs flex-[0.6]'
            />
            <SimpleColumn
              name={item.cairan_masuk1 || '-'}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={item.cairan_masuk2 || '-'}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={item.cairan_masuk3 || '-'}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={item.cairan_masuk_ngt || '-'}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={item.nama_cairan || '-'}
              className='text-xs flex-[1.4]'
            />
            <SimpleColumn
              name={item.cairan_keluar_urine || '-'}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={item.cairan_keluar_ngt || '-'}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={item.drain_dll || '-'}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={item.keterangan || '-'}
              className='text-xs flex-1'
              isLast
            />
          </div>
        ))}
      </div>
    </LayoutBorderNo>
  )
}
