import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import { MonitoringCairanModel } from '@/models/monitoring-cairan.model'
import { getMonitoringCairan } from '@/services/monitoring-cairan'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportMonitoringCairanProps {
  isReport?: boolean
  noreg?: string
  norm?: string
  no?: string
}

const init: MonitoringCairanModel[] = []

const ReportMonitoringCairan = ({
  isReport,
  noreg,
  no,
}: ReportMonitoringCairanProps) => {
  const { pasien } = usePasienStore((state) => state)
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.monitoringCairan, noreg!],
    queryFn: () => getMonitoringCairan({ no_reg: noreg!, kd_bagian: '' }),
    enabled: !!noreg,
  })

  const res = data?.response ?? init
  console.log('res', res)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res.length == 0) return <EmptyPlaceholder />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}
      <h1 className='text-center text-black font-semibold my-4'>
        MONITORING CAIRAN
      </h1>

      {/* Informasi Pasien */}
      {pasien != null && (
        <InformasiPasien
          nama={pasien.nama_pasien}
          noRM={pasien.no_rm}
          tanggalLahir={pasien.tgl_lahir}
          jk={pasien.jenis_kelamin}
        />
      )}

      <h3 className='text-center text-black font-medium mb-4'>INTAKE</h3>
      <div className='flex px-2'>
        <SimpleColumn name='No' className='text-xs flex-[0.5]' />
        <SimpleColumn name='Tanggal & Jam' className='text-xs flex-1' />
        <SimpleColumn name='Minum' className='text-xs flex-1' />
        <SimpleColumn name='NGT' className='text-xs flex-1' />
        <SimpleColumn name='Infus' className='text-xs flex-1' />
        <SimpleColumn name='Jenis Infus' className='text-xs flex-1' />
        <SimpleColumn name='Jumlah' className='text-xs flex-1' />
        <SimpleColumn isLast name='Perawat' className='text-xs flex-1 ' />
      </div>

      {res.map((item, index) => (
        <div key={index} className='px-2 flex'>
          <SimpleColumn name={`${index + 1}`} className='text-xs flex-[0.5]' />
          <SimpleColumn name={item.intake.tanggal} className='text-xs flex-1' />
          <SimpleColumn
            name={`${item.intake.minum}`}
            className='text-xs flex-1'
          />
          <SimpleColumn
            name={`${item.intake.ngt}`}
            className='text-xs flex-1'
          />
          <SimpleColumn
            name={`${item.intake.infuse}`}
            className='text-xs flex-1'
          />
          <SimpleColumn
            name={`${item.intake.jenis_infuse}`}
            className='text-xs flex-1'
          />
          <SimpleColumn
            name={`${item.intake.total}`}
            className='text-xs flex-1'
          />
          <SimpleColumn
            isLast
            name={`${item.intake.nama_user}`}
            className='text-xs  flex-1'
          />
        </div>
      ))}

      <h3 className='text-center text-black font-medium my-4'>OUTPUT</h3>
      <div className='flex px-2'>
        <SimpleColumn name='No' className='text-xs flex-[0.5]' />
        <SimpleColumn name='Tanggal & Jam' className='text-xs flex-1' />
        <SimpleColumn name='Urine' className='text-xs flex-1' />
        <SimpleColumn name='NGT' className='text-xs flex-1' />
        <SimpleColumn name='WSD' className='text-xs flex-1' />
        <SimpleColumn name='Drain' className='text-xs flex-1' />
        <SimpleColumn name='Muntah' className='text-xs flex-1' />
        <SimpleColumn name='Pendarahan' className='text-xs flex-1' />
        <SimpleColumn name='Jumlah' className='text-xs flex-1' />
        <SimpleColumn isLast name='Perawat' className='text-xs flex-1 ' />
      </div>

      {res.map((item, index) => (
        <div key={index} className='px-2 flex'>
          <SimpleColumn name={`${index + 1}`} className='text-xs flex-[0.5]' />
          <SimpleColumn name={item.intake.tanggal} className='text-xs flex-1' />
          <SimpleColumn
            name={`${item.output.urine}`}
            className='text-xs flex-1'
          />
          <SimpleColumn
            name={`${item.output.ngt}`}
            className='text-xs flex-1'
          />
          <SimpleColumn
            name={`${item.output.wsd}`}
            className='text-xs flex-1'
          />
          <SimpleColumn
            name={`${item.output.drain}`}
            className='text-xs flex-1'
          />
          <SimpleColumn
            name={`${item.output.muntah}`}
            className='text-xs flex-1'
          />
          <SimpleColumn
            name={`${item.output.pendarahan}`}
            className='text-xs flex-1'
          />
          <SimpleColumn
            name={`${item.output.total}`}
            className='text-xs flex-1'
          />
          <SimpleColumn
            isLast
            name={`${item.intake.nama_user}`}
            className='text-xs  flex-1'
          />
        </div>
      ))}

      <div className='h-[50px]' />
    </LayoutBorderNo>
  )
}
export default ReportMonitoringCairan
