import { post } from '@/services/api-2'
import type { Response } from '@/type'

export interface IntervensiResikoJatuhDewasa {
  tanggal: string
  resiko_jatuh: ResikoJatuh[]
}

export interface ResikoJatuh {
  insert_dttm: string
  UpdDttm: string
  user_id: string
  InsertPc: string
  person: string
  pelayanan: string
  kd_bagian: string
  noreg: string
  shift: string
  resiko1: boolean
  resiko2: boolean
  resiko3: boolean
  resiko4: boolean
  resiko5: boolean
  resiko6: boolean
  resiko7: boolean
  resiko8: boolean
  resiko9: boolean
  resiko10: boolean
  resiko11: boolean
  resiko12: boolean
  resiko13: boolean
  resiko14: boolean
  resiko15: boolean
  resiko16: boolean
  resiko17: boolean
  resiko18: boolean
  nama_perawat: string
}

const getIntervensiDewasa = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<IntervensiResikoJatuhDewasa[]>> => {
  const response = await post(`/v1/intervensi-resiko-jatuh-dewasa/get`, {
    no_reg: noreg,
  })

  return response.data
}

export { getIntervensiDewasa }
