import { CheckIcon, MinusIcon } from 'lucide-react'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { getTindakanTransfusi } from '@/services/penmed'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatTanggalV2 } from '@/utils/date_helper'

import EmptyTransfusi from './empty-transfusi'
import { InfoTransfusiFooter } from './info-footer'

interface InformasiTranfusiDarahProps {
  isReport?: boolean
  noreg?: string
}

// helper agar tidak repetitif
function TandaColumn({ value }: { value: boolean }) {
  return (
    <div className='flex isLast flex-col flex-[0.5] gap-2 text-center justify-center items-center p-2 border-y border-black border-r'>
      {value ? <CheckIcon /> : <MinusIcon />}
    </div>
  )
}

const TransfusiDarah = ({ noreg = '' }: InformasiTranfusiDarahProps) => {
  const { pasien } = usePasienStore((state) => state)

  const tglLahir = formatTanggalV2(pasien?.tgl_lahir || '')

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.tBAnak, noreg],
    queryFn: () => getTindakanTransfusi({ noreg: noreg! }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return <EmptyTransfusi message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo>
      <div className='p-4'>
        <h1 className='text-center text-black font-semibold mb-1'>
          INFORMASI TINDAKAN TRANSFUSI DARAH
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={tglLahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <h3 className='mt-4 mb-4'>
          Petugas Pelaksana tindakan menyatakan bahwa telah menerangkan hal
          terkait dengan transfusi darah di bawah ini secara benar dan jelas,
          dan sudah memberikan kesempatan pada pasien / keluarga untuk bertanya
          dan berdiskusi
        </h3>

        <div className='flex text-xs'>
          <SimpleColumn head name='No.' className='w-[100px]' />
          <SimpleColumn head name='JENIS INFORMASI' className='flex-[0.5]' />
          <SimpleColumn head name='INFORMASI' className='flex-[1]' />
          <SimpleColumn head name='TANDA' className='flex-[0.5]' isLast />
        </div>

        {[
          {
            no: '1',
            jenis: 'Pengertian Transfusi',
            informasi:
              'Suatu proses pemindahan darah dari orang sehat ke tubuh orang yang sakit (pasien)',
            value: res?.value1,
          },
          {
            no: '2',
            jenis: 'Jenis Darah',
            informasi:
              'Darah yang dipindahkan dapat berupa darah lengkap atau hanya komponen darah',
            value: res?.value2,
          },
          {
            no: '3',
            jenis: 'Tujuan',
            informasi:
              'Untuk menolong pasien yang mengalami kurang darah baik dalam bentuk sel darah maupun komponen-komponennya',
            value: res?.value3,
          },
          {
            no: '4',
            jenis: 'Risiko',
            informasi:
              'Pemindahan darah selain dapat menolong orang dapat juga menimbulkan penyulit pada masing-masing individu penerimanya terlebih pasien yang ada riwayat alergi',
            value: res?.value4,
          },
          {
            no: '5',
            jenis: 'Komplikasi',
            informasi:
              'Penyulit atau komplikasi yang bisa timbul sifatnya dapat terjadi cepat (akut) atau lambat, selain itu bila dilakukan Transfusi dalam jumlah banyak dan cepat juga dapat menimbulkan akibat seperti Hipotermi yaitu suhu tubuh menurun dan beberapa penyakit lainnya',
            value: res?.value5,
          },
        ].map((item) => (
          <div key={item.no} className='flex text-xs'>
            <SimpleColumn name={item.no} className='w-[100px]' />
            <SimpleColumn name={item.jenis} className='flex-[0.5]' />
            <SimpleColumn name={item.informasi} className='flex-[1]' />
            <TandaColumn value={!!item.value} />
          </div>
        ))}

        <InfoTransfusiFooter
          namaPemberi={res?.nama_pemberi}
          ttdPemberi='/ttd-dokter.png'
          namaPenerima={res?.nama_penerima}
          ttdPenerima='/ttd-pasien.png'
        />
      </div>
    </LayoutBorderNo>
  )
}

export default TransfusiDarah
