import { ResikoJatuh, ReskoJatuhGeriatri } from './geriatri'

/* ======================================================
 * Props komponen — hanya menerima data ReskoJatuhGeriatri
 * ====================================================== */
interface LaporanResikoJatuhGeriatriProps {
  data: ReskoJatuhGeriatri
}

interface CategoryGroup {
  label: string
  items: ResikoJatuh[]
}

/* ======================================================
 * Helpers
 * ====================================================== */
function isJawabanAktif(jawaban: string): boolean {
  return jawaban?.trim().toUpperCase() === 'YA'
}

/* ======================================================
 * Komponen utama — hanya menampilkan tabel resiko jatuh
 * ====================================================== */
export default function LaporanResikoJatuhGeriatri({
  data,
}: LaporanResikoJatuhGeriatriProps) {
  const groups: CategoryGroup[] = [
    { label: 'RIWAYAT JATUH', items: data.riwayat_jatuh ?? [] },
    { label: 'STATUS MENTAL', items: data.status_mental ?? [] },
    { label: 'PENGLIHATAN', items: data.penglihatan ?? [] },
    { label: 'KEBIASAAN BERKEMIH', items: data.kebiasaan_berkemih ?? [] },
    { label: 'TRANSFER', items: data.transfer ?? [] },
    { label: 'MOBILITAS', items: data.mobilitasi ?? [] },
  ].filter((g) => g.items.length > 0)

  return (
    <>
      <style>{`
        .lrjg-table {
          width: 100%;
          border-collapse: collapse;
          font-size: 13.5px;
          font-family: Arial, Helvetica, sans-serif;
          color: #1a1a1a;
        }
        .lrjg-table th, .lrjg-table td {
          border: 1px solid #555;
          padding: 10px 12px;
          vertical-align: middle;
        }
        .lrjg-table thead th {
          background: #f0def0;
          font-weight: 700;
          text-align: center;
          font-size: 14px;
        }
        .col-faktor {
          width: 20%;
          text-align: center;
          font-weight: 700;
          background: #fafafa;
        }
        .col-skala { width: 52%; }
        .col-poin {
          width: 10%;
          text-align: center;
          font-weight: 700;
        }
        .col-hasil {
          width: 12%;
          text-align: center;
        }
        .lrjg-table tbody .col-skala.hasil-aktif,
        .lrjg-table tbody .col-hasil.hasil-aktif {
          background: #bcdaf2;
          font-weight: 600;
        }
        .lrjg-table tfoot td {
          font-weight: 700;
        }
        .lrjg-total-label {
          text-align: right;
        }
        .lrjg-total-value {
          text-align: center;
        }
      `}</style>

      <table className='lrjg-table'>
        <thead>
          <tr>
            <th className='col-faktor'>Faktor Resiko</th>
            <th className='col-skala'>SKALA</th>
            <th className='col-poin'>POIN</th>
            <th className='col-hasil'>HASIL</th>
          </tr>
        </thead>
        <tbody>
          {groups.map((group, gi) =>
            group.items.map((item, idx) => {
              const aktif = isJawabanAktif(item.jawaban)
              return (
                <tr key={`${gi}-${idx}`}>
                  {idx === 0 && (
                    <td className='col-faktor' rowSpan={group.items.length}>
                      {group.label}
                    </td>
                  )}
                  <td className={`col-skala ${aktif ? 'hasil-aktif' : ''}`}>
                    {item.title}
                  </td>
                  <td className='col-poin'>{item.skor}</td>
                  <td className={`col-hasil ${aktif ? 'hasil-aktif' : ''}`}>
                    {item.jawaban || '-'}
                  </td>
                </tr>
              )
            }),
          )}
        </tbody>
        <tfoot>
          <tr>
            <td className='lrjg-total-label' colSpan={3}>
              TOTAL SKOR
            </td>
            <td className='lrjg-total-value'>{data.total_skor}</td>
          </tr>
        </tfoot>
      </table>
    </>
  )
}

