import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatTanggalV2 } from '@/utils/date_helper'

import { PonekReport } from './PonekReport'
import { getPonek } from './ponek'

interface PengkajianAwalPonekProps {
  isReport?: boolean
  id?: string
  noreg?: string
}

const FormulirPengkajianAwalPonek = ({
  noreg = '',
  id = '',
  isReport = false,
}: PengkajianAwalPonekProps) => {
  const { pasien } = usePasienStore((state) => state)

  const tglLahir = formatTanggalV2(pasien?.tgl_lahir || pasien?.tgl_lahir || '')

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.pengkajianAwalPonek,
      noreg,
      pasien?.no_rm,
    ],
    queryFn: () =>
      getPonek({
        noreg: noreg!,
        id: id,
      }),
    enabled: !!noreg,
  })

  const res = data?.response ?? null

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo>
      {isReport && <ReportHeader />}
      <div className='p-4'>
        <h1 className='text-center text-black font-semibold mb-1'>
          PENGKAJIAN AWAL PONEK
        </h1>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={tglLahir}
            jk={pasien.jenis_kelamin}
          />
        )}
        {/* Informasi Pasien */}

        <div className='mt-0'>
          <PonekReport data={res} />
        </div>
      </div>
    </LayoutBorderNo>
  )
}

export default FormulirPengkajianAwalPonek
