import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import Text from '@/components/text'
import { getVerifikasiPasienOperasi } from '@/services/verifikasi-pasien-operasi'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportVerifikasiPasienOperasiProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

function mark(value: boolean) {
  return value ? '✓' : '-'
}

export default function ReportVerifikasiPasienOperasi({
  isReport = false,
  noreg = '',
  no,
}: ReportVerifikasiPasienOperasiProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.verifikasiPasienOperasi,
      noreg,
      pasien?.jenis_kelamin,
    ],
    queryFn: () =>
      getVerifikasiPasienOperasi({
        no_reg: noreg,
        jk: pasien!.jenis_kelamin,
      }),
    enabled: !!noreg && !!pasien?.jenis_kelamin,
  })

  const res = data?.response

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return <EmptyPlaceholder />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          VERIFIKASI PASIEN OPERASI
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='border border-black my-2 p-2'>
          <Text kStyle='min-w-[250px]' k='Jam Tiba' v={res.jam_tiba_operasi} />
          <Text
            kStyle='min-w-[250px]'
            k='Jam Keluar'
            v={res.jam_keluar_operasi}
          />
          <Text kStyle='min-w-[250px]' k='Ruang Rawat' v={res.ruang_rawat} />
          <Text
            kStyle='min-w-[250px]'
            k='Tanggal Operasi'
            v={res.tanggal_operasi}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Urutan Operasi'
            v={res.urutan_operasi}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Lokasi Operasi'
            v={`${res.lokasi_operasi} (Kiri: ${mark(
              res.lokasi_kiri,
            )}, Kanan: ${mark(res.lokasi_kanan)})`}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Bagian Operasi'
            v={res.bagian_operasi}
          />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='CHECKLIST PRE OPERASI' />
          <div className='flex mt-2'>
            <SimpleColumn name='No' className='text-xs flex-[0.3]' />
            <SimpleColumn name='Item' className='text-xs flex-[3]' />
            <SimpleColumn name='Ruangan' className='text-xs flex-[0.6]' />
            <SimpleColumn name='Petugas' className='text-xs flex-[0.6]' />
            <SimpleColumn
              name='Perawat'
              className='text-xs flex-[0.6]'
              isLast
            />
          </div>
          {(res.pre_operasi ?? []).map((item, index) => (
            <div className='flex' key={index}>
              <SimpleColumn
                name={item.no || `${index + 1}`}
                className='text-xs flex-[0.3]'
              />
              <SimpleColumn
                name={item.label || '-'}
                className='text-xs flex-[3]'
              />
              <SimpleColumn
                name={mark(item.col1)}
                className='text-xs flex-[0.6]'
              />
              <SimpleColumn
                name={mark(item.col2)}
                className='text-xs flex-[0.6]'
              />
              <SimpleColumn
                name={mark(item.col3)}
                className='text-xs flex-[0.6]'
                isLast
              />
            </div>
          ))}
          <Text kStyle='min-w-[250px]' k='Catatan' v={res.catatan_preoperasi} />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='CHECKLIST PASKA OPERASI' />
          <div className='flex mt-2'>
            <SimpleColumn name='No' className='text-xs flex-[0.3]' />
            <SimpleColumn name='Item' className='text-xs flex-[3]' />
            <SimpleColumn name='Ruangan' className='text-xs flex-[0.6]' />
            <SimpleColumn name='Petugas' className='text-xs flex-[0.6]' />
            <SimpleColumn
              name='Perawat'
              className='text-xs flex-[0.6]'
              isLast
            />
          </div>
          {(res.paska_operasi ?? []).map((item, index) => (
            <div className='flex' key={index}>
              <SimpleColumn
                name={item.no || `${index + 1}`}
                className='text-xs flex-[0.3]'
              />
              <SimpleColumn
                name={item.label || '-'}
                className='text-xs flex-[3]'
              />
              <SimpleColumn
                name={mark(item.col1)}
                className='text-xs flex-[0.6]'
              />
              <SimpleColumn
                name={mark(item.col2)}
                className='text-xs flex-[0.6]'
              />
              <SimpleColumn
                name={mark(item.col3)}
                className='text-xs flex-[0.6]'
                isLast
              />
            </div>
          ))}
          <Text
            kStyle='min-w-[250px]'
            k='Catatan'
            v={res.catatan_paska_operasi}
          />
        </div>

        <div className='grid grid-cols-3 gap-2 mt-4'>
          <div className='text-center'>
            <Text isHeader k='Pengantar Pre Operasi' />
            <p>{res.pengantar_preoperasi?.nama || '-'}</p>
          </div>
          <div className='text-center'>
            <Text isHeader k='Penerima 1' />
            <p>{res.penerima_preoperasi1?.nama || '-'}</p>
          </div>
          <div className='text-center'>
            <Text isHeader k='Penerima 2' />
            <p>{res.penerima_preoperasi2?.nama || '-'}</p>
          </div>
          <div className='text-center'>
            <Text isHeader k='Pengantar Paska Operasi' />
            <p>{res.pengantar_paskaoperasi?.nama || '-'}</p>
          </div>
          <div className='text-center'>
            <Text isHeader k='Penerima 1' />
            <p>{res.penerima_paskaoperasi1?.nama || '-'}</p>
          </div>
          <div className='text-center'>
            <Text isHeader k='Penerima 2' />
            <p>{res.penerima_paskaoperasi2?.nama || '-'}</p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
