// ── Sub-components ───────────────────────────────────────────────────────────

interface CheckMarkProps {
  checked: boolean
  onClick: () => void
}

function CheckMark({ checked, onClick }: CheckMarkProps): JSX.Element {
  return (
    <button
      type='button'
      onClick={onClick}
      className='w-full h-full flex items-center justify-center focus:outline-none'
      aria-label={checked ? 'Checked' : 'Unchecked'}
    >
      {checked ? (
        <svg
          className='w-8 h-8 text-gray-800'
          viewBox='0 0 24 24'
          fill='none'
          stroke='currentColor'
          strokeWidth='2.5'
          strokeLinecap='round'
          strokeLinejoin='round'
        >
          <polyline points='20 6 9 17 4 12' />
        </svg>
      ) : (
        <svg
          className='w-8 h-8 text-gray-800'
          viewBox='0 0 24 24'
          fill='none'
          stroke='currentColor'
          strokeWidth='2.5'
          strokeLinecap='round'
        >
          <line x1='4' y1='12' x2='20' y2='12' />
        </svg>
      )}
    </button>
  )
}

export default function TindakanTransfusiDarahForm({
  data: dataProp,
  onChange,
}: TindakanTransfusiDarahProps = {}): JSX.Element {
  const [data, setData] = useState<TindakanTransfusiDarah>({
    ...defaultData,
    ...dataProp,
  })

  /** Merge patch → update local state → bubble up via onChange */
  const update = (patch: Partial<TindakanTransfusiDarah>): void => {
    setData((prev) => {
      const next = { ...prev, ...patch }
      onChange?.(next)
      return next
    })
  }

  const setBoolean = (field: BooleanKeys, val: boolean): void =>
    update({ [field]: val })

  return (
    <div
      className='bg-white min-h-screen p-6 flex justify-center'
      style={{ fontFamily: "'Times New Roman', Times, serif" }}
    >
      <div className='w-full '>
        {/* Header paragraph */}
        <p className='text-sm text-gray-800 mb-4 leading-snug'>
          Petugas Pelaksana tindakan menyatakan bahwa telah menerangkan hal
          terkait dengan transfusi darsh di bawati ini secara benar dan jelas,
          dan sudah memberikan kesempatan pada pasien / keluarga untuk bertanya
          dan berdiskusi
        </p>

        {/* Main Table */}
        <table
          className='w-full border-collapse text-sm'
          style={{ borderColor: '#888' }}
        >
          <thead>
            <tr className='bg-gray-100'>
              <th
                className='border border-gray-400 py-2 px-3 text-center font-semibold text-gray-700 tracking-wide'
                style={{ width: '5%' }}
              >
                NO.
              </th>
              <th
                className='border border-gray-400 py-2 px-3 text-center font-semibold text-gray-700 tracking-wide'
                style={{ width: '18%' }}
              >
                JENIS INFORMASI
              </th>
              <th
                className='border border-gray-400 py-2 px-3 text-center font-semibold text-gray-700 tracking-wide'
                style={{ width: '62%' }}
              >
                INFORMASI
              </th>
              <th
                className='border border-gray-400 py-2 px-3 text-center font-semibold text-gray-700 tracking-wide'
                style={{ width: '15%' }}
              >
                TANDA
              </th>
            </tr>
          </thead>
          <tbody>
            {infoRows.map((row: InfoRow) => (
              <tr key={row.no} className='align-top'>
                <td
                  className='border border-gray-400 py-4 px-3 text-gray-800'
                  style={{ verticalAlign: 'top' }}
                >
                  {row.no}.
                </td>
                <td
                  className='border border-gray-400 py-4 px-3 text-gray-800'
                  style={{ verticalAlign: 'top' }}
                >
                  {row.jenis}
                </td>
                <td
                  className='border border-gray-400 py-4 px-3 text-gray-800 leading-relaxed'
                  style={{ verticalAlign: 'top' }}
                >
                  {row.informasi}
                </td>
                <td
                  className='border border-gray-400 py-4 px-3'
                  style={{ verticalAlign: 'middle', height: 80 }}
                >
                  <CheckMark
                    checked={data[row.key]}
                    onClick={() => setBoolean(row.key, !data[row.key])}
                  />
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* Footer section */}
        <table className='w-full border-collapse text-sm mt-0'>
          <tbody>
            <tr className='align-top'>
              {/* Left: statement + tanggal */}
              <td
                className='border border-gray-400 py-3 px-3 text-gray-800 leading-relaxed'
                style={{ width: '55%', verticalAlign: 'top' }}
              >
                <p className='mb-3'>
                  Dengan ini menyatakan bahwa saya telah menerangkan hal-hal di
                  atas secara benar dan jelas dan memberikan kesempatan untuk
                  bertanya dan atau berdiskusi
                </p>
              </td>

              {/* Right: signatures */}
              <td
                className='border border-gray-400 py-3 px-4'
                style={{ verticalAlign: 'top' }}
              >
                <div className='flex justify-around gap-4 mt-1'>
                  {/* Pemberi Informasi */}
                  <div className='flex flex-col items-center gap-2 flex-1'>
                    <p className='text-xs text-center text-gray-700 font-medium'>
                      Yang memberi informasi,
                    </p>
                    <TandaTanganField
                      imageUrl={
                        import.meta.env.VITE_BASE_API_URL_RME +
                        '/app/images/tindakan_transfusi/' +
                        data.ttd_pemberi
                      }
                      name={data.nama_pemberi}
                    />
                  </div>
                </div>
              </td>
            </tr>
          </tbody>

          {/* // 2/ */}
          <tbody>
            <tr className='align-top'>
              {/* Left: statement + tanggal */}
              <td
                className='border border-gray-400 py-3 px-3 text-gray-800 leading-relaxed'
                style={{ width: '55%', verticalAlign: 'top' }}
              >
                <p className='mb-3'>
                  Dengan ini menyatakan bahwa saya telah menerima informasi dari
                  dokter sebagaimana adanya di atas kemudian yang sudah diberi
                  tanda/paraf di kolom kanannya dan saya telah memahaminya.
                </p>
              </td>

              {/* Right: signatures */}
              <td
                className='border border-gray-400 py-3 px-4'
                style={{ verticalAlign: 'top' }}
              >
                <div className='flex justify-around gap-4 mt-1'>
                  {/* Pemberi Informasi */}
                  <div className='flex flex-col items-center gap-2 flex-1'>
                    <p className='text-xs text-center text-gray-700 font-medium'>
                      Yang menerima informasi,
                    </p>
                    {/* <SignatureField
                      label=''
                      value={data.ttd_penerima}
                      onChange={(v: string) => setString('ttd_pemberi', v)}
                    /> */}
                    <TandaTanganField
                      imageUrl={
                        import.meta.env.VITE_BASE_API_URL_RME +
                        '/app/images/tindakan_transfusi/' +
                        data.ttd_penerima
                      }
                      name={data.nama_penerima}
                    />
                  </div>
                </div>
              </td>
            </tr>
          </tbody>

          <tbody>
            <tr className='border border-gray-400 p-5'>
              <p className='mb-3 p-3'>
                * bila pasien tidak kompeten atau tidak mau menerima informasi,
                maka penerima informasi adalah wajib atau keluarga terdekat *
              </p>
            </tr>
          </tbody>
        </table>
      </div>
    </div>
  )
}
