import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import Text from '@/components/text'
import { initAsesmenAwalKeperawatanRanap } from '@/models/asesmen-awal-keperawatan-ranap'
import { getAsesmenPerawatRanap } from '@/services/asesmen-perawat-ranap'
import { useAuthStore } from '@/store/auth.store'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDateTime } from '@/utils/formatDate'

interface ReportAsesmenAwalKeperawatanRanapProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportAsesmenAwalKeperawatanRanap({
  isReport = false,
  noreg = '',
  no,
}: ReportAsesmenAwalKeperawatanRanapProps) {
  const { pasien } = usePasienStore((state) => state)
  const { user } = useAuthStore((state) => state)

  const kdBagian = pasien?.kd_bagian || user?.kd_bagian || ''

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.asesmenAwalKeperawatanRanap,
      noreg,
      kdBagian,
    ],
    queryFn: () => getAsesmenPerawatRanap({ noReg: noreg, kdBagian }),
    enabled: !!noreg && !!kdBagian,
  })

  const res = data?.response ?? initAsesmenAwalKeperawatanRanap

  if (!kdBagian) return <EmptyPlaceholder />
  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (
    res == null ||
    !res.pengkajian ||
    !res.fisik ||
    !res.vital_sign ||
    !res.nyeri ||
    !res.persistem ||
    res.pengkajian.keluhan_utama == ''
  )
    return <EmptyPlaceholder />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          ASESMEN AWAL KEPERAWATAN RAWAT INAP
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='border border-black my-2 p-2'>
          <Text
            kStyle='min-w-[250px]'
            k='Tiba di ruangan'
            v={formatDateTime(res.pengkajian.insert_dttm)}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Cara Masuk'
            v={res.pengkajian.cara_masuk}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Asal Masuk'
            v={res.pengkajian.asal_pasien}
          />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='BAGIAN I PENGKAJIAN FISIK' />
          <div className='flex gap-2 items-start justify-between'>
            <div className='flex flex-col flex-1'>
              <Text
                k='GCS'
                v={`E:${res.fisik.gcs_e} V:${res.fisik.gcs_v} M:${res.fisik.gcs_m}`}
              />
              <Text k='Suhu' v={`${res.vital_sign.suhu} °C`} />
              <Text
                k='Tekanan Darah'
                v={`${res.vital_sign.tekanan_darah} mmHg`}
              />
              <Text k='Pupil' v={res.fisik.pupil} />
              <Text k='Nadi' v={`${res.vital_sign.nadi} x/menit`} />
            </div>

            <div className='flex flex-col flex-1'>
              <Text
                k='Reaksi Cahaya'
                v={`${res.vital_sign.reaksi_cahaya_kiri}/${res.vital_sign.reaksi_cahaya_kanan}`}
              />
              <Text k='Pernafasan' v={`${res.vital_sign.pernapasan} x/menit`} />
              <Text k='SpO2' v={`${res.vital_sign.spo2} %`} />
            </div>
          </div>
          <Text k='TB' v={`${res.vital_sign.tinggi_badan} cm`} />
          <Text k='BB' v={`${res.vital_sign.berat_badan} kg`} />
          <Text k='Kesadaran' v={res.fisik.kesadaran} />
          <Text k='Kepala' v={res.fisik.kepala} />
          <Text k='Rambut' v={res.fisik.rambut} />
          <Text k='Wajah' v={res.fisik.wajah} />
          <Text k='Mata' v={res.fisik.mata} />
          <Text k='Telinga' v={res.fisik.telinga} />
          <Text k='Hidung' v={res.fisik.hidung} />
          <Text k='Mulut' v={res.fisik.mulut} />
          <Text k='Gigi' v={res.fisik.gigi} />
          <Text k='Lidah' v={res.fisik.lidah} />
          <Text k='Tenggorokan' v={res.fisik.tenggorokan} />
          <Text k='Leher' v={res.fisik.leher} />
          <Text k='Dada' v={res.fisik.dada} />
          <Text k='Respirasi' v={res.fisik.respirasi} />
          <Text k='Perut' v={res.fisik.perut} />
          <Text k='Jantung' v={res.fisik.jantung} />
          <Text k='Integumen' v={res.fisik.integument} />
          <Text k='Ekstremitas' v={res.fisik.ekstremitas} />
          <Text k='Kemampuan Menggenggam' v={res.fisik.kemampuan_genggam} />
          <Text k='Genetalia' v={res.fisik.genetalia} />
          <Text k='Anus' v={res.fisik.anus} />
          <Text k='Punggung' v={res.fisik.punggung} />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='BAGIAN II RIWAYAT KESEHATAN' />
          <Text
            k='Diagnosa Dokter saat masuk'
            v={res.pengkajian.diagnosa_khusus}
          />
          <Text k='Alasan masuk rumah sakit' v={res.pengkajian.keluhan_utama} />
          <Text
            k='Riwayat kesehatan yang lalu'
            v={res.pengkajian.riwayat_penyakit_dahulu}
          />
          <Text k='Riwayat alergi' v={res.pengkajian.riwayat_alergi} />
          <Text
            k='Riwayat transfusi darah'
            v={res.pengkajian.riwayat_transfusi_darah}
          />
          <Text k='Riwayat merokok' v={res.pengkajian.riwayat_merokok} />
          <Text
            k='Riwayat minum minuman keras'
            v={res.pengkajian.minum_alkohol}
          />
          <Text
            k='Riwayat penggunaan obat'
            v={res.pengkajian.penggunaan_obat}
          />
          <Text
            k='Riwayat penyakit keluarga'
            v={res.pengkajian.riwayat_penyakit_keluarga}
          />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='BAGIAN III REVIEW PERSISTEM' />
          <Text isHeader k='A. KENYAMANAN / NYERI' kStyle='mt-2' />
          <Text k='Penyebab' v={res.nyeri.penyebab} />
          <Text k='Kualitas' v={res.nyeri.kualitas} />
          <Text k='Penyebaran' v={res.nyeri.penyebaran} />
          <Text k='Keparahan' v={res.nyeri.keparahan} />
          <Text k='Waktu' v={res.nyeri.waktu} />
          <Text k='Lokasi' v={res.nyeri.lokasi} />
          <Text k='Skala Nyeri' v={`${res.nyeri.skor_nyeri}`} />
          <Text k='Nyeri hilang bila' v={res.nyeri.nyeri_hilang_bila} />
          <Text
            k='Kebutuhan edukasi / hambatan pembelajaran'
            v={res.nyeri.hambatan_pembelajaran}
          />
          <Text k='Dibutuhkan penerjemah' v={res.nyeri.dibutuhkan_penerjemah} />
          <Text
            k='Kebutuhan pembelajaran pasien'
            v={res.nyeri.kebutuhan_pembelajaran_pasien}
          />

          <Text isHeader k='B. ELIMINASI' kStyle='mt-2' />
          <Text k='BAB' v={res.persistem.eliminasi_bab} />
          <Text k='BAK' v={res.persistem.eliminasi_bak} />
          <Text k='Masalah Prostat' v={res.persistem.masalah_prostat} />

          <Text isHeader k='C. KOMUNIKASI & EDUKASI' kStyle='mt-2' />
          <Text k='Bicara' v={res.persistem.bicara} />
          <Text k='Bahasa' v={res.persistem.bahasa} />
          <Text k='Perlu penerjemah' v={res.persistem.perlu_penerjemah} />
          <Text k='Bahasa isyarat' v={res.persistem.bahasa_isyarat} />
          <Text k='Hambatan belajar' v={res.persistem.hambatan_belajar} />
          <Text k='Cara belajar' v={res.persistem.cara_belajar} />
          <Text k='Tingkat pendidikan' v={res.persistem.tingkat_pendidikan} />
          <Text
            k='Potensi kebutuhan pembelajaran'
            v={res.persistem.potensi_kebutuhan_pembelajaran}
          />

          <Text isHeader k='D. SOSIAL' kStyle='mt-2' />
          <Text k='Pekerjaan' v={res.persistem.pekerjaan} />
          <Text k='Tinggal bersama' v={res.persistem.tinggal_bersama} />
          <Text k='Status' v={res.persistem.status} />
          <Text
            k='Bantuan yang dibutuhkan'
            v={res.persistem.bantuan_yang_dibutuhkan}
          />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='BAGIAN IV DAFTAR DIAGNOSA KEPERAWATAN' />

          <div className='flex mt-2'>
            <SimpleColumn name='No' className='text-xs flex-[0.3]' />
            <SimpleColumn
              name='Diagnosa Keperawatan'
              className='text-xs flex-[2]'
            />
            <SimpleColumn name='Hasil' className='text-xs flex-[1.5]' isLast />
          </div>

          {(res.asuhan ?? []).length == 0 && <EmptyPlaceholder />}

          {(res.asuhan ?? []).map((item, index) => (
            <div className='flex' key={item.no_daskep ?? index}>
              <SimpleColumn
                name={`${index + 1}`}
                className='text-xs flex-[0.3]'
              />
              <SimpleColumn
                name={item.diagnosa?.judul || item.diagnosa?.problem || '-'}
                className='text-xs flex-[2]'
              />
              <SimpleColumn
                name={item.hasil || '-'}
                className='text-xs flex-[1.5]'
                isLast
              />
            </div>
          ))}
        </div>

        <div className='flex justify-end mt-4'>
          <div className='text-center text-xs'>
            <p>Perawat Yang Memeriksa</p>
            <div className='h-16' />
            <p>{res.pengkajian.nama_perawat || '-'}</p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
