import { useState } from 'react'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { constants } from '@/utils/constants'

import ButtonListIntervensi from './component/ButtonList'
import IntervensiResikoJatuhAnakReport from './component/ListIntervensi'
import { getIntervensiAnak } from './intervensi-anak'

interface IntervensiResikoJatuhAnakProps {
  isReport?: boolean
  noreg?: string
}

const FormulirIntervensiResikoJatuh = ({
  noreg = '',
  isReport = true,
}: IntervensiResikoJatuhAnakProps) => {
  // const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.intervensiResikoJatuhAnak, noreg],
    queryFn: () =>
      getIntervensiAnak({
        noreg: noreg!,
      }),
    enabled: !!noreg,
  })

  const res = data?.response ?? []

  const [selectedIndex, setSelectedIndex] = useState(0) // ✅ selalu di atas

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo>
      {isReport && <ReportHeader />}
      <div className='p-4'>
        <ButtonListIntervensi
          items={res}
          onChange={(idx) => setSelectedIndex(idx)}
        />

        <h1 className='text-center text-black font-semibold mb-1 mt-4'>
          INTERVENSI RISIKO JATUH PASIEN ANAK
        </h1>

        <p className='text-center'>
          Beri tanda (✓) pada tindakan yang dilaksanakan
        </p>

        <div className='mt-4'>
          <IntervensiResikoJatuhAnakReport data={res[selectedIndex]} />
        </div>
      </div>
    </LayoutBorderNo>
  )
}

export default FormulirIntervensiResikoJatuh
