import { useState } from 'react'

import { SimpleColumn } from '@/components/simple-column'
import { Dialog, DialogDescription, DialogTitle } from '@/components/ui/dialog'
import { Diagnosa } from '@/type'

interface DiagnosaTableProps {
  data: Diagnosa[]
  onEdit?: (item: Diagnosa) => void
  onDelete?: (diagnosa: string) => void
}

export function DiagnosaTable({ data }: DiagnosaTableProps) {
  const [show, setShow] = useState(false)

  if (data.length > 0) {
    return (
      <div className='mb-2'>
        <div className='flex'>
          <SimpleColumn
            head
            name='No.'
            className='w-[50px] p-1'
            className2='text-xs'
          />
          <SimpleColumn
            head
            name='Kode'
            className='p-1 flex-1'
            className2='text-xs'
          />
          <SimpleColumn
            head
            name='Deskripsi'
            className='p-1 flex-1'
            className2='text-xs'
            isLast
          />
        </div>
        {data != null &&
          data.length > 0 &&
          data.map((item, i) => (
            <div className='flex' key={i}>
              <SimpleColumn
                name={`${i + 1}`}
                className='w-[50px] p-1'
                className2='text-xs'
              />
              <SimpleColumn
                name={item.diagnosa}
                className='p-1 flex-1 items-start'
                className2='text-xs'
              />
              <SimpleColumn
                name={`${item.description}`}
                isLast
                className='p-1 flex-1 items-start'
                className2='text-xs'
              />
            </div>
          ))}

        <Dialog
          modal
          open={show}
          onOpenChange={() => {
            setShow(!show)
          }}
        >
          <DialogTitle></DialogTitle>
          <DialogDescription></DialogDescription>
        </Dialog>
      </div>
    )
  } else {
    return (
      <div className='mb-2'>
        <div className='flex'>
          <SimpleColumn
            head
            name='No.'
            className='w-[50px] p-1'
            className2='text-xs'
          />
          <SimpleColumn
            head
            name='Kode'
            className='p-1 flex-1'
            className2='text-xs'
          />
          <SimpleColumn
            head
            name='Deskripsi'
            className='p-1 flex-1'
            className2='text-xs'
            isLast
          />
        </div>

        <div className='flex'>
          <SimpleColumn isLast name='Tidak ada diagnosa' className2='text-xs' />
        </div>
      </div>
    )
  }
}
