import dayjs from 'dayjs'

import { useState } from 'react'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Skeleton } from '@/components/ui/skeleton'
import { getPasienPulangRanapByDate } from '@/services/pasien'
import { useGlobalStore } from '@/store/global.store'

import { pasienPulangCols } from '../pasien-pulang/components/pasien-pulang-col'
import RekamMedis from '../pasien-pulang/rekam-medis'
import { PasienDataTable } from '../pasien/components/table/pasien-data-table'

export default function PasienPulangRanap() {
  const { dialogId } = useGlobalStore((state) => state)

  const today = dayjs().format('YYYY-MM-DD')

  const [date, setDate] = useState(today)

  const { data, isLoading, isError, refetch, isRefetching } = useQuery({
    queryKey: ['pasien-pulang-ranap'],
    queryFn: async () => await getPasienPulangRanapByDate({ date: date }),
    staleTime: Infinity,
  })

  return (
    <>
      <div className='flex items-center justify-between p-2'>
        <div />
        <div />
        <div className='flex items-center justify-between gap-2'>
          <Input
            className='w-[150px]'
            type='date'
            value={date}
            onChange={(e) => setDate(e.target.value)}
          />
          <Button
            className='border border-white'
            onClick={async () => refetch()}
          >
            Apply
          </Button>
        </div>
      </div>

      {/* Tabel */}
      {isLoading || isRefetching ? (
        <Skeleton className='flex h-[calc(100vh-30vh)] rounded-md border' />
      ) : isError ? (
        <Error className='text-red-500' />
      ) : (
        <PasienDataTable
          columns={pasienPulangCols}
          data={data?.response ?? []}
        />
      )}
      {/* Tabel */}

      {/* RekamMedis */}
      {dialogId == 'dialog-rekam-medis' && <RekamMedis />}
      {/* RekamMedis */}
    </>
  )
}
