import { SimpleColumn } from '@/components/simple-column'
import { TriaseLaporan } from '@/models/triase.model'

const TableSkalaTriase = ({ data }: { data: TriaseLaporan }) => {
  return (
    <div>
      {/* Table */}
      {/* Header */}
      <div className='flex mt-4'>
        <SimpleColumn name='' className='border-b-0 text-xs flex-1' />
        <SimpleColumn
          name='SKALA TRIASE'
          className='border-b-0 text-xs flex-1'
        />
        <SimpleColumn name='KETERANGAN' className='border-b-0 text-xs flex-1' />
        <SimpleColumn
          name='RESPONSE TIME'
          className='border-b-0 text-xs flex-1'
          isLast
        />
      </div>
      {/* Header */}

      {/* Body */}
      <div className='border-b-[1px] border-black'>
        <Item
          n1={data.skala_triase == 'Resusitasi' ? '✓' : ''}
          n2='1'
          n3='Resusitasi'
          n4='Segera'
        />
        <Item
          n1={data.skala_triase == 'Emergency / Gawat Darurat' ? '✓' : ''}
          n2='2'
          n3='Emergency / Gawat Darurat'
          n4='10 menit'
        />
        <Item
          n1={data.skala_triase == 'Urgent / Darurat' ? '✓' : ''}
          n2='3'
          n3='Urgent / Darurat'
          n4='30 menit'
        />
        <Item
          n1={data.skala_triase == 'Semi / Darurat' ? '✓' : ''}
          n2='4'
          n3='Semi Darurat'
          n4='60 menit'
        />
        <Item
          n1={data.skala_triase == 'Tidak Darurat' ? '✓' : ''}
          n2='5'
          n3='Tidak Darurat'
          n4='120 menit'
        />
      </div>
      {/* Body */}
    </div>
  )
}

export default TableSkalaTriase

const Item = ({
  n1,
  n2,
  n3,
  n4,
}: {
  n1?: string
  n2?: string
  n3?: string
  n4?: string
}) => {
  return (
    <div className='flex boder border-b-black'>
      <SimpleColumn name={n1} className='border-b-0 text-xs flex-1' />
      <SimpleColumn
        name={`SKALA ${n2}`}
        className='border-b-0 text-xs flex-1'
      />
      <SimpleColumn name={n3} className='border-b-0 text-xs flex-1' />
      <SimpleColumn isLast name={n4} className='border-b-0 text-xs flex-1' />
    </div>
  )
}
