import type { Response } from '@/type'

import { post } from './api-2'

const getPaps = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<FormulirPaps>> => {
  const response = await post(`/v1/laporan-pernyataan-paps`, { no_reg: noreg })

  return response.data
}

export { getPaps }

export interface FormulirPaps {
  dpaps: Dpaps
  pasien: Pasien
}

export interface Dpaps {
  noreg: string
  kd_bagian: string
  no_rm: string
  insert_dttm: string
  user_id: string
  terhadap: string
  nama: string
  umur: string
  jenis_kelamin: string
  alamat: string
  ktp: string
  dirawat: string
  alasan_paps: string
  saksi1: string
  saksi2: string
  ttd_saksi1: string
  ttd_saksi2: string
  dokter_merawat: string
  ttd_dokter_merawat: string
  pernyataan: string
  ttd_pernyataan: string
}

export interface Pasien {
  no_rm: string
  nama: string
  umur: string
  jenis_kelamin: string
  alamat: string
  ktp: string
}

// Converts JSON strings to/from your types
export class Convert {
  public static toFormulirPaps(json: string): FormulirPaps {
    return JSON.parse(json)
  }

  public static formulirPapsToJson(value: FormulirPaps): string {
    return JSON.stringify(value)
  }
}
