import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { getPemasanganRestrain } from '@/services/penmed'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatTanggalV2 } from '@/utils/date_helper'

import { DataRestrain } from './pemasangan-restrain.tsx'

interface PemasanganRestrainProps {
  isReport?: boolean
  noreg?: string
}

const PemasanganRestrain = ({
  noreg = '',
  //   isReport = false,
}: PemasanganRestrainProps) => {
  const { pasien } = usePasienStore((state) => state)

  const tglLahir = formatTanggalV2(pasien?.tgl_lahir || pasien?.tgl_lahir || '')

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.pemasanganRestarin, noreg],
    queryFn: () =>
      getPemasanganRestrain({
        noreg: noreg!,
      }),
    enabled: !!noreg,
  })

  const res = data?.response ?? []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo>
      <div className='p-4'>
        <h1 className='text-center text-black font-semibold mb-1'>
          PEMASANGAN RESTRAIN
        </h1>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={tglLahir}
          />
        )}
        {/* Informasi Pasien */}

        <div className='flex text-xs'>
          <SimpleColumn head name='No.' className='w-[100px]' />
          <SimpleColumn head name='TD' className='flex-[0.5]' />
          <SimpleColumn head name='HR' className='flex-[0.5]' />
          <SimpleColumn head name='TEMP' className='flex-[0.5]' />
          <SimpleColumn head name='TANGAN KANAN' className='flex-[0.5]' />
          <SimpleColumn head name='TANGAN KIRI' className='flex-[0.5]' />
          <SimpleColumn head name='KAKI KANAN' className='flex-[0.5]' />
          <SimpleColumn head name='KAKI KIRI' className='flex-[0.5]' />
          <SimpleColumn head name='LUKA' className='flex-[0.5]' />
          <SimpleColumn head name='PERAWAT' className='flex-[0.5]' isLast />
        </div>

        <div className='mt-0'>
          <DataRestrain data={res} />
        </div>
      </div>
    </LayoutBorderNo>
  )
}

export default PemasanganRestrain
