import type { Response } from '@/type'

import { get } from './api-2'

export interface KartuObservasiIntensive {
  id_observasi: number
  jam: string
  t: string
  n: string
  p: string
  s: string
  cvp: string
  ekg: string
  pupil_kiri: string
  pupil_kanan: string
  redaksi_kiri: string
  redaksi_kanan: string
  anggota_badan: string
  kesadaran: string
  sputum_warna: string
  isi_cup: string
  keterangan: string
}

export interface KartuCairanIntensive {
  id_kartu: number
  jam: string
  cairan_masuk1: string
  cairan_masuk2: string
  cairan_masuk3: string
  cairan_masuk_ngt: string
  nama_cairan: string
  cairan_keluar_urine: string
  cairan_keluar_ngt: string
  drain_dll: string
  keterangan: string
}

const getKartuObservasiIntensive = async (
  noreg: string,
): Promise<Response<KartuObservasiIntensive[]>> => {
  const response = await get('/v1/kartu-observasi', { noreg }, { noreg })

  return response.data
}

const getKartuCairanIntensive = async (
  noreg: string,
): Promise<Response<KartuCairanIntensive[]>> => {
  const response = await get('/v1/kartu-cairan', { noreg }, { noreg })

  return response.data
}

export { getKartuObservasiIntensive, getKartuCairanIntensive }
