export function toHeaderTitle(kd_bagian: string) {
  return match(kd_bagian)
    .with(
      'POL020',
      () => 'PENGKAJIAN AWAL PASIEN RAWAT INAP MEDICAL (Interna, Paru, Kardio)',
    )
    .with(
      'POL033',
      () => 'PENGKAJIAN AWAL PASIEN RAWAT INAP MEDICAL (Interna, Paru, Kardio)',
    )
    .with(
      'POL021',
      () => 'PENGKAJIAN AWAL PASIEN RAWAT INAP MEDICAL (Interna, Paru, Kardio)',
    )
    .with('POL011', () => 'PENGKAJIAN AWAL PASIEN RAWAT INAP BEDAH')
    .with('POL012', () => 'PENGKAJIAN AWAL PASIEN RAWAT INAP BEDAH')
    .with('POL013', () => 'PENGKAJIAN AWAL PASIEN RAWAT INAP BEDAH')
    .with('POL026', () => 'PENGKAJIAN AWAL PASIEN RAWAT INAP NEUROLOGI')
    .with('POL027', () => 'PENGKAJIAN AWAL MEDIS PASIEN OBSTETRI & GINEKOLOGI')
    .with('POL019', () => 'PENGKAJIAN AWAL PASIEN RAWAT INAP ANAK')
    .otherwise(() => '')
}

export function toHeaderNo(kd_bagian: string) {
  return match(kd_bagian)
    .with('POL020', () => 'RM. RI 03 A')
    .with('POL033', () => 'RM. RI 03 A')
    .with('POL021', () => 'RM. RI 03 A')
    .with('POL027', () => 'RM. RI 03 B')
    .with('POL019', () => 'RM. RI 03 C')
    .with('POL011', () => 'RM. RI 03 d')
    .with('POL012', () => 'RM. RI 03 d')
    .with('POL026', () => 'RM. RI 03 F')
    .otherwise(() => '')
}
