import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import Text from '@/components/text'
import { getPemilihanDpjp } from '@/services/pemilihan-dpjp'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportPemilihanDpjpProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportPemilihanDpjp({
  isReport = false,
  noreg = '',
  no,
}: ReportPemilihanDpjpProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.pemilihanDpjp,
      noreg,
      pasien?.no_rm,
    ],
    queryFn: () => getPemilihanDpjp({ no_reg: noreg, no_rm: pasien!.no_rm }),
    enabled: !!noreg && !!pasien?.no_rm,
  })

  const res = data?.response

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return <EmptyPlaceholder />

  const pemilihan = res.pemilihan_dpjp ?? res.pemilihan_djp
  const dataPasien = res.pasien

  if (pemilihan == null || dataPasien == null) return <EmptyPlaceholder />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          FORMULIR PEMILIHAN DPJP
        </h1>
        <p className='text-center mb-2'>
          (DOKTER PENANGGUNG JAWAB PASIEN) RAWAT INAP
        </p>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='YANG MENYATAKAN' />
          <Text kStyle='min-w-[250px]' k='Nama' v={pemilihan.nama} />
          <Text kStyle='min-w-[250px]' k='Umur / TTL' v={pemilihan.umur} />
          <Text kStyle='min-w-[250px]' k='Alamat' v={pemilihan.alamat} />
          <Text
            kStyle='min-w-[250px]'
            k='Hubungan dengan Pasien'
            v={pemilihan.hubungan}
          />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='PASIEN' />
          <Text kStyle='min-w-[250px]' k='Nama' v={dataPasien.nama} />
          <Text kStyle='min-w-[250px]' k='Umur / TTL' v={dataPasien.umur} />
          <Text kStyle='min-w-[250px]' k='Alamat' v={dataPasien.alamat} />
          <Text kStyle='min-w-[250px]' k='No. RM' v={dataPasien.no_rm} />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='PERNYATAAN' />
          <p className='mt-2'>
            Dengan ini menyatakan dengan sadar dan sesungguhnya bahwa:
          </p>
          <p className='mt-1'>
            1. Telah menerima dan memahami informasi mengenai dokter penanggung
            jawab pasien selama dirawat di Rumah Sakit.
          </p>
          <p className='mt-1'>
            2. Berdasarkan hal tersebut di atas, saya memilih dokter:{' '}
            <strong>{pemilihan.dokter || '-'}</strong> sebagai dokter penanggung
            jawab.
          </p>
          <p className='mt-1'>
            Demikian pernyataan ini saya buat dengan sebenar-benarnya.
          </p>
        </div>

        <div className='grid grid-cols-2 gap-2 mt-4'>
          <div className='text-center'>
            <Text isHeader k='Yang Menyatakan' />
            <div className='h-14' />
            <p>{pemilihan.nama || '-'}</p>
          </div>
          <div className='text-center'>
            <Text isHeader k='Petugas' />
            <div className='h-14' />
            <p>{pemilihan.petugas || '-'}</p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
