import type { Response } from '@/type'

import { patch } from './api-2'

export const INIT_RES_PEMBERIAN_TERAPI_CAIRAN:ResPemberianCairan = {
  cairan: [],
  pasien: {
    id: '',
    nik: '',
    nama: '',
    agama: '',
    jeniskelamin: '',
    email: '',
    hp: '',
    tgl_lahir: '',
    alamat: ''
  }
}

export interface Pasien {
  id: string;
  nik: string;
  nama: string;
  agama: string;
  jeniskelamin: string;
  email: string;
  hp: string;
  tgl_lahir: string;
  alamat: string;
}


export interface ResPemberianCairan {
  cairan: DaftarPemberianTerapiCairan[];
  pasien: Pasien;
}

export interface DaftarPemberianTerapiCairan {
  insert_dttm: string
  jumlah_infuse: string
  sisa_infuse: string
  noreg: string
  nama_cairan: string
  dosis_makro: string
  dosis_mikro: string
  fls_ke: number
  obat_ditambahkan: string
  keterangan: string
  perawat: {
    nama: string
  }
  pelayanan: {
    kd_bag: string
    bagian: string
    pelayanan: string
  }
}

const getDaftarPemberianTerapiCairan = async (
  no_reg: string,
  no_rm: string,
): Promise<Response<ResPemberianCairan>> => {
  const response = await patch('/v4/pemberian-terapi-cairan-infuse', {
    no_reg,
    no_rm
  })

  return response.data
}

export { getDaftarPemberianTerapiCairan }
