import type { MonitoringTansfusiDarahModel } from '@/models/monitoring-monitoring-transfusi-darah'
import type { Response } from '@/type'

import { post } from './api-2'

const getMonitoringTransfusiDarah = async ({
  no_reg,
  kd_bagian,
}: {
  no_reg: string
  kd_bagian: string
}): Promise<Response<MonitoringTansfusiDarahModel[]>> => {
  const response = await post(`v4/transfusi-darah/get`, {
    no_reg,
    kd_bagian,
  })

  return response.data
}

export { getMonitoringTransfusiDarah }
