import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import { asesmenNyeriIcon } from '@/assets/images/asesmen_nyeri'
import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import Text from '@/components/text'
import type { TriaseLaporan } from '@/models/triase.model'
import { getTriase } from '@/services/triase'
import { usePasienStore } from '@/store/pasien.store'
import { Pasien } from '@/type'
import { constants } from '@/utils/constants'
import { formatDate } from '@/utils/formatDate'

import TableFlacc from './table-flacc'
import TableSkalaTriase from './table-skala-triase'

interface TriaseProps {
  isReport?: boolean
  no?: string
  noreg?: string
}

const initTriase: TriaseLaporan = {
  tanggal: '',
  jam: '',
  keluhan_utama: '',
  alasan_datang: '',
  penyebab_cedera: '',
  status_kehamilan: '',
  nama: '',
  gravida: '',
  para: '',
  abortus: '',
  hpht: '',
  ddj: '',
  tanda_vital: {
    jalan_nafas: '',
    pupil: '',
    reflex_cahaya: '',
    td: '',
    nadi: '',
    suhu: '',
    pernafasan: '',
    spo2: '',
    gcs_e: '',
    gcs_v: '',
    gcs_m: '',
    akral: '',
    kesadaran: '',
  },
  status_alergi: '',
  status_alergi_detail: '',
  gangguan_perilaku: '',
  gangguan_perilaku_detail: '',
  nyeri: '',
  skala_nyeri: 0,
  nyeri_p: '',
  nyeri_q: '',
  nyeri_r: '',
  nyeri_s: '',
  nyeri_t: '',
  skala_triase: '',
  flag_wajah: 0,
  flag_kaki: 0,
  flag_aktifitas: 0,
  flag_menangis: 0,
  flag_bersuara: 0,
  flag_total: 0,
}

export default function Triase({
  isReport = false,
  no = '',
  noreg = '',
}: TriaseProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.triase, noreg],
    queryFn: () => getTriase({ noreg }),
    enabled: !!noreg,
  })

  const res = data?.response != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return <EmptyPlaceholder />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader pasien={pasien ?? ({} as Pasien)} />}

      {/* Content */}
      <h1 className='text-center text-black font-semibold mb-2 pt-4'>TRIASE</h1>
      <div className='p-2'>
        {/* Keluhan Utama */}
        <div className='border border-black p-2 mb-1'>
          <Text
            kStyle='font-semibold min-w-[100px]'
            k='Keluhan Utama'
            v={res?.keluhan_utama}
          />
        </div>
        {/* Keluhan Utama */}

        {/* Tanda Vital */}
        <div className='border border-black p-2 mb-1'>
          <p className='text-xs font-semibold'>Tanda Tanda Vital</p>
          <div className='flex items-center justify-between'>
            <div>
              <Text
                kStyle='min-w-[100px]'
                k='Jalan Nafas'
                v={res?.tanda_vital?.jalan_nafas}
              />
              <Text
                kStyle='min-w-[100px]'
                k='Td'
                v={`${res?.tanda_vital?.td} mmHg`}
              />
              <Text
                kStyle='min-w-[100px]'
                k='Pernafasan'
                v={`${res?.tanda_vital?.pernafasan} x/menit`}
              />
              <Text
                kStyle='min-w-[100px]'
                k='GCS'
                v={`E:${res?.tanda_vital?.gcs_e} M:${res?.tanda_vital?.gcs_m}  V:${res?.tanda_vital?.gcs_v}`}
              />
            </div>
            <div>
              <Text
                kStyle='min-w-[100px]'
                k='Pupil'
                v={res?.tanda_vital?.pupil}
              />
              <Text
                kStyle='min-w-[100px]'
                k='Nadi'
                v={`${res?.tanda_vital?.nadi} x/menit`}
              />
              <Text
                kStyle='min-w-[100px]'
                k='SpO2'
                v={`${res?.tanda_vital?.spo2} %`}
              />
            </div>
            <div>
              <Text
                kStyle='min-w-[100px]'
                k='Refleks Cahaya'
                v={res?.tanda_vital?.reflex_cahaya}
              />
              <Text
                kStyle='min-w-[100px]'
                k='Suhu'
                v={`${res?.tanda_vital?.suhu}°C`}
              />
              <Text
                kStyle='min-w-[100px]'
                k='Akral'
                v={res?.tanda_vital?.akral}
              />
            </div>
          </div>
        </div>
        {/* Tanda Vital */}

        {/* Status Alergi */}
        <div className='border border-black p-2 mb-1'>
          <Text
            kStyle='font-semibold min-w-[100px]'
            k='Status Alergi'
            v={res?.status_alergi}
          />
          {res?.status_alergi == 'ADA' && (
            <Text
              kStyle='font-semibold min-w-[100px]'
              k='Reaksi Alergi'
              v={res?.status_alergi_detail}
            />
          )}
        </div>
        {/* Status Alergi */}

        {/* Gangguan Perilaku */}
        <div className='border border-black p-2 mb-1'>
          <Text
            kStyle='font-semibold min-w-[100px]'
            k='Gangguan Perilaku'
            v={res?.gangguan_perilaku}
          />
        </div>
        {/* Gangguan Perilaku */}

        {/* Asesmen Nyeri */}
        <div className='border border-black p-2 mb-1'>
          <p className='text-xs font-semibold'>Skala Nyeri</p>
          <div className='flex p-4'>
            <div className='flex flex-col flex-1 items-center justify-center p-4'>
              <img
                src={toScoreNyeri(res.skala_nyeri)}
                className='h-[60px] object-contain mb-4'
              />
              <Text
                kStyle='min-w-[16px]'
                k='Skala Nyeri'
                v={res.skala_nyeri.toString()}
              />
            </div>
            <div className='flex flex-col flex-1 p-4'>
              <Text kStyle='min-w-[16px]' k='P' v={res.nyeri_p} />
              <Text kStyle='min-w-[16px]' k='Q' v={res.nyeri_q} />
              <Text kStyle='min-w-[16px]' k='R' v={res.nyeri_r} />
              <Text kStyle='min-w-[16px]' k='S' v={res.nyeri_s} />
              <Text kStyle='min-w-[16px]' k='T' v={res.nyeri_t} />
            </div>
          </div>
        </div>
        {/* Asesmen Nyeri */}

        {/* Skala FLACC */}
        <TableFlacc data={res ?? initTriase} />
        {/* Skala FLACC */}

        {/* Skala Triase */}
        <TableSkalaTriase data={res ?? initTriase} />
        {/* Skala Triase */}
      </div>
      {/* Content */}

      {/* Petugas Triase */}
      <div className='p-2 mb-1 m-2'>
        {res.nama != '' && (
          <div className='flex justify-end'>
            <div className='flex flex-col gap-2 text-center items-center'>
              <p className='text-xs font-semibold'>
                {formatDate(res.tanggal)}
                {` `}
                {res.jam} WIB
              </p>
              <p className='text-xs font-semibold'>Petugas Triase</p>
              <QRCode
                value={res.nama}
                className='w-[50px] h-[50px] object-contain'
              />
              <p className='text-xs font-semibold'>({res.nama})</p>
            </div>
          </div>
        )}
      </div>
      {/* Petugas Triase */}
    </LayoutBorderNo>
  )
}

function toScoreNyeri(n: number) {
  if (n == 1 || n == 2) {
    return asesmenNyeriIcon.AN1
  }

  if (n == 3 || n == 4) {
    return asesmenNyeriIcon.AN2
  }

  if (n == 5 || n == 6) {
    return asesmenNyeriIcon.AN3
  }

  if (n == 7 || n == 8) {
    return asesmenNyeriIcon.AN4
  }

  if (n == 9 || n == 10) {
    return asesmenNyeriIcon.AN5
  }

  return asesmenNyeriIcon.AN1
}
