import { PDFViewer } from '@react-pdf/renderer'
import { createFileRoute } from '@tanstack/react-router'

// 1. Import the Viewer
import { MyDocument } from '@/features/laporan/Laporan'

export const Route = createFileRoute('/laporan')({
  component: Render,
})

function Render() {
  return (
    // 2. Wrap your document in the Viewer
    // Use style to make it full screen
    <PDFViewer style={{ width: '100%', height: '100vh', border: 'none' }}>
      <MyDocument />
    </PDFViewer>
  )
}
