import type { Response } from '@/type'

import { get } from './api-2'

export interface PermintaanDnr {
  pasien: {
    nama_pasien: string
    nik: string
    tgl_lahir: string
    no_rm: string
    alamat: string
    no_hp: string
    umur: string
    jenis_kelamin: string
  }
  permintaan: {
    tanggal: string
    nama: string
    umur: string
    jenis_kelamin: string
    alamat: string
    hubungan: string
    nama_yang_menyatakan: string
    ttd_yang_menyatakan: string
    nama_dokter: string
    ttd_dokter: string
    nama_saksi1: string
    ttd_saksi1: string
    nama_saksi2: string
    ttd_saksi2: string
  }
}

const getPermintaanDnr = async ({
  no_reg,
  no_rm,
}: {
  no_reg: string
  no_rm: string
}): Promise<Response<PermintaanDnr>> => {
  const params = { no_reg, no_rm }
  const response = await get('/v1/permintaan-dnr', params, params)

  return response.data
}

export { getPermintaanDnr }
