import type { Response } from '@/type'

import { get } from './api-2'

export interface PemilihanDpjp {
  pasien: {
    nama: string
    umur: string
    alamat: string
    no_rm: string
  }
  pemilihan_dpjp?: PemilihanDpjpData
  pemilihan_djp?: PemilihanDpjpData
}

export interface PemilihanDpjpData {
  hubungan: string
  nama: string
  umur: string
  alamat: string
  dokter: string
  petugas: string
  ttd_petugas: string
  ttd_pernyataan: string
}

const getPemilihanDpjp = async ({
  no_reg,
  no_rm,
}: {
  no_reg: string
  no_rm: string
}): Promise<Response<PemilihanDpjp>> => {
  const params = { no_reg, no_rm }
  const response = await get('/v4/pemilihan-dpjp', params, params)

  return response.data
}

export { getPemilihanDpjp }
