import { EWSModel } from '@/models/ews-model'
import { Response } from '@/type'

import { post } from './api-2'

export const initEWS: EWSModel = {
  kontrol_pasien: [],
  keterangan: {
    ringan: '',
    sedang: '',
    tinggi: '',
    henti_nafas: '',
  },
  monitoring_cairan: [],
  nyeri: [],
}

const getEws = async ({
  noReg,
  kdBagian,
}: {
  kdBagian: string
  noReg: string
}): Promise<Response<EWSModel>> => {
  const response = await post(`/v1/data-kontrol-pasien`, {
    kd_bagian: kdBagian,
    no_reg: noReg,
  })

  return response.data
}

export { getEws }
