import QRCode from 'react-qr-code'

import { ResikoJatuh } from '../intervensi-dewasa'

interface DailyData {
  tanggal: string
  resiko_jatuh: ResikoJatuh[]
}

// -------------------------------------------------------
// Definisi intervensi per kategori
// -------------------------------------------------------
const INTERVENSI_RENDAH = [
  'Pastikan bel, peralatan pribadi mudah dijangkau',
  'Pastikan posisi tempat tidur pada poisisi terendah dan terkunci',
  'Pasang pagar tempat tidur /Brakard',
  'Orientasi pasien / penunggu tentang lingkungan/ ruang sekitar',
  'Pasang busa penyanggah pagar tempat tidur pada pasien anak-anak',
  'Anjurkan pasien menggunakan alas kaki anti selip/ tidak licin',
  'Edukasi pasien toileting dan edukasi perilaku pencegahan jatuh',
]

const INTERVENSI_SEDANG = [
  'Pasang tanda resiko jatuh (tempel striker kuning) pada gelang identitas pasien',
  'Pasang tanda risiko jatuh pada tempat tidur bagian kaki pasien (segitiga kuning/segitiga merah)',
  'Beri tanda resiko jatuh pada pintu kamar pasien ( RT )',
  'Libatkan keluarga dengan edukasi lebih ketat tentang pencegahan jatuh',
  'Tingkatkan observasi/bantuan saat ambulansi',
  'Instruksikan pasien untuk tidak bangun tanpa pertolongan',
  'Dampingi pasien dalam kegiatan ADL',
  'Kunjungi dan monitor pasien setiap jam',
  'Pasien ditempatkan dekat Nurse Station',
  'Lakukan Fiksasi fisik (Restrain) dengan persetujuan keluarga',
]

function getChecked(
  data: ResikoJatuh | undefined,
  key: keyof ResikoJatuh,
): boolean {
  return data ? (data[key] as boolean) : false
}

interface ShiftData {
  pagi?: ResikoJatuh
  sore?: ResikoJatuh
  malam?: ResikoJatuh
}

function getShiftData(list: ResikoJatuh[]): ShiftData {
  return {
    pagi: list.find((r) => r.shift.toLowerCase() === 'pagi'),
    sore: list.find((r) => r.shift.toLowerCase() === 'sore'),
    malam: list.find((r) => r.shift.toLowerCase() === 'malam'),
  }
}

const CheckMark = ({ checked }: { checked: boolean }) =>
  checked ? <span className='text-lg font-bold text-gray-800'>✓</span> : null

interface IntervensiSectionProps {
  label: string
  color: string
  textColor: string
  items: string[]
  resikoKeys: (keyof ResikoJatuh)[]
  shifts: ShiftData
  index: number
}

function IntervensiSection({
  label,
  color,
  textColor,
  items,
  resikoKeys,
  shifts,
  index,
}: IntervensiSectionProps) {
  return (
    <>
      {/* Sub-header kategori */}
      <tr>
        <td className='border border-gray-400' />
        <td
          className={`border border-gray-400 px-3 py-1.5 text-center text-sm font-semibold ${color} ${textColor}`}
        >
          {label}
        </td>
        <td className='border border-gray-400' />
        <td className='border border-gray-400' />
        <td className='border border-gray-400' />
      </tr>

      {items.map((item, i) => {
        const key = resikoKeys[i]
        return (
          <tr key={i} className='align-top'>
            <td className='border border-gray-400 px-3 py-2 text-center text-sm'>
              {i + index}
            </td>
            <td className='border border-gray-400 px-3 py-2 text-sm leading-snug'>
              {item}
            </td>
            <td className='border border-gray-400 px-3 py-2 text-center'>
              <CheckMark checked={getChecked(shifts.pagi, key)} />
            </td>
            <td className='border border-gray-400 px-3 py-2 text-center'>
              <CheckMark checked={getChecked(shifts.sore, key)} />
            </td>
            <td className='border border-gray-400 px-3 py-2 text-center'>
              <CheckMark checked={getChecked(shifts.malam, key)} />
            </td>
          </tr>
        )
      })}

      {/* INTERVENSI_SEDANG */}

      {label === 'Resiko Sedang' && (
        <>
          <tr key={1} className='align-top'>
            <td className='border border-gray-400 px-3 py-2 text-center text-sm'></td>
            <td className='border border-gray-400 px-3 py-2 text-sm leading-snug'>
              {'Nama Perawat'}
            </td>
            <td className='border border-gray-400 px-3 py-2 text-center'>
              <div>
                <div className='bg-white border-b  py-1 px-2 text-xs  text-gray-600 uppercase tracking-wide text-center'>
                  {shifts.pagi?.nama_perawat ?? ''}
                </div>

                <div className='py-3 px-2 flex flex-col items-center justify-center'>
                  {shifts.pagi?.nama_perawat ? (
                    <QRCode
                      value={shifts.pagi.nama_perawat}
                      className='h-[50px] w-[50px]'
                    />
                  ) : (
                    <div className='h-[50px] w-[50px]' />
                  )}
                </div>
              </div>
            </td>
            <td className='border border-gray-400 px-3 py-2 text-center'>
              <div>
                <div className='bg-white border-b  py-1 px-2 text-xs  text-gray-600 uppercase tracking-wide text-center'>
                  {shifts.sore?.nama_perawat ?? ''}
                </div>

                <div className='py-3 px-2 flex flex-col items-center justify-center'>
                  {shifts.sore?.nama_perawat ? (
                    <QRCode
                      value={shifts.sore.nama_perawat}
                      className='h-[50px] w-[50px]'
                    />
                  ) : (
                    <div className='h-[50px] w-[50px]' />
                  )}
                </div>
              </div>
            </td>
            <td className='border border-gray-400 px-3 py-2 text-center'>
              <div>
                <div className='bg-white border-b  py-1 px-2 text-xs  text-gray-600 uppercase tracking-wide text-center'>
                  {shifts.malam?.nama_perawat ?? ''}
                </div>

                <div className='py-3 px-2 flex flex-col items-center justify-center'>
                  {shifts.malam?.nama_perawat ? (
                    <QRCode
                      value={shifts.malam.nama_perawat}
                      className='h-[50px] w-[50px]'
                    />
                  ) : (
                    <div className='h-[50px] w-[50px]' />
                  )}
                </div>
              </div>
            </td>
          </tr>
        </>
      )}
    </>
  )
}

interface Props {
  data: DailyData
}

export default function ResikoJatuhReport({ data }: Props) {
  const shifts = getShiftData(data.resiko_jatuh)

  const formatDate = (d: string) =>
    new Date(d).toLocaleDateString('id-ID', {
      day: '2-digit',
      month: 'long',
      year: 'numeric',
    })

  return (
    <div className='p-6 bg-white min-h-screen'>
      <p className='text-xs text-gray-500 mb-3'>
        Tanggal: {formatDate(data.tanggal)}
      </p>

      <table className='w-full border-collapse border border-gray-400 text-sm'>
        <thead>
          {/* Baris 1: header utama */}
          <tr>
            <th
              rowSpan={2}
              className='border border-gray-400 px-3 py-2 text-center font-semibold w-12'
            >
              No.
            </th>
            <th
              rowSpan={2}
              className='border border-gray-400 px-3 py-2 text-center font-semibold uppercase'
            >
              INTERVENSI
            </th>
            <th
              colSpan={2}
              className='border border-gray-400 px-3 py-2 text-center font-semibold uppercase'
            >
              TANGGAL / SIHIF
            </th>
            <th className='border border-gray-400 px-3 py-2 text-center font-semibold uppercase'>
              TANGGAL,
            </th>
          </tr>
          {/* Baris 2: sub-header shift */}
          <tr>
            <th className='border border-gray-400 px-3 py-2 text-center font-semibold uppercase text-xs w-20'>
              PAGI
            </th>
            <th className='border border-gray-400 px-3 py-2 text-center font-semibold uppercase text-xs w-20'>
              SORE
            </th>
            <th className='border border-gray-400 px-3 py-2 text-center font-semibold uppercase text-xs w-20'>
              MALAM
            </th>
          </tr>
        </thead>

        <tbody>
          {/* Resiko Rendah */}
          <IntervensiSection
            index={1}
            label='Resiko Rendah'
            color='bg-blue-400'
            textColor='text-white'
            items={INTERVENSI_RENDAH}
            resikoKeys={[
              'resiko1',
              'resiko2',
              'resiko3',
              'resiko4',
              'resiko5',
              'resiko6',
              'resiko7',
            ]}
            shifts={shifts}
          />

          {/* Resiko Sedang */}
          <IntervensiSection
            index={8}
            label='Resiko Sedang'
            color='bg-orange-400'
            textColor='text-white'
            items={INTERVENSI_SEDANG}
            resikoKeys={['resiko8', 'resiko9', 'resiko10', 'resiko11']}
            shifts={shifts}
          />
        </tbody>
      </table>
    </div>
  )
}
