import { post } from '@/services/api-2'
import type { Labor, Radiologi, Response } from '@/type'

export interface TransferIntra {
  ruang_asal: string
  asal_kelas: string
  asal_kamar: string
  ke: string
  ke_kelas: string
  ke_kamar: string
  dokter_dpjp: string
  diagnosa_utama: DiagnosaUtama[]
  diagnosa_sekunder: any[]
  alasan_pindah: AlasanPindah
  penggunaan_oksigen: string
  cairan_parental: string
  transfusi: string
  penggunaan_kateter: string
  pemakaian_ke: string
  pemakaian_tanggal: string
  pemakaian_pukul: string
  diet: string
  mobilisasi: string
  edukasi: string
  labor: Labor[]
  radiologi: Radiologi[]
  fisioterapi: Radiologi[]
  riwayat_tambahan: RiwayatTambahan
  tingkat_kemampuan_fungsi: TingkatKemampuanFungsi
  barang_yang_disertakan: string
  sebelum_transfer: Transfer
  setelah_transfer: Transfer
  dpjp: Dpjp
  yang_menerima: Dpjp
  yang_menyerahkan: Dpjp
}

export interface AlasanPindah {
  kondisi_pasien: string
  fasilitas: string
  tenaga: string
  'lain-lain': string
}

export interface DiagnosaUtama {
  ppa: Ppa
  diagnosa: Diagnosa
  description: string
  type: string
  table: string
}

export enum Diagnosa {
  A16 = 'A16',
  B90 = 'B90',
  J180 = 'J18.0',
}

export enum Ppa {
  Dpjp = 'dpjp',
}

export interface Dpjp {
  nama: string
  ttd: string
}

export interface Penlab {
  pemeriksaan_deskripsi: string
  normal: string
  satuan: string
  hasil: string
  kategori: Kategori
  status_kritis: string
}

export enum Kategori {
  Atas = 'ATAS',
  Bawah = 'BAWAH',
  Normal = 'NORMAL',
}

export interface RadiologiRadiologi {
  id_penlab: number
  pemeriksaan_deskripsi: string
  uraian: string
  hasil: string
}

export interface RiwayatTambahan {
  penglihatan: string
  pendengaran: string
  komunikasi: string
}

export interface Transfer {
  keadaan_umum: string
  tanda_vital: string
  catatan_penting: string
}

export interface TingkatKemampuanFungsi {
  bed_aktivity: string
  personal_hygine: string
  dressing: string
  eating: string
  transfer: string
}

export class Convert {
  public static toTransferIntra(json: string): TransferIntra {
    return JSON.parse(json)
  }

  public static transferIntraToJson(value: TransferIntra): string {
    return JSON.stringify(value)
  }
}

const getAllTransferIntra = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<TransferIntra[]>> => {
  const response = await post(`/v1/all-transfer-pasien/get`, {
    no_reg: noreg,
  })

  return response.data
}

export { getAllTransferIntra }
