// Converts JSON strings to/from your types
export class Convert {
  public static toReportHD(json: string): ReportHD {
    return JSON.parse(json)
  }

  public static reportHDToJson(value: ReportHD): string {
    return JSON.stringify(value)
  }
}

const getHD = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<ReportHD>> => {
  const response = await post(`/v2/poli-hd`, {
    no_reg: noreg,
  })

  return response.data
}

export { getHD }

