import { useState } from 'react'

export default function PainAssessmentReport() {
  const [identitasPasien, setIdentitasPasien] = useState('')
  const [tanggal, setTanggal] = useState('')
  const [jam, setJam] = useState('')
  const [P, setP] = useState('')
  const [Q, setQ] = useState('')
  const [R, setR] = useState('')
  const [S, setS] = useState('')
  const [T, setT] = useState('')

  return (
    <div className='bg-white min-h-screen p-4 font-sans text-sm text-black'>
      <div className='max-w-3xl mx-auto border border-black'>
        {/* Title */}
        <div className='border-b border-black text-center py-2 font-bold text-sm tracking-wide'>
          FORMULIR ASESMEN / ASESMEN ULANG NYERI
        </div>

        {/* Identity */}
        <div className='border-b border-black px-3 py-2 space-y-1'>
          <div className='flex gap-2 items-center'>
            <span className='font-bold whitespace-nowrap text-xs'>
              IDENTITAS PASIEN :
            </span>
            <input
              className='flex-1 border-b border-black outline-none bg-transparent text-xs'
              value={identitasPasien}
              onChange={(e) => setIdentitasPasien(e.target.value)}
            />
          </div>
          <div className='flex gap-2 items-center'>
            <span className='font-bold whitespace-nowrap text-xs'>
              TANGGAL / JAM ASESMEN :
            </span>
            <input
              type='date'
              className='border-b border-black outline-none bg-transparent text-xs'
              value={tanggal}
              onChange={(e) => setTanggal(e.target.value)}
            />
            <input
              type='time'
              className='border-b border-black outline-none bg-transparent text-xs'
              value={jam}
              onChange={(e) => setJam(e.target.value)}
            />
          </div>
        </div>

        {/* PQRST Fields */}
        {[
          { key: 'P', val: P, set: setP },
          { key: 'Q', val: Q, set: setQ },
          { key: 'R', val: R, set: setR },
          { key: 'S', val: S, set: setS },
          { key: 'T', val: T, set: setT },
        ].map(({ key, val, set }) => (
          <div key={key} className='border-b border-black px-3 pt-1 pb-2'>
            <div className='flex items-center gap-2'>
              <span className='font-normal text-xs w-5 shrink-0'>{key} :</span>
              <input
                className='flex-1 outline-none bg-transparent text-xs border-b border-transparent focus:border-gray-400'
                value={val}
                onChange={(e) => set(e.target.value)}
              />
            </div>
            {/* dotted separator line */}
            <div
              className='mt-2 w-full'
              style={{
                borderBottom: '1px dotted #999',
              }}
            />
          </div>
        ))}

        {/* Skala Nyeri Legend */}
        <div className='border-b border-black px-3 py-2'>
          <div className='font-bold text-xs mb-0.5'>Skala Nyeri</div>
          <div className='font-bold text-xs mb-1'>Keterangan :</div>
          <ul className='list-disc pl-5 space-y-1 text-xs leading-snug'>
            <li>
              <span className='font-bold'>P</span> = Provokatif : yang
              memprovokasi nyeri , Apa yang menjadi penyebab nyeri ? →{' '}
              Rudapaksa, benturan ?
              <br />
              <span className='pl-3'>
                Apa yang membuat lebih baik atau buruk ?
              </span>
            </li>
            <li>
              <span className='font-bold'>Q</span> = Quality / Kualitas :
              Seperti apa rasanya ?
              <br />
              <span className='pl-3'>
                Seperti tertusuk benda tajam, tumpul , sakit, berdenyut, ditusuk
                jarum, dll ?
              </span>
            </li>
            <li>
              <span className='font-bold'>R</span> = Regio / Radiasi : Daerah
              nyeri , Dimana rasa sakit itu berada ? → →
              <br />
              <span className='pl-3'>Menyebar kemana ?</span>
            </li>
            <li>
              <span className='font-bold'>S</span> = Severity / Skala : Seberapa
              berat pakai skala 0 sd 10 →
            </li>
            <li>
              <span className='font-bold'>T</span> = Tempo / timing : Waktu yang
              berkaitan dengan nyeri, Kapan nyeri datang ?
              <br />
              <span className='pl-3'>
                Apa rasa sakit itu datang dan pergi atau terus menerus ?
              </span>
            </li>
          </ul>
        </div>

        {/* Bottom two-column section */}
        <div className='flex text-xs'>
          {/* Left column */}
          <div className='flex-1 border-r border-black px-3 py-2 space-y-3'>
            {/* Scale 1 */}
            <div>
              <p className='mb-1 leading-snug'>
                <span className='font-bold'>1.</span> Pada pasien dewasa dan
                anak &gt; 9 tahun, tingkat nyeri diukur dengan skala motorik
                sebagai berikut :
              </p>
              <div className='pl-4 space-y-0.5'>
                <div>a. &nbsp;&nbsp; 0 = tidak nyeri</div>
                <div>
                  b. &nbsp;&nbsp; 1 – 3 = nyeri ringan ( sedikit terganggu
                  aktivitas sehari-hari)
                </div>
                <div>
                  c. &nbsp;&nbsp; 4 – 6 = nyeri sedang ( gangguan nyata terhadap
                  aktivitas sehari-hari)
                </div>
                <div>
                  d. &nbsp;&nbsp; 7 – 10 = nyeri berat ( tidak dapat melakukan
                  aktivitas sehari-hari)
                </div>
              </div>
            </div>

            {/* Scale 2 */}
            <div>
              <p className='mb-1 leading-snug'>
                <span className='font-bold'>2.</span> Pada pasien (dewasa dan
                anak &gt;3 tahun) yang tidak dapat menggambarkan identitas nyeri
                dengan angka, gunakan Wong Baker Faces Pain Scale :
              </p>
              <div className='pl-4 space-y-0.5'>
                <div>
                  a. &nbsp;&nbsp; 0 – 1 sangat bahagia karena tidak nyeri sama
                  sekali
                </div>
                <div>b. &nbsp;&nbsp; 2 – 3 sedikit nyeri</div>
                <div>c. &nbsp;&nbsp; 4 – 5 cukup nyeri</div>
                <div>d. &nbsp;&nbsp; 6 – 7 lumayan nyeri</div>
                <div>e. &nbsp;&nbsp; 8 – 9 sangat nyeri</div>
                <div>
                  f. &nbsp;&nbsp;&nbsp; 10 amat sangat nyeri (tidak tertahankan)
                </div>
              </div>
            </div>
          </div>

          {/* Right column */}
          <div className='w-44 px-3 py-2 space-y-6 text-xs leading-snug'>
            <div>
              <div className='underline font-semibold mb-1'>Catatan :</div>
              <p>
                Tanya pasien tentang intensitas nyerinya yang dilambangkan
                dengan angka.
              </p>
            </div>
            <div>
              <div className='underline font-semibold mb-1'>Catatan :</div>
              <p>
                Pasien diminta untuk menunjuk / memilih gambar mana yang paling
                sesuai dengan yang ia rasakan.
              </p>
            </div>
          </div>
        </div>

        {/* Page number */}
        <div className='border-t border-black text-right px-3 py-1 text-xs'>
          1
        </div>
      </div>
    </div>
  )
}
