import { SimpleColumn } from '@/components/simple-column'
import { AsesmenPerawat } from '@/models/asesmen-rajal'

const TablePengkajianResikoJatuhRajal = ({
  title,
  data,
}: {
  title?: string
  data: AsesmenPerawat
}) => {
  return (
    <div className='mb-2'>
      {/* Table */}
      <p className='text-xs font-semibold'>{title ?? ''}</p>
      {/* Header */}
      <div className='flex mt-4'>
        <SimpleColumn name='No' className='border-b-0 text-xs w-[50px]' />
        <SimpleColumn
          name='Penilaian / Pengkajian'
          className='border-b-0 text-xs flex-1'
        />
        <SimpleColumn name='YA' className='border-b-0 text-xs flex-1' />
        <SimpleColumn
          name='TIDAK'
          className='border-b-0 text-xs flex-1'
          isLast
        />
      </div>
      {/* Header */}

      {/* Body */}
      <div className='border-b-[1px] border-black'>
        <Item
          n1='a.'
          n2={`Cara berjalan pasien (salah satu atau lebih)\n1. Tidak seimbang / sempoyongan / limbung\n2. Jalan dengan menggunakan alat bantu (tongkat, tripot, kursi roda,orang lain.)`}
          n3={data.aseskep_rj1 == 'true' ? '✓' : ''}
          n4={data.aseskep_rj1 == 'false' ? '✓' : ''}
        />
        <Item
          n1='b.'
          n2={`Menopang saat akan duduk: tampak memegang pinggiran Kursi atau Meja / benda lain sebagai penopang saat akan duduk`}
          n3={data.aseskep_rj2 == 'true' ? '✓' : ''}
          n4={data.aseskep_rj2 == 'false' ? '✓' : ''}
        />
      </div>
      {/* Body */}
    </div>
  )
}

export default TablePengkajianResikoJatuhRajal

const Item = ({
  n1,
  n2,
  n3,
  n4,
}: {
  n1?: string
  n2?: string
  n3?: string
  n4?: string
}) => {
  return (
    <div className='flex boder border-b-black'>
      <SimpleColumn name={n1} className='border-b-0 text-xs w-[50px]' />
      <SimpleColumn name={n2} className='border-b-0 text-xs flex-1' />
      <SimpleColumn name={n3} className='border-b-0 text-xs flex-1' />
      <SimpleColumn isLast name={n4} className='border-b-0 text-xs flex-1' />
    </div>
  )
}
