import type { Response } from '@/type'

import { put } from './api-2'

export interface DoubleCheckHighAlert {
  insert_dttm: string
  id_double_check: number
  no_reg: string
  kd_bagian: string
  pasien_pemberi: boolean
  pasien_verify: boolean
  obat_pemberi: boolean
  obat_verify: boolean
  dosis_pemberi: boolean
  dosis_verify: boolean
  cara_pemberi: boolean
  cara_verify: boolean
  waktu_pemberi: boolean
  waktu_verify: boolean
  informasi_pemberi: boolean
  informasi_verify: boolean
  dokumentasi_pemberi: boolean
  dokumentasi_verify: boolean
  keterangan: string
  nama_obat: string
  kode_obat: string
  perawat_pemberi: string
  verify_nama: string
  user: {
    nama: string
  }
}

const getDoubleCheckHighAlert = async (
  no_reg: string,
): Promise<Response<DoubleCheckHighAlert[]>> => {
  const response = await put('/v1/double-check', { no_reg })

  return response.data
}

export { getDoubleCheckHighAlert }
