import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import Text from '@/components/text'
import { getReportAsesmenBayi } from '@/services/perinatologi'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportPerinatologiProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportPerinatologi({
  isReport = false,
  noreg = '',
  no,
}: ReportPerinatologiProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.perinatologi,
      noreg,
      pasien?.no_rm,
    ],
    queryFn: () =>
      getReportAsesmenBayi({
        no_reg: noreg,
        no_rm: pasien!.no_rm,
      }),
    enabled: !!noreg && !!pasien?.no_rm,
  })

  const res = data?.response

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || !res.asesmen_bayi) return <EmptyPlaceholder />

  const bayi = res.asesmen_bayi
  const vital = res.vital_sign
  const fisik = res.fisik

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          PENGKAJIAN AWAL KEPERAWATAN NEONATUS
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='IDENTITAS ORANG TUA' />
          <Text kStyle='min-w-[250px]' k='Nama Ayah' v={bayi.nama_ayah} />
          <Text
            kStyle='min-w-[250px]'
            k='Pekerjaan Ayah'
            v={bayi.pekerjaan_ayah}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Riwayat Penyakit Ayah'
            v={bayi.riwayat_penyakit_ayah}
          />
          <Text kStyle='min-w-[250px]' k='Nama Ibu' v={bayi.nama_ibu} />
          <Text
            kStyle='min-w-[250px]'
            k='Pekerjaan Ibu'
            v={bayi.pekerjaan_ibu}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Riwayat Penyakit Ibu'
            v={bayi.penyakit_ibu}
          />
          <Text kStyle='min-w-[250px]' k='Dokter Obgyn' v={bayi.dokter_obgyn} />
          <Text kStyle='min-w-[250px]' k='Dokter Anak' v={bayi.dokter_anak} />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='RIWAYAT KEHAMILAN' />
          <Text
            kStyle='min-w-[250px]'
            k='Usia Kehamilan'
            v={bayi.prenatal_usia_kehamilan || bayi.usia_kehamilan}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Komplikasi Antenatal'
            v={bayi.prenatal_komplikasi}
          />
          <Text kStyle='min-w-[250px]' k='HIS' v={bayi.prenatal_his} />
          <Text kStyle='min-w-[250px]' k='TTP' v={bayi.prenatal_ttp} />
          <Text kStyle='min-w-[250px]' k='Ketuban' v={bayi.prenatal_ketuban} />
          <Text kStyle='min-w-[250px]' k='Jam' v={bayi.prenatal_jam} />
          <Text
            kStyle='min-w-[250px]'
            k='Kebiasaan Ibu'
            v={bayi.prenatal_kebiasaan_ibu}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Riwayat Persalinan'
            v={bayi.prenatal_riwayat_persalinan}
          />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='KEADAAN BAYI SAAT LAHIR' />
          <Text kStyle='min-w-[250px]' k='Tanggal Lahir' v={bayi.tgl_lahir} />
          <Text
            kStyle='min-w-[250px]'
            k='Jenis Kelamin'
            v={bayi.jenis_kelamin}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Jenis Persalinan'
            v={bayi.natal_persalinan}
          />
          <Text kStyle='min-w-[250px]' k='KPD' v={bayi.natal_kpd} />
          <Text kStyle='min-w-[250px]' k='Keadaan' v={bayi.natal_keadaan} />
          <Text
            kStyle='min-w-[250px]'
            k='Tindakan Diberikan'
            v={bayi.natal_tindakan_diberikan}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Ditolong Oleh'
            v={bayi.natal_ditolong_oleh}
          />
          <Text kStyle='min-w-[250px]' k='Ketuban' v={bayi.natal_ketuban} />
          <Text kStyle='min-w-[250px]' k='Letak' v={bayi.natal_letak} />
          <Text
            kStyle='min-w-[250px]'
            k='Lahir Umur'
            v={bayi.natal_lahir_umur}
          />
          <Text kStyle='min-w-[250px]' k='Volume' v={bayi.natal_volume} />
          <Text
            kStyle='min-w-[250px]'
            k='Komplikasi'
            v={bayi.natal_komplikasi}
          />
          <Text kStyle='min-w-[250px]' k='Lahir Dengan' v={bayi.lahir_dengan} />
          <Text kStyle='min-w-[250px]' k='Menangis' v={bayi.menangis} />
          <Text kStyle='min-w-[250px]' k='Keterangan' v={bayi.keterangan} />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='TANDA VITAL' />
          <Text
            kStyle='min-w-[250px]'
            k='Vital Sign'
            v={`TD: ${vital.td} | HR: ${vital.hr} | RR: ${vital.rr} | SpO2: ${vital.spo2}`}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Antropometri'
            v={`BB: ${vital.bb} | TB: ${vital.tb} | LK: ${vital.lingkar_kepala} | LL: ${vital.lingkar_lengan} | LD: ${vital.lingkar_dada} | LP: ${vital.lingkar_perut}`}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Keadaan Umum'
            v={vital.keadaan_umum}
          />
          <Text kStyle='min-w-[250px]' k='Warna Kulit' v={vital.warna_kulit} />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='PEMERIKSAAN FISIK' />
          <Text
            kStyle='min-w-[250px]'
            k='GCS'
            v={`E:${fisik.gcs_e} V:${fisik.gcs_v} M:${fisik.gcs_m}`}
          />
          <Text kStyle='min-w-[250px]' k='Kesadaran' v={fisik.kesadaran} />
          <Text kStyle='min-w-[250px]' k='Kepala' v={fisik.kepala} />
          <Text kStyle='min-w-[250px]' k='Tonick Neck' v={fisik.tonick_neck} />
          <Text kStyle='min-w-[250px]' k='Kelainan' v={fisik.kelainan} />
          <Text kStyle='min-w-[250px]' k='Wajah' v={fisik.wajah} />
          <Text kStyle='min-w-[250px]' k='Telinga' v={fisik.telinga} />
          <Text kStyle='min-w-[250px]' k='Hidung' v={fisik.hidung} />
          <Text kStyle='min-w-[250px]' k='Mulut' v={fisik.mulut} />
          <Text
            kStyle='min-w-[250px]'
            k='Leher & Bahu'
            v={fisik.leher_dah_bahu}
          />
          <Text kStyle='min-w-[250px]' k='Dada' v={fisik.dada} />
          <Text kStyle='min-w-[250px]' k='Abdomen' v={fisik.abdomen} />
          <Text kStyle='min-w-[250px]' k='Punggung' v={fisik.punggung} />
          <Text kStyle='min-w-[250px]' k='Integumen' v={fisik.integumen} />
          <Text kStyle='min-w-[250px]' k='Ekstremitas' v={fisik.ekstremitas} />
          <Text kStyle='min-w-[250px]' k='Genetalia' v={fisik.genetalia} />
          <Text kStyle='min-w-[250px]' k='Anus' v={fisik.anus} />
          <Text kStyle='min-w-[250px]' k='Babin Ski' v={fisik.babin_ski} />
          <Text
            kStyle='min-w-[250px]'
            k='Refleks Rooting'
            v={fisik.refleks_rooting}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Refleks Swallowing'
            v={fisik.refleks_swallowing}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Refleks Sucking'
            v={fisik.refleks_sucking}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Refleks Moro'
            v={fisik.refleks_moro}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Refleks Graps'
            v={fisik.refleks_graps}
          />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='APGAR SCORE' />
          <div className='flex mt-2'>
            <SimpleColumn name='Waktu' className='text-xs flex-1' />
            <SimpleColumn name='Jantung' className='text-xs flex-[0.7]' />
            <SimpleColumn name='Nafas' className='text-xs flex-[0.7]' />
            <SimpleColumn name='Otot' className='text-xs flex-[0.7]' />
            <SimpleColumn name='Refleksi' className='text-xs flex-[0.7]' />
            <SimpleColumn name='Warna Kulit' className='text-xs flex-[0.7]' />
            <SimpleColumn name='Total' className='text-xs flex-[0.6]' isLast />
          </div>
          {(res.apgar_score ?? []).length == 0 && <EmptyPlaceholder />}
          {(res.apgar_score ?? []).map((item, index) => (
            <div className='flex' key={item.id ?? index}>
              <SimpleColumn
                name={item.waktu || '-'}
                className='text-xs flex-1'
              />
              <SimpleColumn
                name={`${item.jantung ?? '-'}`}
                className='text-xs flex-[0.7]'
              />
              <SimpleColumn
                name={`${item.nafas ?? '-'}`}
                className='text-xs flex-[0.7]'
              />
              <SimpleColumn
                name={`${item.otot ?? '-'}`}
                className='text-xs flex-[0.7]'
              />
              <SimpleColumn
                name={`${item.refleksi ?? '-'}`}
                className='text-xs flex-[0.7]'
              />
              <SimpleColumn
                name={`${item.warna_kulit ?? '-'}`}
                className='text-xs flex-[0.7]'
              />
              <SimpleColumn
                name={`${item.total ?? '-'}`}
                className='text-xs flex-[0.6]'
                isLast
              />
            </div>
          ))}
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='RIWAYAT KELAHIRAN YANG LALU' />
          <div className='flex mt-2'>
            <SimpleColumn name='Tahun' className='text-xs flex-[0.7]' />
            <SimpleColumn name='Tempat' className='text-xs flex-1' />
            <SimpleColumn name='Umur Kehamilan' className='text-xs flex-1' />
            <SimpleColumn name='Jenis Persalinan' className='text-xs flex-1' />
            <SimpleColumn name='Penolong' className='text-xs flex-1' />
            <SimpleColumn name='Penyulit' className='text-xs flex-1' />
            <SimpleColumn name='JK' className='text-xs flex-[0.5]' />
            <SimpleColumn name='BB' className='text-xs flex-[0.6]' />
            <SimpleColumn name='Keadaan' className='text-xs flex-1' isLast />
          </div>
          {(res.riwayat_kelahiran ?? []).length == 0 && <EmptyPlaceholder />}
          {(res.riwayat_kelahiran ?? []).map((item, index) => (
            <div className='flex' key={item.kd_riwayat ?? index}>
              <SimpleColumn
                name={item.tahun_persalinan || '-'}
                className='text-xs flex-[0.7]'
              />
              <SimpleColumn
                name={item.tempat_persalinan || '-'}
                className='text-xs flex-1'
              />
              <SimpleColumn
                name={item.umur_kehamilan || '-'}
                className='text-xs flex-1'
              />
              <SimpleColumn
                name={item.jenis_persalinan || '-'}
                className='text-xs flex-1'
              />
              <SimpleColumn
                name={item.penolong || '-'}
                className='text-xs flex-1'
              />
              <SimpleColumn
                name={item.penyulit || '-'}
                className='text-xs flex-1'
              />
              <SimpleColumn
                name={item.jk || '-'}
                className='text-xs flex-[0.5]'
              />
              <SimpleColumn
                name={item.bb || '-'}
                className='text-xs flex-[0.6]'
              />
              <SimpleColumn
                name={item.keadaan_sekarang || '-'}
                className='text-xs flex-1'
                isLast
              />
            </div>
          ))}
        </div>

        <div className='flex justify-end mt-4'>
          <div className='text-center text-xs'>
            <p>Perawat Yang Memeriksa</p>
            <div className='h-16' />
            <p>{res.karyawan?.nama || '-'}</p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
