import { cn } from '@/lib/utils'

const Text = ({
  k = '',
  v = '',
  kStyle,
  vStyle,
  isHeader = false,
}: {
  k?: string
  v?: string
  kStyle?: string
  vStyle?: string
  isHeader?: boolean
}) => {
  if (isHeader) {
    return <p className={cn('text-xs font-bold', kStyle)}>{k || v}</p>
  }

  return (
    <div className='flex items-center gap-4'>
      <p className={cn('min-w-[200px] text-xs', kStyle)}>{k}</p>
      <p className={cn('text-xs', vStyle)}>
        {k == '' ? '' : ':'} {v}
      </p>
    </div>
  )
}
export default Text
