import React from 'react'

/**
 * Interface untuk struktur data Skala Nyeri Fisik
 * Berdasarkan sumber data JSON yang Anda berikan
 */
interface FisikSkalaData {
  postur_tubuh?: string
  pola_tidur?: string
  ekspresi_wajah?: string
  tangisa?: string // Sesuai key: "tangisa"
  warna?: string
  respirasi?: string
  denyut_jantung?: string
  saurasi_oksigen?: string // Sesuai key: "saurasi_oksigen"
  tekanan_darah?: string
  perepsi_perawat?: string // Sesuai key: "perepsi_perawat"
  total?: number
}

interface FisikSkalaProps {
  data: FisikSkalaData
}

const FisikSkalaTable: React.FC<FisikSkalaProps> = ({ data }) => {
  // Helper untuk merender baris tabel dengan border hitam tegas
  const Row = ({
    label,
    value,
  }: {
    label: string
    value?: string | number
  }) => (
    <tr className='border-b border-black last:border-b-0'>
      <td className='border-r border-black p-2 w-1/3 font-medium text-[11px] md:text-xs leading-tight'>
        {label}
      </td>
      <td className='p-2 text-[11px] md:text-xs leading-relaxed whitespace-pre-wrap'>
        {value || '-'}
      </td>
    </tr>
  )

  return (
    <div className='w-full border border-black bg-white overflow-hidden shadow-sm mb-10'>
      <table className='w-full border-collapse'>
        <thead>
          {/* Header Hitam/Putih sesuai Screenshot 2026-05-05 at 12.00.41.png */}
          <tr className='bg-white border-b border-black text-xs md:text-sm font-bold uppercase'>
            <th className='border-r border-black p-3 w-1/3 text-center tracking-[0.2em]'>
              FISIK
            </th>
            <th className='p-3 text-center tracking-[0.2em]'>SKALA</th>
          </tr>
        </thead>
        <tbody>
          <Row label='Postur Tubuh/Tonus Otot' value={data.postur_tubuh} />
          <Row label='Pola Tidur' value={data.pola_tidur} />
          <Row label='Ekspresi Wajah' value={data.ekspresi_wajah} />
          <Row label='Tangisan' value={data.tangisa} />
          <Row label='Warna' value={data.warna} />
          <Row label='Respirasi' value={data.respirasi} />
          <Row label='Denyut Jantung' value={data.denyut_jantung} />
          <Row label='Saturasi Jantung' value={data.saurasi_oksigen} />
          <Row label='Tekanan Darah' value={data.tekanan_darah} />
          <Row label='Persepsi Perawat' value={data.perepsi_perawat} />

          {/* Baris TOTAL sesuai Screenshot 2026-05-05 at 11.46.38.png */}
          <tr className='border-t border-black font-bold uppercase text-xs md:text-sm'>
            <td className='border-r border-black p-3 bg-gray-50'>TOTAL</td>
            <td className='p-3 bg-gray-50 text-base md:text-lg'>
              {data.total ?? 0}
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  )
}

export default FisikSkalaTable
