import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import Text from '@/components/text'
import { getRekonsiliasiObatAdmisi } from '@/services/rekonsiliasi-obat'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportRekonsiliasiObatAdmisiProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

function joinNames(items: { nama: string }[] | undefined) {
  return (items ?? [])
    .map((item) => item.nama)
    .filter(Boolean)
    .join(', ')
}

export default function ReportRekonsiliasiObatAdmisi({
  isReport = false,
  noreg = '',
  no,
}: ReportRekonsiliasiObatAdmisiProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.rekonsiliasiObat, noreg],
    queryFn: () => getRekonsiliasiObatAdmisi(noreg),
    enabled: !!noreg,
  })

  const res = data?.response

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return <EmptyPlaceholder />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          REKONSILIASI OBAT SAAT PASIEN MASUK
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='border border-black my-2 p-2'>
          <Text
            kStyle='min-w-[250px]'
            k='Riwayat Penyakit'
            v={joinNames(res.riwayat_penyakit) || '-'}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Riwayat Pengobatan Terdahulu'
            v={joinNames(res.riwayat_pengobatan_terdahulu) || '-'}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Alergi Obat'
            v={joinNames(res.alergi_obat) || '-'}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Manifestasi Alergi'
            v={joinNames(res.manafestasi_alergi) || '-'}
          />
          <Text kStyle='min-w-[250px]' k='Dampak' v={res.dampak || '-'} />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='DAFTAR OBAT SAAT MASUK' />
          <div className='flex mt-2'>
            <SimpleColumn name='No' className='text-xs flex-[0.3]' />
            <SimpleColumn name='Nama Obat' className='text-xs flex-[1.5]' />
            <SimpleColumn name='Dosis' className='text-xs flex-[0.8]' />
            <SimpleColumn name='Aturan Pakai' className='text-xs flex-1' />
            <SimpleColumn name='Cara Pemberian' className='text-xs flex-1' />
            <SimpleColumn
              name='Waktu Pemberian Terakhir'
              className='text-xs flex-1'
            />
            <SimpleColumn name='Tindak Lanjut' className='text-xs flex-1' />
            <SimpleColumn
              name='Perubahan Aturan Pakai'
              className='text-xs flex-1'
              isLast
            />
          </div>

          {(res.rekonsiliasi_obat_data ?? []).length == 0 && (
            <EmptyPlaceholder />
          )}

          {(res.rekonsiliasi_obat_data ?? []).map((item, index) => (
            <div className='flex' key={item.id ?? index}>
              <SimpleColumn
                name={`${index + 1}`}
                className='text-xs flex-[0.3]'
              />
              <SimpleColumn
                name={item.nama_obat || '-'}
                className='text-xs flex-[1.5]'
              />
              <SimpleColumn
                name={item.dosis || '-'}
                className='text-xs flex-[0.8]'
              />
              <SimpleColumn
                name={item.aturan_pakai || '-'}
                className='text-xs flex-1'
              />
              <SimpleColumn
                name={item.cara_pemberian || '-'}
                className='text-xs flex-1'
              />
              <SimpleColumn
                name={item.waktu_pemberian_terakhir || '-'}
                className='text-xs flex-1'
              />
              <SimpleColumn
                name={item.tindak_lanjut || '-'}
                className='text-xs flex-1'
              />
              <SimpleColumn
                name={item.perubahan_aturan_pakai || '-'}
                className='text-xs flex-1'
                isLast
              />
            </div>
          ))}
        </div>

        <div className='grid grid-cols-3 gap-2 mt-4'>
          <div className='text-center'>
            <Text isHeader k='Dokter DPJP' />
            <div className='h-14' />
            <p>{res.nama_dpjp || '-'}</p>
          </div>
          <div className='text-center'>
            <Text isHeader k='Perawat' />
            <div className='h-14' />
            <p>{res.nama_perawat || '-'}</p>
          </div>
          <div className='text-center'>
            <Text isHeader k='Apoteker' />
            <div className='h-14' />
            <p>{res.nama_apoteker || '-'}</p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
