import { Edukasi } from '@/features/pasien/edukasi-terintegrasi/edukasi'
import {
  AddEdukasiTerintegrasiReq,
  UpdateEdukasiTerintegrasiReq,
} from '@/hooks/edukasi-terintegrasi'
import type { EdukasiTerintegrasi, Response } from '@/type'

import { get, post, put } from './api'
import { get as getV2, post as postV2 } from './api-2'

const getData = async (
  no_rm: string,
): Promise<Response<EdukasiTerintegrasi[]>> => {
  const response = await get(`/v1/edukasi-terintegrasi/${no_rm}`)

  return response.data
}

const getDataEdukasi = async (noreg: string): Promise<Response<Edukasi>> => {
  const response = await getV2(`/v4/edukasi-terintegrasi-noreg/${noreg}`)
  return response.data
}

const postDataEdukasi = async (noreg: string): Promise<Response<Edukasi>> => {
  const response = await postV2(`/v1/edukasi-terintegrasi`, {
    no_reg: noreg,
  })
  return response.data
}

const saveEt = async (
  data: AddEdukasiTerintegrasiReq,
): Promise<Response<unknown>> => {
  const response = await post(`/v1/edukasi-terintegrasi`, data)

  return response.data
}

const updateEt = async (
  data: UpdateEdukasiTerintegrasiReq,
): Promise<Response<unknown>> => {
  const response = await put(`/v1/edukasi-terintegrasi`, data)

  return response.data
}

export { getData, saveEt, updateEt, getDataEdukasi, postDataEdukasi }
