import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatTanggalISO } from '@/utils/date_helper'

import { getMonitoringTransfusi } from './monitoring'

interface MonitoringInformasiProps {
  isReport?: boolean
  noreg?: string
}

const MonitoringTransfusiDarahReport = ({
  isReport = true,
  noreg = '',
}: MonitoringInformasiProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.monitorDarah, noreg],
    queryFn: () => getMonitoringTransfusi({ noreg }),
  })

  const res = data?.response != null ? data.response : null
  console.log(res)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0) return <EmptyPlaceholder />

  return (
    <LayoutBorderNo>
      {isReport && <ReportHeader />}

      <div className='p-4'>
        <h1 className='text-center text-black font-semibold mb-1'>
          INFORMASI TINDAKAN TRANSFUSI DARAH
        </h1>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        {/* Form — renders with empty defaults when res is null */}

        <div className='flex text-xs'>
          <SimpleColumn head name='No.' className='w-[100px]' />
          <SimpleColumn head name='TANGGAL' className='flex-[0.5]' />
          <SimpleColumn head name='JENIS DARAH' className='flex-[1]' />
          <SimpleColumn head name='NO. KANTONG' className='flex-[0.5]' />
          <SimpleColumn head name='REAKSI' className='flex-[0.5]' />
          <SimpleColumn head name='ISI' className='flex-[0.5]' />
          <SimpleColumn head name='TD' className='flex-[0.5]' />
          <SimpleColumn head name='NADI' className='flex-[0.5]' />
          <SimpleColumn head name='RR' className='flex-[0.5]' />
          <SimpleColumn head name='TEMP' className='flex-[0.5]' />
          <SimpleColumn
            head
            name='NAMA PERAWAT/BIDAN'
            className='flex-[0.5]'
            isLast
          />
        </div>

        <div className='mb-2'>
          {res!.map((item, index) => (
            <div key={index} className='flex'>
              <SimpleColumn
                name={`${index + 1}`}
                className='text-xs w-[100px]'
              />

              <SimpleColumn
                name={`${formatTanggalISO(item.insert_dttm)}`}
                className='flex-[0.5]'
              />
              <SimpleColumn name={`${item.jenis_darah}`} className='flex-[1]' />
              <SimpleColumn
                name={`${item.no_kantung}`}
                className='flex-[0.5]'
              />
              {/* <SimpleColumn name={`${item.reaksi}`} className='flex-[0.5]' />
               */}

              <div className='flex flex-col gap-2 text-left last:border-b-0 justify-center items-center p-2 border-y border-black border-l flex-[0.5]'>
                {item.reaksi?.map((e, index) => (
                  <div key={index}>
                    {e.reaksi} : {e.keterangan}
                  </div>
                ))}
              </div>
              <SimpleColumn name={`${item.isi}`} className='flex-[0.5]' />
              <SimpleColumn name={`${item.td}`} className='flex-[0.5]' />
              <SimpleColumn name={`${item.nadi}`} className='flex-[0.5]' />
              <SimpleColumn name={`${item.rr}`} className='flex-[0.5]' />
              <SimpleColumn name={`${item.temp}`} className='flex-[0.5]' />
              <SimpleColumn
                hasQR
                name={`${item.perawat.nama}`}
                className='flex-[0.5]'
                isLast
              />
            </div>
          ))}
        </div>

        <div className='mt-0' />
      </div>
    </LayoutBorderNo>
  )
}

export default MonitoringTransfusiDarahReport
