interface ReportSurveilansInfeksiFullProps {
  data: SurveilansInfeksiData
}

const sectionTitle = 'mt-3 border-b border-black pb-1 text-[13px]'
const subTitle = 'mt-2 text-[12px]'

function signatureUrl(ttd: string) {
  if (!ttd) return undefined
  const base = import.meta.env.VITE_BASE_API_URL_RME ?? ''
  return `${base}/app/images/surveilans_infeksi/${ttd}`
}

