import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import Text from '@/components/text'
import { DiagnosaTable } from '@/features/pasien-pulang/rekam-medis/components/diagnosa-table'
import { LaborTable } from '@/features/pasien-pulang/rekam-medis/components/labor-table'
import { RadiologiTable } from '@/features/pasien-pulang/rekam-medis/components/radiologi-table'
import { getPengkajianRawatInapAnak } from '@/services/pengkajian-rawat-inap-anak'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDateTime } from '@/utils/formatDate'

interface ReportPengkajianRawatInapAnakProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportPengkajianRawatInapAnak({
  isReport = false,
  noreg = '',
  no,
}: ReportPengkajianRawatInapAnakProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.pengkajianRawatInapAnak,
      noreg,
      pasien?.no_rm,
      pasien?.bagian,
      pasien?.pelayanan,
    ],
    queryFn: () =>
      getPengkajianRawatInapAnak({
        no_reg: noreg,
        no_rm: pasien!.no_rm,
        kategori: 'ANAK',
        bagian: pasien!.bagian,
        pelayanan: pasien!.pelayanan,
      }),
    enabled: !!noreg && !!pasien?.no_rm,
  })

  const res = data?.response

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || !res.asesmen) return <EmptyPlaceholder />

  const alergiMakanan = res.alergi
    ?.filter((item) => item.Kelompok?.toLowerCase() == 'makanan')
    .map((item) => item.Alergi)
    .filter(Boolean)
    .join(', ')

  const alergiObat = res.alergi
    ?.filter((item) => item.Kelompok?.toLowerCase() == 'obat')
    .map((item) => item.Alergi)
    .filter(Boolean)
    .join(', ')

  const alergiLain = res.alergi
    ?.filter((item) => item.Kelompok?.toLowerCase() == 'lain')
    .map((item) => item.Alergi)
    .filter(Boolean)
    .join(', ')

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          PENGKAJIAN AWAL MEDIS PASIEN RAWAT INAP ANAK
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='border border-black my-2 p-2'>
          <Text
            kStyle='min-w-[250px]'
            k='Tanggal Masuk'
            v={formatDateTime(res.asesmen.tanggal_masuk)}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Jam Masuk'
            v={res.asesmen.jam_masuk}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Keluhan Utama'
            v={res.asesmen.keluhan_utama}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Anamnesis'
            v={res.asesmen.anamnesis}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Riwayat Penyakit Terdahulu'
            v={res.asesmen.penyakit_dahulu}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Riwayat Penyakit Keluarga'
            v={res.asesmen.riwayat_penyakit_keluarga}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Riwayat Alergi'
            v={`Makanan: ${alergiMakanan || '-'} | Obat: ${
              alergiObat || '-'
            } | Lainnya: ${alergiLain || '-'}`}
          />
          <Text kStyle='min-w-[250px]' k='Telaah' v={res.asesmen.telaah} />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='PEMERIKSAAN FISIK & VITAL SIGN' />
          <Text
            kStyle='min-w-[250px]'
            k='Keadaan Umum'
            v={res.vital_sign.keadaan_umum}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Kesadaran'
            v={res.vital_sign.kesadaran}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Vital Sign'
            v={`TD: ${res.vital_sign.td} | Nadi: ${res.vital_sign.nadi} | RR: ${res.vital_sign.rr} | Suhu: ${res.vital_sign.suhu} | TB: ${res.vital_sign.tb} | BB: ${res.vital_sign.bb}`}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Kepala'
            v={res.pemeriksaan_fisik.kepala}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Mata'
            v={res.pemeriksaan_fisik.mata}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Mulut'
            v={res.pemeriksaan_fisik.mulut}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Gigi'
            v={res.pemeriksaan_fisik.gigi}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Leher'
            v={res.pemeriksaan_fisik.leher}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Kelenjar Getah Bening'
            v={res.pemeriksaan_fisik.getah_bening}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Paru'
            v={res.pemeriksaan_fisik.paru}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Jantung'
            v={res.pemeriksaan_fisik.jantung}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Dinding Dada'
            v={res.pemeriksaan_fisik.dinding_dada}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Abdomen'
            v={res.pemeriksaan_fisik.abdomen}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Hepar'
            v={res.pemeriksaan_fisik.hepar}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Limpa'
            v={res.pemeriksaan_fisik.limpa}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Ginjal'
            v={res.pemeriksaan_fisik.ginjal}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Genetalia'
            v={res.pemeriksaan_fisik.genetalia}
          />
          <Text kStyle='min-w-[250px]' k='OUF' v={res.pemeriksaan_fisik.ouf} />
          <Text
            kStyle='min-w-[250px]'
            k='Ekstremitas Atas'
            v={res.pemeriksaan_fisik.ekstremitas_atas}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Ekstremitas Bawah'
            v={res.pemeriksaan_fisik.ekstremitas_bawah}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Tugor Kulit'
            v={res.pemeriksaan_fisik.tugor_kulit}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Punggung'
            v={res.pemeriksaan_fisik.punggung}
          />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='DIAGNOSA' />
          <DiagnosaTable data={res.diagnosa ?? []} />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='PEMERIKSAAN LABORATORIUM' />
          <LaborTable data={res.labor ?? []} />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text isHeader k='PEMERIKSAAN RADIOLOGI' />
          <RadiologiTable data={res.radiologi ?? []} />
        </div>

        <div className='border border-black my-2 p-2'>
          <Text kStyle='min-w-[250px]' k='Terapi' v={res.asesmen.terapi} />
          <Text
            kStyle='min-w-[250px]'
            k='Prognosis'
            v={res.asesmen.prognosis}
          />
        </div>

        <div className='flex justify-end mt-4'>
          <div className='text-center text-xs'>
            <p>Dokter Yang Memeriksa</p>
            <div className='h-16' />
            <p>{res.asesmen.nama_dokter || '-'}</p>
            <p>{formatDateTime(res.asesmen.tanggal_asesmen)}</p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
