import { SimpleColumn } from '@/components/simple-column'
import type { Asuhan } from '@/models/asesmen-awal-keperawatan-igd.model'

const TableMasalahkeperawatan = ({ data }: { data: Asuhan[] }) => {
  return (
    <div>
      {/* Header */}
      <div className='flex mt-4'>
        <SimpleColumn name='No' className='border-b-0 text-xs w-[50px]' />
        <SimpleColumn
          name='Diagnosa Keperawatan'
          className='border-b-0 text-xs flex-1'
        />
        <SimpleColumn
          name='Tindakan Keperawatan Dan Kolaborasi'
          className='border-b-0 text-xs flex-1'
          isLast
        />
      </div>
      {/* Header */}

      {/* Body */}
      <div className='border-b-[1px] border-black'>
        {data.length == 0 && (
          <div className='border border-black border-b-0 p-2'>
            <p className='text-xs text-center'>Tidak ada asuhan.</p>
          </div>
        )}

        {data.map((item, index) => (
          <Item
            key={item.tanggal}
            n1={`${index + 1}.`}
            n2={item.diagnosa.judul}
            n3={
              <div className='text-left'>
                <h3 className='font-semibold mt-1'>TINDAKAN</h3>
                {item.implementasi.map((i) => (
                  <div key={i.id}>
                    <p>{i.deskripsi}</p>
                    <p>Pelaksana :{i.user.nama}</p>
                  </div>
                ))}
                <h3 className='font-semibold mt-1'>INTERVENSI KEPERAWATAN</h3>
                {item.deskripsi_siki.map((i) => (
                  <div key={i.id_siki}>
                    <p>{i.nama_siki}</p>
                  </div>
                ))}
                <h3 className='font-semibold mt-1'>MASALAH KEPERAWATAN</h3>
                {item.deskripsi_slki.map((i) => (
                  <div key={i.id_kriteria}>
                    <p>{i.nama_sllki}</p>
                  </div>
                ))}
              </div>
            }
          />
        ))}
      </div>
      {/* Body */}
    </div>
  )
}

export default TableMasalahkeperawatan

const Item = ({
  n1,
  n2,
  n3,
}: {
  n1?: string
  n2?: string
  n3?: React.ReactNode
}) => {
  return (
    <div className='flex boder border-b-black'>
      <SimpleColumn
        name={n1}
        className='justify-start items-start border-b-0 text-xs w-[50px]'
      />
      <SimpleColumn
        name={n2}
        className='justify-start items-start border-b-0 text-xs flex-1'
      />
      <SimpleColumn
        isChild={n3}
        isLast
        className='border-b-0 text-xs flex-1 items-start justify-start'
      />
    </div>
  )
}
