import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import {
  INIT_RES_PEMBERIAN_TERAPI_CAIRAN,
  getDaftarPemberianTerapiCairan,
} from '@/services/daftar-pemberian-terapi-cairan'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate, formatTime } from '@/utils/formatDate'

interface ReportDaftarPemberianTerapiCairanProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportDaftarPemberianTerapiCairan({
  isReport = false,
  noreg = '',
  no,
}: ReportDaftarPemberianTerapiCairanProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.terapiCairan, noreg],
    queryFn: () => getDaftarPemberianTerapiCairan(noreg, pasien!.no_rm),
    enabled: !!noreg,
  })

  const res =
    data?.response != null ? data.response : INIT_RES_PEMBERIAN_TERAPI_CAIRAN

  const cairan = res.cairan ?? []

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          DAFTAR PEMBERIAN TERAPI CAIRAN / INFUS
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='flex mt-4'>
          <SimpleColumn name='No' className='text-xs flex-[0.35]' />
          <SimpleColumn name='Tanggal' className='text-xs flex-1' />
          <SimpleColumn name='Jam' className='text-xs flex-[0.6]' />
          <SimpleColumn
            name='Nama Cairan / Infus'
            className='text-xs flex-[1.5]'
          />
          <SimpleColumn name='Jumlah CC' className='text-xs flex-[0.7]' />
          <SimpleColumn name='Dosis Makro' className='text-xs flex-[0.7]' />
          <SimpleColumn name='Dosis Mikro' className='text-xs flex-[0.7]' />
          <SimpleColumn name='Fls Ke' className='text-xs flex-[0.5]' />
          <SimpleColumn
            name='Obat Ditambahkan'
            className='text-xs flex-[1.5]'
          />
          <SimpleColumn name='Sisa Infus' className='text-xs flex-[0.7]' />
          <SimpleColumn name='Perawat' className='text-xs flex-1' />
          <SimpleColumn name='Keterangan' className='text-xs flex-1' isLast />
        </div>

        {cairan.length == 0 && <EmptyPlaceholder />}

        {cairan.map((item, index) => (
          <div className='flex' key={index}>
            <SimpleColumn
              name={`${index + 1}`}
              className='text-xs flex-[0.35]'
            />
            <SimpleColumn
              name={formatDate(item.insert_dttm)}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={formatTime(item.insert_dttm)}
              className='text-xs flex-[0.6]'
            />
            <SimpleColumn
              name={item.nama_cairan || '-'}
              className='text-xs flex-[1.5]'
            />
            <SimpleColumn
              name={item.jumlah_infuse || '-'}
              className='text-xs flex-[0.7]'
            />
            <SimpleColumn
              name={item.dosis_makro || '-'}
              className='text-xs flex-[0.7]'
            />
            <SimpleColumn
              name={item.dosis_mikro || '-'}
              className='text-xs flex-[0.7]'
            />
            <SimpleColumn
              name={`${item.fls_ke ?? '-'}`}
              className='text-xs flex-[0.5]'
            />
            <SimpleColumn
              name={item.obat_ditambahkan || '-'}
              className='text-xs flex-[1.5]'
            />
            <SimpleColumn
              name={item.sisa_infuse || '-'}
              className='text-xs flex-[0.7]'
            />
            <SimpleColumn
              name={item.perawat?.nama || '-'}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={item.keterangan || '-'}
              className='text-xs flex-1'
              isLast
            />
          </div>
        ))}
      </div>
    </LayoutBorderNo>
  )
}
