import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { MonitoringCairanModel } from '@/models/monitoring-cairan.model'
import { getBalanceCairan } from '@/services/monitoring-cairan'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportMonitoringBalanceCairanProps {
  isReport?: boolean
  noreg?: string
  norm?: string
  no?: string
}

const init: MonitoringCairanModel[] = []

const ReportMonitoringBalanceCairan = ({
  isReport,
  noreg,
  no,
}: ReportMonitoringBalanceCairanProps) => {
  const { pasien } = usePasienStore((state) => state)
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.balanceCairan, noreg!],
    queryFn: () => getBalanceCairan({ no_reg: noreg! }),
    enabled: !!noreg,
  })

  const res = data?.response ?? init

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res.length == 0) return <EmptyPlaceholder />

  return (
    <LayoutBorderNo no={no}>
      {' '}
      {isReport && <ReportHeader />}
      <header className='text-center text-black font-semibold my-4'>
        BALANCE CAIRAN
      </header>
      {/* Informasi Pasien */}
      {pasien != null && (
        <InformasiPasien
          nama={pasien.nama_pasien}
          noRM={pasien.no_rm}
          tanggalLahir={pasien.tgl_lahir}
          jk={pasien.jenis_kelamin}
        />
      )}
      <div className='flex'>
        <div className='w-[200px]'>
          <div className='h-[100px] p-2 border border-black'>
            <p className='text-xs text-center font-medium'>TANGGAL/ JAM</p>
          </div>
        </div>
        <div className='w-[200px]'>
          <div className='h-[100px] p-2 border border-black border-b-0 border-l-0'>
            <p className='text-xs text-center'></p>
          </div>
        </div>

        <div className={`${isReport ? 'w-full' : 'w-[600px]'} overflow-x-auto`}>
          <div className='flex min-w-max'>
            {res.map((item, idx) => (
              <div key={idx} className='w-[60px]'>
                <div className='h-[100px] p-2 border border-black border-b-0 border-l-0'>
                  <p className='text-xs text-center'>{item.intake.tanggal}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
      <div className='flex'>
        <div className='w-[200px]'>
          <div className='h-[132px] p-2 border border-black'>
            <p className='text-xs text-center font-medium'>MASUK</p>
          </div>
        </div>
        <div className='w-[200px]'>
          <div className='p-2 border border-black border-b-0 border-l-0'>
            <p className='text-xs text-center'>Peroral/NGT</p>
          </div>
          <div className='p-2 border border-black border-b-0 border-l-0'>
            <p className='text-xs text-center'>Parerental/Transfusi</p>
          </div>
          <div className='p-2 border border-black border-b-0 border-l-0'>
            <p className='text-xs text-center'>Minum</p>
          </div>
          <div className='p-2 border border-black border-l-0'>
            <p className='text-xs text-center'>Jumlah</p>
          </div>
        </div>

        <div className={`${isReport ? 'w-full' : 'w-[600px]'} overflow-x-auto`}>
          <div className='flex min-w-max'>
            {res.map((item, idx) => (
              <div key={idx} className='w-[60px]'>
                <div className='p-2 border border-black border-b-0 border-l-0'>
                  <p className='text-xs text-center'>{item.intake.ngt}</p>
                </div>
                <div className='p-2 border border-black border-b-0 border-l-0'>
                  <p className='text-xs text-center'>{item.intake.infuse}</p>
                </div>
                <div className='p-2 border border-black border-b-0 border-l-0'>
                  <p className='text-xs text-center'>{item.intake.minum}</p>
                </div>
                <div className='p-2 border border-black border-l-0'>
                  <p className='text-xs text-center'>{item.intake.total}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
      <div className='flex'>
        <div className='w-[200px]'>
          <div className='h-[200px] p-2 border border-black border-t-0'>
            <p className='text-xs text-center font-medium'>KELUAR</p>
          </div>
        </div>
        <div className='w-[200px]'>
          <div className='p-2 border border-black border-b-0 border-t-0 border-l-0'>
            <p className='text-xs text-center font-medium'>Feses</p>
          </div>
          <div className='p-2 border border-black border-b-0 border-l-0'>
            <p className='text-xs text-center font-medium'>Urine</p>
          </div>
          <div className='p-2 border border-black border-b-0 border-l-0'>
            <p className='text-xs text-center font-medium'>Muntah/NGT</p>
          </div>
          <div className='p-2 border border-black border-l-0 border-b-0'>
            <p className='text-xs text-center font-medium'>Drain/Darah</p>
          </div>
          <div className='p-2 border border-black border-l-0 border-b-0'>
            <p className='text-xs text-center font-medium'>IWL</p>
          </div>
          <div className='p-2 border border-black border-l-0'>
            <p className='text-xs text-center font-medium'>Jumlah</p>
          </div>
        </div>

        <div className={`${isReport ? 'w-full' : 'w-[600px]'} overflow-x-auto`}>
          <div className='flex min-w-max'>
            {res.map((item, idx) => (
              <div key={idx} className='w-[60px]'>
                <div className='p-2 border border-black border-b-0 border-l-0'>
                  <p className='text-xs text-center'>{item.output.feses}</p>
                </div>
                <div className='p-2 border border-black border-b-0 border-l-0'>
                  <p className='text-xs text-center'>{item.output.urine}</p>
                </div>
                <div className='p-2 border border-black border-b-0 border-l-0'>
                  <p className='text-xs text-center'>{item.output.ngt}</p>
                </div>
                <div className='p-2 border border-black border-l-0'>
                  <p className='text-xs text-center'>{item.output.drain}</p>
                </div>
                <div className='p-2 border border-black border-l-0'>
                  <p className='text-xs text-center'>{item.output.wsd}</p>
                </div>
                <div className='p-2 border border-black border-l-0'>
                  <p className='text-xs text-center'>{item.output.total}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
      <div className='flex'>
        <div className='w-[200px]'>
          <div className='p-2 border border-black border-t-0'>
            <p className='text-xs text-center font-medium'>BALANCE CAIRAN</p>
          </div>
        </div>
        <div className='w-[200px]'>
          <div className='p-2 border border-black border-t-0 border-l-0'>
            <p className='text-xs text-center font-medium text-white'>jumlah</p>
          </div>
        </div>
        <div className={`${isReport ? 'w-full' : 'w-[600px]'} overflow-x-auto`}>
          <div className='flex min-w-max'>
            {res.map((item, idx) => (
              <div key={idx} className='w-[60px]'>
                <div className='p-2 border border-black  border-l-0 border-t-0'>
                  <p className='text-xs text-center font-medium'>
                    {item.balance.total}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
export default ReportMonitoringBalanceCairan
