import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import Text from '@/components/text'
import { DiagnosaTable } from '@/features/pasien-pulang/rekam-medis/components/diagnosa-table'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import SignatureField from '../paps/singnature'
import { AlergiTable } from './component/alergi-table'
import EmptyDataGizi from './component/empty-data'
import { getReportAsuhanGizi } from './gizi_model'

interface ReportAsuhanGiziProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportAsuhanGizi({
  isReport = true,
  noreg = '',
}: ReportAsuhanGiziProps) {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.reportAsuhanGizi, noreg],
    queryFn: () => getReportAsuhanGizi({ noreg }),
    enabled: !!noreg,
  })
  const { pasien } = usePasienStore((state) => state)

  const res = data != null ? data.response : null

  console.log(res)

  if (isLoading) return <Loading />
  if (isError) return <Error />

  if (res == null) return <EmptyDataGizi />
  if (res?.tanggal == '') return <EmptyDataGizi />

  return (
    <>
      <LayoutBorderNo no={'no'}>
        {isReport && <ReportHeader />}
        <div className='p-2 text-xs'>
          {/* DATA */}
          <h1 className='text-center text-xl text-black font-semibold'>
            FORMULIR ASUHAN GIZI
          </h1>
        </div>

        <table className='w-full border-collapse  text-xs'>
          {pasien != null && (
            <InformasiPasien
              nama={pasien.nama_pasien}
              noRM={pasien.no_rm}
              tanggalLahir={pasien.tgl_lahir}
            />
          )}

          <tbody>
            <tr className='text-left pl-4 pr-3'>
              <td className='border-r  pl-4 pr-3 pt-2 pb-2 ml-4   w-1/4  text-left'>
                <h5 className='pb-2 pt-1'> Tanggal : {res?.tanggal}</h5>
                <h5 className='pb-2 pt-1'> DIAGNOSA MEDIS</h5>
                <DiagnosaTable data={res != null ? res.diagnosa : []} />
              </td>
            </tr>

            <tr className='text-left '>
              <div className='flex  p-4'>
                <SimpleColumn
                  head
                  name='ASESMEN GIZI'
                  className='w-full p-1'
                  className2='text-xs'
                  isLast
                />
              </div>
              <p className='w-full pl-4 text-left text-xs'>Anthropometric</p>
              <p className='w-full pl-4 text-left text-xs'>Umur {res?.umur}</p>
            </tr>
          </tbody>
        </table>

        <div className='mx-4 my-4 p-2 mb-1 '>
          <div className='flex items-start justify-items-start'>
            <div>
              <Text kStyle='min-w-[100px]' k='BB' v={res?.fisik_gizi.bb} />
              <Text kStyle='min-w-[100px]' k='TB' v={res?.fisik_gizi.tb} />
              <Text kStyle='min-w-[100px]' k='IMT' v={res?.fisik_gizi.imt} />
            </div>
            <div className='min-w-[100px]'></div>
            <div>
              <Text
                kStyle='min-w-[100px]'
                k='Lingkar Atas'
                v={res?.fisik_gizi.lla + ' cm'}
              />
              <Text
                kStyle='min-w-[100px]'
                k='Lingkar Lutut'
                v={res?.fisik_gizi.lt + ' cm'}
              />
            </div>
          </div>
        </div>

        <div className='flex pl-4 pr-4 '>
          <SimpleColumn
            head
            name='BIOKIMIA'
            className='w-full p-1'
            className2='text-xs'
            isLast
          />
        </div>

        <div className='flex  pb-4 pr-4 pl-4'>
          <SimpleColumn
            name={'\n' + res?.biokimia + '\n'}
            className2='text-xs'
            className='min-h-[50px] w-full'
            isLast
          />
        </div>

        <div className='flex pl-4 pr-4 '>
          <SimpleColumn
            head
            name='KLINIK/FISIK'
            className='w-full p-1'
            className2='text-xs'
            isLast
          />
        </div>

        <div className='flex  pb-4 pr-4 pl-4'>
          <SimpleColumn
            name={'\n' + res?.klinik_fisik + '\n'}
            className2='text-xs'
            className='min-h-[50px] w-full'
            isLast
          />
        </div>

        <div className='flex pl-4 pr-4 '>
          <SimpleColumn
            head
            name='RIWAYAT GIZI'
            className='w-full p-1'
            className2='text-xs'
            isLast
          />
        </div>

        <div className='flex  pb-4 pr-4 pl-4'>
          <div className='w-full'>
            <p className='text-xs p-3 '>Alergi Makanan</p>
            <AlergiTable data={res != null ? res.alergi_makan : []} />
          </div>
        </div>

        <div className='flex pl-4 pr-4 '>
          <SimpleColumn
            head
            name='POLA MAKAN'
            className='w-full p-1'
            className2='text-xs'
            isLast
          />
        </div>

        <div className='flex  pb-4 pr-4 pl-4'>
          <SimpleColumn
            name={'\n' + res?.pola_makan + '\n'}
            className2='text-xs'
            className='min-h-[50px] w-full'
            isLast
          />
        </div>

        <div className='flex pl-4 pr-4 '>
          <SimpleColumn
            head
            name='RIWAYAT PERSONAL'
            className='w-full p-1'
            className2='text-xs'
            isLast
          />
        </div>

        <div className='flex  pb-4 pr-4 pl-4'>
          <SimpleColumn
            name={'\n' + res?.riwayat_personal + '\n'}
            className2='text-xs'
            className='min-h-[50px] w-full'
            isLast
          />
        </div>

        <div className='flex pl-4 pr-4 '>
          <SimpleColumn
            head
            name='DIAGNOSA GIZI'
            className='w-full p-1'
            className2='text-xs'
            isLast
          />
        </div>

        <div className='flex  pb-4 pr-4 pl-4'>
          <SimpleColumn
            name={'\n' + res?.diagnosis_gizi + '\n'}
            className2='text-xs'
            className='min-h-[50px] w-full'
            isLast
          />
        </div>

        <div className='flex pl-4 pr-4 '>
          <SimpleColumn
            head
            name='INTERVENSI GIZI'
            className='w-full p-1'
            className2='text-xs'
            isLast
          />
        </div>

        <div className='flex  pb-4 pr-4 pl-4'>
          <SimpleColumn
            name={'\n' + res?.intervensi_gizi + '\n'}
            className2='text-xs'
            className='min-h-[50px] w-full'
            isLast
          />
        </div>

        <div className='flex pl-4 pr-4 '>
          <SimpleColumn
            head
            name='EVALUASI DAN MONITORING'
            className='w-full p-1'
            className2='text-xs'
            isLast
          />
        </div>

        <div className='flex  pb-4 pr-4 pl-4'>
          <SimpleColumn
            name={'\n' + res?.monitoring_evaluasi + '\n'}
            className2='text-xs'
            className='min-h-[50px] w-full'
            isLast
          />
        </div>

        <div className='flex justify-center text-sm'>
          <SignatureField
            title='Ahli Gizi'
            imageUrl={
              import.meta.env.VITE_BASE_API_URL_RME +
              '/app/images/asuhan_gizi/' +
              res?.ttd_ahli_gizi
            }
            name={res?.nama_ahli_gizi}
          />
        </div>
      </LayoutBorderNo>
    </>
  )
}
