import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import { getKartuObservasiIntensive } from '@/services/kartu-intensive'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

interface ReportKartuObservasiIntensiveProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportKartuObservasiIntensive({
  isReport = false,
  noreg = '',
  no,
}: ReportKartuObservasiIntensiveProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.kartuObservasiIntensive, noreg],
    queryFn: () => getKartuObservasiIntensive(noreg),
    enabled: !!noreg,
  })

  const res = data?.response ?? []

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          KARTU OBSERVASI INTENSIVE
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='flex mt-4'>
          <SimpleColumn name='Jam' className='text-xs flex-[0.5]' />
          <SimpleColumn name='T' className='text-xs flex-[0.4]' />
          <SimpleColumn name='N' className='text-xs flex-[0.4]' />
          <SimpleColumn name='P' className='text-xs flex-[0.4]' />
          <SimpleColumn name='S' className='text-xs flex-[0.4]' />
          <SimpleColumn name='CVP' className='text-xs flex-[0.5]' />
          <SimpleColumn name='EKG' className='text-xs flex-[0.5]' />
          <SimpleColumn name='Pupil Ki' className='text-xs flex-[0.5]' />
          <SimpleColumn name='Pupil Ka' className='text-xs flex-[0.5]' />
          <SimpleColumn name='Redaksi Ki' className='text-xs flex-[0.5]' />
          <SimpleColumn name='Redaksi Ka' className='text-xs flex-[0.5]' />
          <SimpleColumn name='Anggota Badan' className='text-xs flex-1' />
          <SimpleColumn name='Kesadaran' className='text-xs flex-1' />
          <SimpleColumn name='Sputum' className='text-xs flex-[0.7]' />
          <SimpleColumn name='Isi Cup' className='text-xs flex-[0.6]' />
          <SimpleColumn name='Keterangan' className='text-xs flex-1' isLast />
        </div>

        {res.length == 0 && <EmptyPlaceholder />}

        {res.map((item, index) => (
          <div className='flex' key={item.id_observasi ?? index}>
            <SimpleColumn
              name={item.jam?.substring(11, 19) || item.jam || '-'}
              className='text-xs flex-[0.5]'
            />
            <SimpleColumn name={item.t || '-'} className='text-xs flex-[0.4]' />
            <SimpleColumn name={item.n || '-'} className='text-xs flex-[0.4]' />
            <SimpleColumn name={item.p || '-'} className='text-xs flex-[0.4]' />
            <SimpleColumn name={item.s || '-'} className='text-xs flex-[0.4]' />
            <SimpleColumn
              name={item.cvp || '-'}
              className='text-xs flex-[0.5]'
            />
            <SimpleColumn
              name={item.ekg || '-'}
              className='text-xs flex-[0.5]'
            />
            <SimpleColumn
              name={item.pupil_kiri || '-'}
              className='text-xs flex-[0.5]'
            />
            <SimpleColumn
              name={item.pupil_kanan || '-'}
              className='text-xs flex-[0.5]'
            />
            <SimpleColumn
              name={item.redaksi_kiri || '-'}
              className='text-xs flex-[0.5]'
            />
            <SimpleColumn
              name={item.redaksi_kanan || '-'}
              className='text-xs flex-[0.5]'
            />
            <SimpleColumn
              name={item.anggota_badan || '-'}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={item.kesadaran || '-'}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={item.sputum_warna || '-'}
              className='text-xs flex-[0.7]'
            />
            <SimpleColumn
              name={item.isi_cup || '-'}
              className='text-xs flex-[0.6]'
            />
            <SimpleColumn
              name={item.keterangan || '-'}
              className='text-xs flex-1'
              isLast
            />
          </div>
        ))}
      </div>
    </LayoutBorderNo>
  )
}
