import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import Text from '@/components/text'
import { DiagnosaTable } from '@/features/pasien-pulang/rekam-medis/components/diagnosa-table'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import SignatureField from '../paps/singnature'
import EmptyDataSkriningGizi from './component/emty-data'
import NutrisiReport from './component/skrining-table'
import { getReportSkriningGizi } from './skrining-gizi'

interface ReportSkriningGiziProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportSkriningGizi({
  isReport = true,
  noreg = '',
}: ReportSkriningGiziProps) {
  const { pasien } = usePasienStore((state) => state)
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.reportSkriningGizi, noreg],
    queryFn: () => getReportSkriningGizi({ noreg }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : null

  console.log(res)

  if (isLoading) return <Loading />
  if (isError) return <Error />

  if (res == null) return <EmptyDataSkriningGizi />
  if (res?.tanggal == '') return <EmptyDataSkriningGizi />

  return (
    <LayoutBorderNo no={'RM RI'}>
      {isReport && <ReportHeader />}
      <h1 className='text-center text-black font-semibold mt-2'>
        FORMULIR SKRINING GIZI
      </h1>

      {pasien != null && (
        <InformasiPasien
          nama={pasien.nama_pasien}
          noRM={pasien.no_rm}
          tanggalLahir={pasien.tgl_lahir}
        />
      )}

      <div className='mx-4 my-4 p-2 mb-1 '>
        <DiagnosaTable data={res != null ? res.diagnosa : []} />{' '}
      </div>

      <div className='mx-4 my-4 p-2 mb-1 '>
        <div className='flex items-start justify-items-start'>
          <div>
            <Text
              kStyle='min-w-[100px] pb-2'
              k='BB'
              v={res?.skrining.bb + ' kg'}
            />
            <Text
              kStyle='min-w-[100px] pb-2'
              k='ULNA'
              v={res?.skrining.ulna + ' cm'}
            />
          </div>
          <div className='min-w-[100px]'></div>
          <div>
            <Text
              kStyle='min-w-[100px] pb-2'
              k='TB'
              v={res?.skrining.tb + ' cm'}
            />
            <Text
              kStyle='min-w-[100px] pb-2'
              k='LLA'
              v={res?.skrining.lla + ' cm'}
            />
          </div>

          <div className='min-w-[100px]'></div>
          <div>
            <Text
              kStyle='min-w-[100px] pb-2'
              k='IMT'
              v={res?.skrining.imt + ' Kg/m2'}
            />
            <Text
              kStyle='min-w-[100px] pb-2'
              k='BBI'
              v={res?.skrining.bbi + ' kg'}
            />
          </div>
        </div>
      </div>

      <div>
        <NutrisiReport data={res} />
      </div>

      <div className='flex justify-center text-sm'>
        <SignatureField
          title='Ahli Gizi'
          imageUrl={
            import.meta.env.VITE_BASE_API_URL_RME +
            '/app/images/asuhan_gizi/' +
            res?.ttd_ahli_gizi
          }
          name={res?.nama_ahli_gizi}
        />
      </div>
    </LayoutBorderNo>
  )
}
