import { SimpleColumn } from '@/components/simple-column'
import { AsesmenPerawat } from '@/models/asesmen-rajal'

const TableFlaccRajal = ({ data }: { data: AsesmenPerawat }) => {
  return (
    <div className='border border-black p-2 mb-1'>
      <p className='text-xs font-semibold'>{'Skala FLACC Untuk Anak < 6'}</p>
      {/* Table */}
      {/* Header */}
      <div className='flex mt-4'>
        <SimpleColumn name='Asesmen' className='border-b-0 text-xs flex-1' />
        <SimpleColumn name='0' className='border-b-0 text-xs flex-1' />
        <SimpleColumn name='1' className='border-b-0 text-xs flex-1' />
        <SimpleColumn name='2' className='border-b-0 text-xs flex-1' />
        <SimpleColumn
          isLast
          name='Nilai'
          className='border-b-0 text-xs flex-1'
        />
      </div>
      {/* Header */}

      {/* Body */}
      <Item
        n1='Wajah'
        n2='Tersenyum / Tidak ada expresi khusus'
        n3='Terkadang menangis / menarik diri'
        n4='Sering menggetarkan dagu dan mengatupkan rahang'
        n5={`${data.flacc_wajah}`}
      />
      <Item
        n1='Kaki'
        n2='Gerakan normal / relaksasi'
        n3='Tidak tenang / tegang'
        n4='Kaki dibuat untuk menendang / menarik diri'
        n5={`${data.flacc_kaki}`}
      />
      <Item
        n1='Aktivitas'
        n2='Tidur, posisi normal, mudah bergerak'
        n3='Gerakan menggeliat, berguling, kaku'
        n4='Melekungkan punggung / kaku/ menghentak'
        n5={`${data.flacc_aktifitas}`}
      />
      <Item
        n1='Menangis'
        n2='Tidak Menangis (bangun / tidur)'
        n3='Mengerang, merengek-rengek'
        n4='Menangis terus-menerus, terhisak, menjerit'
        n5={`${data.flacc_aktifitas}`}
      />
      <Item
        n1='Bersuara'
        n2='Bersuara normal, tenang'
        n3='Tenang bila dipeluk, digendong atau diajak berbicara'
        n4='Sulit menenangkan'
        n5={`${data.flacc_bersuara}`}
      />
      <div className='border border-black p-2'>
        <p className='text-center text-xs'>Total Skor : {data.flacc_total}</p>
      </div>
      <div className='p-4 flex justify-between'>
        <div className='flex gap-4'>
          <p className='text-xs'>Skala</p>

          <div>
            <p className='text-xs'>0 = Nyaman</p>
            <p className='text-xs'>1 - 3 = Kurang Nyaman</p>
          </div>
        </div>
        <div>
          <p className='text-xs'>4 - 6 = Nyeri Sedang</p>
          <p className='text-xs'>7 - 10 = Nyeri Berat</p>
        </div>
      </div>
      {/* Body */}
    </div>
  )
}

export default TableFlaccRajal

const Item = ({
  n1,
  n2,
  n3,
  n4,
  n5,
}: {
  n1?: string
  n2?: string
  n3?: string
  n4?: string
  n5?: string
}) => {
  return (
    <div className='flex boder border-b-black'>
      <SimpleColumn name={n1} className='border-b-0 text-xs flex-1' />
      <SimpleColumn name={n2} className='border-b-0 text-xs flex-1' />
      <SimpleColumn name={n3} className='border-b-0 text-xs flex-1' />
      <SimpleColumn name={n4} className='border-b-0 text-xs flex-1' />
      <SimpleColumn isLast name={n5} className='border-b-0 text-xs flex-1' />
    </div>
  )
}
