// import type { Skor, SkriningGizi } from '@/types/skrining-gizi'
import { Skor, SkriningGizi } from '../skrining-gizi'

interface NutrisiReportProps {
  /** Data skrining gizi pasien dari API */
  data: SkriningGizi
}

const getActiveScore = (items: Skor[]): number | string =>
  items.find((i) => i.is_active)?.skor ?? '-'

function SkorRow({ item }: { item: Skor }) {
  return (
    <tr className={item.is_active ? 'bg-green-100' : 'bg-white'}>
      <td className='border border-gray-400 px-3 py-2 text-sm'>
        {item.deskripsi}
      </td>
      <td className='border border-gray-400 px-3 py-2 text-center w-24'>
        <span className='inline-block bg-gray-200 rounded px-4 py-1 text-sm font-medium w-10 text-center'>
          {item.skor}
        </span>
      </td>
    </tr>
  )
}

function SkorTable({ items }: { items: Skor[] }) {
  return (
    <table className='w-full border-collapse'>
      <tbody>
        {items.map((item, i) => (
          <SkorRow key={i} item={item} />
        ))}
      </tbody>
    </table>
  )
}

export default function NutrisiReport({ data }: NutrisiReportProps) {
  if (!data) return null

  const sections: { no: number; items: Skor[] }[] = [
    { no: 1, items: data.skor_imt },
    { no: 2, items: data.skor_bb },
    { no: 3, items: data.skor_penyakit_akut },
  ]

  return (
    <div className='p-6 w-full text-sm font-sans'>
      <table className='w-full border-collapse border border-gray-400 text-sm'>
        <thead>
          <tr className='bg-gray-100'>
            <th className='border border-gray-400 px-3 py-2 text-center text-xs tracking-widest font-semibold w-12'>
              NO.
            </th>
            <th className='border border-gray-400 px-3 py-2 text-center text-xs tracking-widest font-semibold'>
              KATEGORI
            </th>
            <th className='border border-gray-400 px-3 py-2 text-center text-xs tracking-widest font-semibold w-24'>
              SKOR
            </th>
            <th className='border border-gray-400 px-3 py-2 text-center text-xs tracking-widest font-semibold w-32'>
              HASIL
            </th>
          </tr>
        </thead>
        <tbody>
          {sections.map(({ no, items }) => (
            <tr key={no}>
              <td className='border border-gray-400 px-3 py-2 align-top font-semibold'>
                {no}
              </td>
              <td className='border border-gray-400 p-0 align-top' colSpan={2}>
                <SkorTable items={items} />
              </td>
              <td className='border border-gray-400 px-4 text-center align-middle'>
                <span className='text-3xl font-bold'>
                  {getActiveScore(items)}
                </span>
              </td>
            </tr>
          ))}

          <tr className='bg-gray-100'>
            <td
              colSpan={2}
              className='border border-gray-400 px-3 py-3 text-center text-xs tracking-widest font-semibold'
            >
              JUMLAH KESELURUHAN.
            </td>
            <td
              colSpan={2}
              className='border border-gray-400 px-4 py-3 text-center'
            >
              <span className='text-3xl font-bold'>
                {data.total_skor ?? '-'}
              </span>
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  )
}
