import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import { SimpleColumn } from '@/components/simple-column'
import { getDoubleCheckHighAlert } from '@/services/double-check'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDateTime } from '@/utils/formatDate'

interface ReportDoubleCheckHighAlertProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

function checkMark(value: boolean) {
  return value ? '✓' : '-'
}

export default function ReportDoubleCheckHighAlert({
  isReport = false,
  noreg = '',
  no,
}: ReportDoubleCheckHighAlertProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.doubleCheck, noreg],
    queryFn: () => getDoubleCheckHighAlert(noreg),
    enabled: !!noreg,
  })

  const res = Array.isArray(data?.response) ? data.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          FORMULIR DOUBLE CHECK HIGH ALERT MEDICATIONS
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='flex mt-4'>
          <SimpleColumn name='No' className='text-xs flex-[0.3]' />
          <SimpleColumn name='Nama Obat' className='text-xs flex-[1.4]' />
          <SimpleColumn name='Benar Pasien' className='text-xs flex-[0.8]' />
          <SimpleColumn name='Benar Obat' className='text-xs flex-[0.8]' />
          <SimpleColumn name='Benar Dosis' className='text-xs flex-[0.8]' />
          <SimpleColumn name='Benar Cara' className='text-xs flex-[0.8]' />
          <SimpleColumn name='Benar Waktu' className='text-xs flex-[0.8]' />
          <SimpleColumn name='Benar Informasi' className='text-xs flex-[0.9]' />
          <SimpleColumn
            name='Benar Dokumentasi'
            className='text-xs flex-[0.9]'
          />
          <SimpleColumn name='Keterangan' className='text-xs flex-1' />
          <SimpleColumn name='Perawat Pemberi' className='text-xs flex-1' />
          <SimpleColumn name='Perawat Verifikasi' className='text-xs flex-1' />
          <SimpleColumn name='Waktu' className='text-xs flex-1' isLast />
        </div>

        {res.length == 0 && <EmptyPlaceholder />}

        {res.map((item, index) => (
          <div className='flex' key={item.id_double_check ?? index}>
            <SimpleColumn
              name={`${index + 1}`}
              className='text-xs flex-[0.3]'
            />
            <SimpleColumn
              name={item.nama_obat || '-'}
              className='text-xs flex-[1.4]'
            />
            <SimpleColumn
              name={checkMark(item.pasien_pemberi)}
              className='text-xs flex-[0.8]'
            />
            <SimpleColumn
              name={checkMark(item.obat_pemberi)}
              className='text-xs flex-[0.8]'
            />
            <SimpleColumn
              name={checkMark(item.dosis_pemberi)}
              className='text-xs flex-[0.8]'
            />
            <SimpleColumn
              name={checkMark(item.cara_pemberi)}
              className='text-xs flex-[0.8]'
            />
            <SimpleColumn
              name={checkMark(item.waktu_pemberi)}
              className='text-xs flex-[0.8]'
            />
            <SimpleColumn
              name={checkMark(item.informasi_pemberi)}
              className='text-xs flex-[0.9]'
            />
            <SimpleColumn
              name={checkMark(item.dokumentasi_pemberi)}
              className='text-xs flex-[0.9]'
            />
            <SimpleColumn
              name={item.keterangan || '-'}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={item.perawat_pemberi || item.user?.nama || '-'}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={item.verify_nama || '-'}
              className='text-xs flex-1'
            />
            <SimpleColumn
              name={formatDateTime(item.insert_dttm)}
              className='text-xs flex-1'
              isLast
            />
          </div>
        ))}
      </div>
    </LayoutBorderNo>
  )
}
