// Converts JSON strings to/from your types
export class Convert {
  public static toPonek(json: string): Ponek {
    return JSON.parse(json)
  }

  public static ponekToJson(value: Ponek): string {
    return JSON.stringify(value)
  }
}

const getPonek = async ({
  noreg,
  id,
}: {
  noreg: string
  id: string
}): Promise<Response<Ponek>> => {
  const response = await post(`/v4/ponek/get`, {
    no_reg: noreg,
    id: id,
  })

  return response.data
}

export { getPonek }
