import React from 'react'

/**
 * Interface untuk struktur data Skala Risiko Jatuh
 * Berdasarkan sumber data JSON yang Anda berikan
 */
interface RisikoJatuhData {
  noreg?: string
  umur?: string
  jenis_kelamin?: string
  diagnosa?: string
  gangguan_kognitif?: string
  faktor_lingkungan?: string
  respon_lingkungan?: string
  penggunaan_obat_obatan?: string
  skor?: number
}

interface RisikoJatuhProps {
  data: RisikoJatuhData
}

const RisikoJatuhTable: React.FC<RisikoJatuhProps> = ({ data }) => {
  // Helper untuk merender baris tabel dengan border hitam tegas
  const Row = ({
    label,
    value,
  }: {
    label: string
    value?: string | number
  }) => (
    <tr className='border-b border-black last:border-b-0'>
      <td className='border-r border-black p-2 w-1/3 font-normal text-[11px] md:text-xs uppercase leading-tight'>
        {label}
      </td>
      <td className='p-2 text-[11px] md:text-xs leading-relaxed whitespace-pre-wrap'>
        {value || ''}
      </td>
    </tr>
  )

  return (
    <div className='w-full border border-black bg-white overflow-hidden shadow-sm mb-10'>
      <table className='w-full border-collapse'>
        <thead>
          {/* Header Abu-abu sesuai estetika tabel parameter sebelumnya */}
          <tr className='bg-gray-100 border-b border-black text-xs md:text-sm font-bold uppercase'>
            <th className='border-r border-black p-3 w-1/3 text-center tracking-[0.2em]'>
              PARAMETER
            </th>
            <th className='p-3 text-center tracking-[0.2em]'>KRITERIA</th>
          </tr>
        </thead>
        <tbody>
          <Row label='Umur' value={data.umur} />
          <Row label='Jenis Kelamin' value={data.jenis_kelamin} />
          <Row label='Diagnosis' value={data.diagnosa} />
          <Row label='Gangguan Kognitif' value={data.gangguan_kognitif} />
          <Row label='Faktor Lingkungan' value={data.faktor_lingkungan} />
          <Row
            label='Respon Terhadap Operasi/Obat Penenang/Efek Anastesia'
            value={data.respon_lingkungan}
          />
          <Row label='Penggunaan Obat' value={data.penggunaan_obat_obatan} />

          {/* Baris SKOR sesuai Screenshot 2026-05-05 at 12.00.41.png */}
          <tr className='border-t border-black font-bold uppercase text-xs md:text-sm'>
            <td className='border-r border-black p-3 bg-white'>SKOR</td>
            <td className='p-3 bg-white text-base md:text-lg'>
              {data.skor ?? 0}
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  )
}

export default RisikoJatuhTable
