import type { TriaseLaporan } from '@/models/triase.model'
import type { Response } from '@/type'

import { post } from './api-2'

const getTriase = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<TriaseLaporan>> => {
  const response = await post('/v2/triase/get', { noreg })

  return response.data
}

export { getTriase }
