import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import { formatTanggalIndonesia } from '@/components/date/tgl-indo'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
// import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { getReportCpptDanSbar } from '@/services/cppt'
import { useAuthStore } from '@/store/auth.store'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { SimpleColumnPpa } from './component/simple-column'
import { SimpleColumnTtd } from './component/simple-column-ttd'

interface CPPTDANSBARProps {
  isReport?: boolean
  no_reg?: string
}

export function CPPTDanSBAR({
  isReport = true,
  no_reg = '',
}: CPPTDANSBARProps) {
  const { pasien } = usePasienStore((state) => state)
  const { user } = useAuthStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.pasien.cppt.report],
    queryFn: () => getReportCpptDanSbar(no_reg),
  })

  const result = data?.response != null ? data?.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no='RM.RI'>
      <div className='p-2'>
        <h1 className='text-center text-black font-semibold mb-4'>
          CATATAN PERKEMBANGAN PASIEN TERINTEGRASI
        </h1>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div>
          <div className='flex text-xs'>
            <SimpleColumn head name='Tanggal & Jam' className='w-[100px]' />
            <SimpleColumn
              head
              name='Professional Pemberi Asuhan'
              className='flex-[0.5]'
            />
            <SimpleColumn head name='Hasil Asesmen' className='flex-1' />
            <SimpleColumn head name='Instruksi PPA' className='flex-[0.5]' />
            <SimpleColumn
              head
              name='Verifikasi DPJP'
              isLast={isReport || pasien?.bagian !== user?.bagian}
              className='flex-[0.5]'
            />
            {!isReport && pasien?.bagian === user?.bagian && (
              <SimpleColumn head name='Action' isLast className='w-[100px]' />
            )}
          </div>

          {result.length > 0 &&
            result.map((item) => (
              <div className='flex text-xs' key={item.id_cppt}>
                <SimpleColumn
                  name={formatTanggalIndonesia(item.waktu)}
                  className='w-[100px]'
                />
                <SimpleColumnPpa
                  hasQR
                  className='flex-[0.5]'
                  kelompok={item.kelompok.toUpperCase()}
                  name={item.nama_perawat}
                  bagian={item.nama_bagian}
                />
                <SimpleColumn
                  isChild={
                    <>
                      {item.metode != 'sbar' ? (
                        <>
                          <Item k='S' value={item.subjektif} />
                          <Item k='O' value={item.objektif} />
                          <Item k='A' value={item.asesmen} />
                          <Item k='P' value={item.plan} />

                          {item.id_handover != '' && (
                            <>
                              <div className='flex flex-col items-center justify-center gap-2'>
                                <Item k='Handover ke' value={item.hand_over} />
                                <QRCode
                                  value={item.id_handover}
                                  className='h-[50px] w-[50px]'
                                />
                                <p>({item.id_handover})</p>
                                <div className='w-[150px] border-t border-black' />
                                <Item
                                  k='diverifikasi'
                                  value={item.tanggal_verifikasi}
                                />
                              </div>
                            </>
                          )}
                        </>
                      ) : (
                        <>
                          <Item k='S' value={item.subjektif} />
                          <Item k='O' value={item.objektif} />
                          <Item k='A' value={item.asesmen} />
                          <Item k='P' value={item.plan} />
                        </>
                      )}
                    </>
                  }
                  className='justify-start items-start flex-1'
                  className2='text-left'
                />
                <SimpleColumn
                  name={item.instruksi_ppa}
                  className='flex-[0.5]'
                />
                {item.verifikasi_dpjp != '' ? (
                  <SimpleColumnTtd
                    name={item.dpjp}
                    imageUrl={item.ttd_dokter}
                    isLast={isReport}
                    className='flex-[0.5]'
                  />
                ) : (
                  <SimpleColumn name='' isLast className='flex-[0.5]' />
                )}
              </div>
            ))}
          {/* Body */}
        </div>
      </div>
      {/* Content */}
    </LayoutBorderNo>
  )
}

const Item = ({ k, value }: { k: string; value: string }) => {
  return (
    <span className='flex flex-shrink-0 gap-1'>
      <strong>{k}</strong> :{' '}
      <p className='text-xs text-black text-left'>{value}</p>
    </span>
  )
}
