import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border_no'
import Loading from '@/components/loading'
import { ReportHeader } from '@/components/report-header'
import Text from '@/components/text'
import { getPersetujuanHiv } from '@/services/persetujuan-hiv'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDateTime } from '@/utils/formatDate'

interface ReportPersetujuanHivProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export default function ReportPersetujuanHiv({
  isReport = false,
  noreg = '',
  no,
}: ReportPersetujuanHivProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.persetujuanHiv,
      noreg,
      pasien?.no_rm,
    ],
    queryFn: () => getPersetujuanHiv({ no_reg: noreg, no_rm: pasien!.no_rm }),
    enabled: !!noreg && !!pasien?.no_rm,
  })

  const res = data?.response

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return <EmptyPlaceholder />

  return (
    <LayoutBorderNo no={no}>
      {isReport && <ReportHeader />}

      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-2'>
          PERSETUJUAN PEMERIKSAAN HIV
        </h1>

        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            tanggalLahir={pasien.tgl_lahir}
            jk={pasien.jenis_kelamin}
          />
        )}

        <div className='border border-black my-2 p-2'>
          <p className='font-semibold'>YANG BERTANDA TANGAN</p>
          <Text kStyle='min-w-[250px]' k='Nama' v={res.bertanda_tangan?.nama} />
          <Text
            kStyle='min-w-[250px]'
            k='Alamat'
            v={res.bertanda_tangan?.alamat}
          />
        </div>

        <div className='border border-black my-2 p-2'>
          <p className='font-semibold'>PASIEN</p>
          <Text kStyle='min-w-[250px]' k='Nama' v={res.pasien?.nama} />
          <Text
            kStyle='min-w-[250px]'
            k='Tanggal Lahir'
            v={formatDateTime(res.pasien?.tgl_lahir)}
          />
          <Text kStyle='min-w-[250px]' k='No. RM' v={res.pasien?.no_rm} />
          <Text
            kStyle='min-w-[250px]'
            k='Jenis Kelamin'
            v={res.pasien?.jenis_kelamin}
          />
          <Text kStyle='min-w-[250px]' k='Alamat' v={res.pasien?.alamat} />
        </div>

        <div className='border border-black my-2 p-2'>
          <p className='font-semibold'>PERNYATAAN</p>
          <p className='mt-2'>
            Saya menyatakan telah menerima penjelasan mengenai pemeriksaan HIV
            dan memberikan persetujuan untuk dilakukan pemeriksaan sesuai
            prosedur yang berlaku.
          </p>
          <Text
            kStyle='min-w-[250px]'
            k='Tanggal'
            v={formatDateTime(res.tanggal)}
          />
        </div>

        <div className='grid grid-cols-3 gap-2 mt-4'>
          <div className='text-center'>
            <p className='font-semibold'>Yang Membuat Pernyataan</p>
            <div className='h-14' />
            <p>{res.bertanda_tangan?.nama || '-'}</p>
          </div>
          <div className='text-center'>
            <p className='font-semibold'>Perawat</p>
            <div className='h-14' />
            <p>{res.nama_perawat || '-'}</p>
          </div>
          <div className='text-center'>
            <p className='font-semibold'>Petugas Laboratorium</p>
            <div className='h-14' />
            <p>{res.nama_petugas_labor || '-'}</p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}
