import { SimpleColumn } from '@/components/simple-column'

import { AlergiMakan } from '../gizi_model'

interface AlergiTableProps {
  data: AlergiMakan[]
  onEdit?: (item: AlergiMakan) => void
  onDelete?: (diagnosa: string) => void
}

export function AlergiTable({ data }: AlergiTableProps) {
  if (data.length > 0) {
    return (
      <div className='mb-2'>
        <div className='flex'>
          <SimpleColumn
            head
            name='No.'
            className='w-[50px] p-1'
            className2='text-xs'
          />
          <SimpleColumn
            head
            name='Makanan'
            className='p-1 flex-1'
            className2='text-xs'
          />
          <SimpleColumn
            head
            name='Alergi'
            className='p-1 flex-1'
            className2='text-xs'
          />
        </div>
        {data != null &&
          data.length > 0 &&
          data.map((item, i) => (
            <div className='flex' key={i}>
              <SimpleColumn
                name={`${i + 1}`}
                className='w-[50px] p-1'
                className2='text-xs'
              />
              <SimpleColumn
                name={item.deskripsi}
                className='p-1 flex-1 items-start'
                className2='text-xs'
              />
              <SimpleColumn
                name={`${item.hasil}`}
                className='p-1 flex-1 items-start'
                className2='text-xs'
              />
            </div>
          ))}
      </div>
    )
  } else {
    return (
      <div className='mb-2'>
        <div className='flex'>
          <SimpleColumn
            head
            name='No.'
            className='w-[50px] p-1'
            className2='text-xs'
          />
          <SimpleColumn
            head
            name='Kode'
            className='p-1 flex-1'
            className2='text-xs'
          />
          <SimpleColumn
            head
            name='Deskripsi'
            className='p-1 flex-1'
            className2='text-xs'
          />
        </div>

        <div className='flex'>
          <SimpleColumn isLast name='Tidak ada diagnosa' className2='text-xs' />
        </div>
      </div>
    )
  }
}
