import type { Response } from '@/type'

import { get } from './api-2'

export interface ObatYangDicurigai {
  id: number
  nama_obat: string
  bentuk_sediaan: string
  rute: string
  aturan_pakai: string
  tanggal_mulai: string
  tanggal_akhir: string
  keterangan: string
}

export interface EfekSampingObatData {
  penyakit_utama: string
  reaksi_eso: string
  penyakit_kondisi_menyertai: string
  hamil: string
  suku: string
  bb: string
  pekerjaan: string
  tanggal_eso: string
  bentuk_eso: string
  data_laboratorium: string
  reaksi_obat_eso: string
  instruksi_dokter: string
  tanggal_kesudahan_eso: string
  hasil: string
  obat_yang_dicurigai: ObatYangDicurigai[]
}

export interface EfekSampingObat {
  id: number
  noreg: string
  efek_samping_obat: EfekSampingObatData
  user: string
  insert_dttm: string
}

const getEfekSampingObat = async ({
  no_reg,
  kd_bagian,
}: {
  no_reg: string
  kd_bagian: string
}): Promise<Response<EfekSampingObat>> => {
  const params = { no_reg, kd_bagian }
  const response = await get('/v1/efek-samping-obat/get', params, params)

  return response.data
}

export { getEfekSampingObat }
